type CloudflarePipelinesFieldTypeType =
  | { type: 'int32' }
  | { type: 'int64' }
  | { type: 'float32' }
  | { type: 'float64' }
  | { type: 'bool' }
  | { type: 'string' }
  | { type: 'binary' }
