type EmailAuthInspectErrorType = { code: string; details?: string; domain: string; message: string }

const EmailAuthSpfTreeSchema: z.ZodType<EmailAuthSpfTreeType> = z
  .lazy(() =>
    z
      .object({
        components: z
          .array(EmailAuthSpfComponentSchema)
          .openapi({ description: 'Parsed SPF components (mechanisms)' }),
        domain: z
          .string()
          .openapi({ description: 'Domain being inspected', example: 'example.com' }),
        errors: z
          .array(EmailAuthInspectErrorSchema)
          .exactOptional()
          .openapi({
            description:
              'All errors encountered during inspection, collected from the entire tree.\nThis includes errors from nested includes at any depth, providing a quick\noverview of all issues without needing to traverse the nested structure.\nEach error includes a `domain` field to identify where it occurred.\nEmpty array if no errors (omitted from JSON when empty).\n',
            example: [],
          }),
        record: z
          .string()
          .openapi({
            description: 'Raw SPF record content',
            example: 'v=spf1 ip4:203.0.113.1 include:spf.example.com -all',
          }),
        total_lookups: z
          .int()
          .openapi({
            description: 'Total number of DNS lookups performed across all includes',
            example: 2,
          }),
      })
      .openapi({
        description: 'Recursive SPF inspection tree\n',
        required: ['domain', 'record', 'total_lookups', 'components'],
      }),
  )
  .openapi('EmailAuthSpfTree')

type EmailAuthSpfResultType =
  | 'pass'
  | 'neutral'
  | 'fail'
  | 'soft_fail'
  | 'none'
  | 'temp_error'
  | 'perm_error'

const EmailAuthSpfResultSchema: z.ZodType<EmailAuthSpfResultType> = z
  .enum(['pass', 'neutral', 'fail', 'soft_fail', 'none', 'temp_error', 'perm_error'])
  .openapi({ description: 'SPF mechanism result qualifier' })
  .openapi('EmailAuthSpfResult')

type EmailAuthSpfComponentType = {
  lookup_count: number
  nested?: z.infer<typeof EmailAuthSpfTreeSchema>
  result: z.infer<typeof EmailAuthSpfResultSchema>
  type: 'ALL' | 'A' | 'MX' | 'IP4' | 'IP6' | 'EXISTS' | 'INCLUDE' | 'PTR' | 'REDIRECT'
  value: string
}

const EmailAuthSpfComponentSchema: z.ZodType<EmailAuthSpfComponentType> = z
  .lazy(() =>
    z
      .object({
        lookup_count: z
          .int()
          .openapi({
            description:
              'Number of DNS lookups this component requires (per RFC 7208).\n- MX, A, EXISTS, INCLUDE, REDIRECT, PTR: 1\n- IP4, IP6, ALL: 0\n',
            example: 0,
          }),
        nested: EmailAuthSpfTreeSchema.exactOptional().openapi({
          description:
            'Nested SPF tree for INCLUDE or REDIRECT mechanisms.\nOnly present for INCLUDE/REDIRECT components.\n',
        }),
        result: EmailAuthSpfResultSchema,
        type: z
          .enum(['ALL', 'A', 'MX', 'IP4', 'IP6', 'EXISTS', 'INCLUDE', 'PTR', 'REDIRECT'])
          .openapi({ description: 'Component type (UPPERCASE)', example: 'IP4' }),
        value: z
          .string()
          .openapi({
            description:
              'Component value with qualifier prefix.\nFor IP4/IP6, stores just the IP address (no "ip4:" or "ip6:" prefix).\nExamples: "203.0.113.1", "203.0.113.0/24", "2001:db8::1/64", "-all", "~mx:example.com", "include:_spf.example.com"\n',
            example: '203.0.113.1',
          }),
      })
      .openapi({
        description:
          'A single SPF component (mechanism) in the inspection tree.\n\nThe `value` field includes the qualifier prefix (e.g., "-all", "~mx:example.com")\nto match the raw SPF record syntax. The qualifier is also available separately\nin the `result` field for programmatic access.\n',
        required: ['type', 'value', 'result', 'lookup_count'],
      }),
  )
  .openapi('EmailAuthSpfComponent')

const EmailAuthInspectErrorSchema: z.ZodType<EmailAuthInspectErrorType> = z
  .object({
    code: z
      .string()
      .openapi({
        description:
          'Error code. Known values:\n- `lookup_failed` — DNS TXT lookup failed\n- `spf_not_found` — no SPF record found\n- `invalid_spf` — record does not start with `v=spf1`\n- `invalid_domain` — PSL validation failed\n- `loop_detected` — include/redirect cycle detected\n- `invalid_mechanism` — unrecognised or malformed mechanism\n- `resource_limit_exceeded` — internal resource protection limits exceeded (recursion depth or query budget)\n- `max_lookups` — RFC 7208 10-lookup limit exceeded\n',
        example: 'max_lookups',
      }),
    details: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Additional error-specific details (optional).\n- For `invalid_domain` errors: the invalid domain string\n- For `invalid_mechanism` errors: the invalid mechanism text (e.g., "invalidmech123")\n- For `loop_detected` errors: the domain that caused the loop\n- For other error types: not present\n',
        example: 'invalid',
      }),
    domain: z
      .string()
      .openapi({ description: 'Domain where the error occurred', example: 'example.com' }),
    message: z
      .string()
      .openapi({
        description: 'Human-readable error message',
        example: 'RFC 7208 10-lookup limit exceeded',
      }),
  })
  .openapi({
    description: 'An error encountered during SPF inspection',
    required: ['code', 'message', 'domain'],
  })
  .openapi('EmailAuthInspectError')

type EmailAuthSpfTreeType = {
  components: z.infer<typeof EmailAuthSpfComponentSchema>[]
  domain: string
  errors?: z.infer<typeof EmailAuthInspectErrorSchema>[]
  record: string
  total_lookups: number
}

