const WorkersObservabilityFilterLeafSchema = z
  .object({
    key: z
      .string()
      .openapi({
        description:
          'Filter field name. Use verified keys from previous query results or the keys endpoint. Common keys include $metadata.service, $metadata.origin, $metadata.trigger, $metadata.message, and $metadata.error.',
      }),
    kind: z
      .literal('filter')
      .exactOptional()
      .openapi({
        description:
          "Discriminator for leaf filter nodes. Always 'filter' when present; may be omitted.",
      }),
    operation: z
      .enum([
        'includes',
        'not_includes',
        'starts_with',
        'ends_with',
        'regex',
        'exists',
        'is_null',
        'in',
        'not_in',
        'eq',
        'neq',
        'gt',
        'gte',
        'lt',
        'lte',
        '=',
        '!=',
        '>',
        '>=',
        '<',
        '<=',
        'INCLUDES',
        'DOES_NOT_INCLUDE',
        'MATCH_REGEX',
        'EXISTS',
        'DOES_NOT_EXIST',
        'IN',
        'NOT_IN',
        'STARTS_WITH',
        'ENDS_WITH',
      ])
      .openapi({
        description:
          'Comparison operator. String operators: includes, not_includes, starts_with, ends_with, regex. Existence: exists, is_null. Set membership: in, not_in (comma-separated values). Numeric: eq, neq, gt, gte, lt, lte.',
      }),
    type: z
      .enum(['string', 'number', 'boolean'])
      .openapi({
        description:
          'Data type of the filter field. Must match the actual type of the key being filtered.',
      }),
    value: z
      .union([z.string(), z.number(), z.boolean()])
      .exactOptional()
      .openapi({
        description:
          'Comparison value. Must match actual values in your data — verify with the values endpoint. Ensure the value type (string/number/boolean) matches the field type. String comparisons are case-sensitive. Regex uses RE2 syntax (no lookaheads/lookbehinds).',
      }),
  })
  .openapi({
    description:
      'A filter condition applied to query results. Use the keys and values endpoints to discover available fields and their values before constructing filters.',
    required: ['key', 'operation', 'type'],
  })
  .openapi('WorkersObservabilityFilterLeaf')

