const ApiShieldCredentialsJWTKeyECES384Schema = ApiShieldCredentialsJWTKeyCommonSchema.and(
  ApiShieldCredentialsJWTKeyECCommonSchema,
)
  .and(
    z
      .object({
        alg: z.literal('ES384').openapi({ description: 'Algorithm', 'x-auditable': true }),
        crv: z.literal('P-384').openapi({ description: 'Curve', 'x-auditable': true }),
      })
      .openapi({ required: ['alg', 'crv'] }),
  )
  .openapi({ description: 'JSON representation of an ES384 key' })
