const ApiShieldAuthIdCharacteristicJwtClaimSchema = z
  .object({
    name: z
      .string()
      .regex(/^(?<token_config_id>[a-z0-9\-]{32,36}):\$(?<json_path>.*?)$/)
      .max(128)
      .openapi({
        description:
          'Claim location expressed as `$(token_config_id):$(json_path)`, where `token_config_id` \nis the ID of the token configuration used in validating the JWT, and `json_path` is a RFC 9535 \nJSONPath (https://goessner.net/articles/JsonPath/, https://www.rfc-editor.org/rfc/rfc9535.html).\nThe JSONPath expression may be in dot or bracket notation, may only specify literal keys\nor array indexes, and must return a singleton value, which will be interpreted as a string.\n',
        example: 'e0de1a3a-8c2c-4f90-98d8-cbdf0a3f2cb5:$.foo.bar[0].baz',
        'x-auditable': true,
      }),
    type: z
      .literal('jwt')
      .openapi({ description: 'The type of characteristic.', example: 'jwt', 'x-auditable': true }),
  })
  .openapi({
    description: 'Auth ID Characteristic extracted from JWT Token Claims',
    required: ['type', 'name'],
  })
  .openapi('ApiShieldAuthIdCharacteristicJwtClaim')

const ApiShieldAuthIdCharacteristicsSchema = z
  .array(
    z.union([ApiShieldAuthIdCharacteristicSchema, ApiShieldAuthIdCharacteristicJwtClaimSchema]),
  )
  .max(10)
  .superRefine((items, ctx) => {
    const seen = new Map()
    for (const [i, val] of items.entries()) {
      const key = JSON.stringify(val)
      if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
      else seen.set(key, i)
    }
  })
  .openapi('ApiShieldAuthIdCharacteristics')

