const BrexExtensionEventFieldSchema = z
  .enum([
    'timestamp',
    'durationMs',
    'eventName',
    'action',
    'userEmail',
    'registrationId',
    'eventId',
    'policyId',
    'url',
    'matchedDlpProfiles',
    'inventoryExtensionId',
    'inventoryExtensionName',
    'inventoryExtensionVersion',
  ])
  .openapi('BrexExtensionEventField')

const BrexExtensionEventFilterOperatorSchema = z
  .enum([
    'eq',
    'neq',
    'in',
    'notIn',
    'contains',
    'notContains',
    'includes',
    'notIncludes',
    'gte',
    'lte',
  ])
  .openapi('BrexExtensionEventFilterOperator')

const BrexExtensionEventFilterSchema = z
  .object({
    field: BrexExtensionEventFieldSchema,
    op: BrexExtensionEventFilterOperatorSchema,
    value: z.xor([
      z.string().min(1).max(2048),
      z
        .preprocess(
          (val) =>
            typeof val === 'number' && Number.isSafeInteger(val)
              ? BigInt(val)
              : typeof val === 'string' && /^-?\d+$/.test(val)
                ? BigInt(val)
                : val,
          z.int64().min(0n),
        )
        .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
      z.array(z.string().min(1).max(2048)).min(1).max(20),
      z
        .array(
          z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64().min(0n),
            )
            .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
        )
        .min(1)
        .max(20),
    ]),
  })
  .openapi({ required: ['field', 'op', 'value'] })
  .openapi('BrexExtensionEventFilter')

