const BuildsCreateBuildRequestSchema = z
  .union([
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'commit_hash')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['commit_hash'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'branch')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['branch'] }),
  ])
  .and(
    z
      .object({
        branch: BuildsBranchSchema.exactOptional().openapi({
          description: 'Git branch name (required if commit_hash not provided)',
        }),
        commit_hash: BuildsCommitHashSchema.exactOptional().openapi({
          description: 'Git commit hash (required if branch not provided)',
        }),
        seed_repo: BuildsBuildSeedRepoInputSchema.exactOptional().openapi({
          description: 'Optional repository and file overrides used to seed this build.',
        }),
      })
      .openapi({ required: [] }),
  )
  .openapi('BuildsCreateBuildRequest')

