const CcRolloutStepRequestSchema = z
  .object({
    description: z.string().openapi({ description: 'Description of the rollout step.' }),
    step_size: z
      .object({
        percentage: z
          .int()
          .openapi({
            description: 'Percentage of instances affected in this step. Min 10% and Max 100%.',
          }),
      })
      .openapi({ required: ['percentage'] }),
  })
  .openapi({
    description: 'Steps defining the rollout process.',
    required: ['step_size', 'description'],
  })
  .openapi('CcRolloutStepRequest')

const CcContainersCreateApplicationRolloutRequestSchema = z
  .object({
    description: z.string().openapi({ description: 'Description of the rollout process.' }),
    kind: z
      .enum(['full_auto', 'full_manual'])
      .default('full_auto')
      .exactOptional()
      .openapi({
        description:
          'Kind of the rollout process. Defaults to "full_auto".\n - "full_auto": For rolling rollouts, starts progressing steps upon rollout creation. For new_instances rollouts, advances percentage targets automatically after target-version health is observed.\n - "full_manual": Requires manually progressing each step in the rollout using the UpdateRollout\'s action parameter.\n',
        'x-auditable': true,
      }),
    percentage: z
      .int()
      .min(0)
      .max(100)
      .exactOptional()
      .openapi({
        description:
          'Initial target version percentage (0-100). Version sync actively replaces instances to match.\nRequired when strategy is "new_instances" and kind is "full_manual". When strategy is "new_instances" and kind is "full_auto", omitted percentage starts at 10% or the smallest percentage that targets at least one instance. Unused for "rolling".\n',
        'x-auditable': true,
      }),
    step_percentage: z
      .union([
        z.literal(5),
        z.literal(10),
        z.literal(20),
        z.literal(25),
        z.literal(50),
        z.literal(100),
      ])
      .exactOptional()
      .openapi({
        description:
          'Percentage of rollout to increase in each step when "steps" is absent. Applicable values: 5, 10, 20, 25, 50, 100.\nThese create rollouts with 20, 10, 5, 4, 2, 1 steps respectively.\nOnly valid for "rolling" strategy.\n',
        'x-auditable': true,
      }),
    steps: z
      .array(CcRolloutStepRequestSchema)
      .exactOptional()
      .openapi({
        description:
          'Steps defining the rollout process, used when "step_percentage" is absent.\nSpecify only one of "step_percentage" or "steps" when creating a rollout.\n"steps" allow granular control over each step.\nOnly valid for "rolling" strategy.\n',
      }),
    strategy: z
      .enum(['rolling', 'new_instances'])
      .openapi({
        description:
          'Strategy used for the rollout.\n- "rolling": Step-based rollout with health gates. Actively replaces instances to reach each step\'s target percentage.\n- "new_instances": Percentage control over version distribution. Version sync actively replaces instances to match the configured percentage. The "full_auto" kind advances through fixed percentage targets after target-version health is observed.\n',
        'x-auditable': true,
      }),
    target_configuration: CcModifyUserDeploymentConfigurationSchema,
  })
  .openapi({
    description: 'Request body to create a new rollout for a scheduler-backed application.',
    required: ['target_configuration', 'strategy', 'description'],
  })
  .openapi('CcContainersCreateApplicationRolloutRequest')

