const CloudflareK2K2StreamCorsOptionsSchema = z
  .strictObject({
    origins: z
      .array(z.string().regex(/^(\*|https?:\/\/[^\/?#@]+)$/))
      .max(5)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          "Allows browser requests from these HTTP or HTTPS origins. Use a wildcard only as the sole origin. An empty list blocks cross-origin browser requests. Defaults to `['*']` when HTTP is enabled without stored origins.",
      }),
  })
  .openapi({ required: [] })
  .openapi('CloudflareK2K2StreamCorsOptions')

const CloudflareK2K2StreamHttpInputSchema = z
  .strictObject({
    authentication: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Indicates whether the HTTP endpoint requires an API token with K2 produce permission. When false, the endpoint accepts unauthenticated records. Defaults to true when HTTP is enabled without a stored value.',
      }),
    cors: CloudflareK2K2StreamCorsOptionsSchema.exactOptional(),
    enabled: z
      .boolean()
      .openapi({ description: 'Indicates whether the HTTP endpoint accepts records.' }),
  })
  .openapi({
    description:
      'Configures the HTTP endpoint. Disabling HTTP keeps `authentication` and `cors`, so enabling it again restores them.',
    required: ['enabled'],
  })
  .openapi('CloudflareK2K2StreamHttpInput')

const CloudflareK2K2StreamWorkerBindingInputSchema = z
  .xor([
    z
      .strictObject({
        enabled: z
          .literal(false)
          .openapi({
            description: 'Indicates whether Workers bindings can produce records to the stream.',
          }),
      })
      .openapi({ required: ['enabled'] }),
    z
      .strictObject({
        enabled: z
          .literal(true)
          .openapi({
            description: 'Indicates whether Workers bindings can produce records to the stream.',
          }),
      })
      .openapi({ required: ['enabled'] }),
  ])
  .openapi('CloudflareK2K2StreamWorkerBindingInput')

const CloudflareK2CreateK2StreamRequestSchema = z
  .strictObject({
    http: CloudflareK2K2StreamHttpInputSchema.default({ enabled: false }).exactOptional(),
    name: z
      .string()
      .regex(/^[a-zA-Z0-9_]+$/)
      .min(1)
      .max(128)
      .exactOptional()
      .openapi({ description: 'Specifies the name of the K2 stream.', example: 'my_k2_stream' }),
    retention_seconds: z
      .int()
      .min(3600)
      .max(2592000)
      .default(604800)
      .exactOptional()
      .openapi({
        description:
          'Sets the record retention period from 1 hour (3600 seconds) to 30 days (2592000 seconds), inclusive.',
      }),
    worker_binding: CloudflareK2K2StreamWorkerBindingInputSchema.default({
      enabled: true,
    }).exactOptional(),
  })
  .openapi({ required: [] })
  .refine(
    (val) =>
      !z
        .object({
          http: z
            .object({ enabled: z.literal(false) })
            .exactOptional()
            .openapi({ required: ['enabled'] }),
          worker_binding: z
            .object({ enabled: z.literal(false) })
            .openapi({ required: ['enabled'] }),
        })
        .openapi({ required: ['worker_binding'] })
        .safeParse(val).success,
  )
  .openapi({ required: ['name'] })
  .openapi('CloudflareK2CreateK2StreamRequest')

const CloudflareK2CreateK2SubscriptionRequestSchema = z
  .strictObject({
    name: z
      .string()
      .regex(/^[A-Za-z0-9_-]{1,128}$/)
      .openapi({
        description:
          'Specifies the name of the subscription. Creating a subscription with an existing name returns the existing subscription.',
        example: 'orders_processor',
      }),
    start_at: z
      .strictObject({
        type: z
          .enum(['earliest', 'latest'])
          .openapi({
            description: 'Starts at the oldest retained record or at the end of the stream.',
          }),
      })
      .openapi({ required: ['type'] }),
  })
  .openapi({ required: ['name', 'start_at'] })
  .openapi('CloudflareK2CreateK2SubscriptionRequest')

const CloudflareK2WorkersK2WorkerIdSchema = z
