const DnsSettingsNameserverSetIpCountSchema = z
  .preprocess(
    (val) =>
      typeof val === 'number' && Number.isSafeInteger(val)
        ? BigInt(val)
        : typeof val === 'string' && /^-?\d+$/.test(val)
          ? BigInt(val)
          : val,
    z.int64().min(1n).max(3n),
  )
  .default(1n)
  .openapi({
    type: 'integer',
    format: 'int64',
    minimum: 1,
    maximum: 3,
    default: 1,
    description:
      'Number of IPv4 addresses and number of IPv6 addresses to allocate to this nameserver. All nameservers in an Advanced nameserver set must use the same value.',
    example: 1,
    'x-auditable': true,
  })
  .openapi('DnsSettingsNameserverSetIpCount')

