const EmailSendingEmailBuilderSchema = z
  .union([
    z.object({}).openapi({ required: ['to'] }),
    z.object({}).openapi({ required: ['cc'] }),
    z.object({}).openapi({ required: ['bcc'] }),
  ])
  .and(
    z.union([
      z.object({}).openapi({ required: ['text'] }),
      z.object({}).openapi({ required: ['html'] }),
    ]),
  )
  .and(
    z
      .object({
        attachments: z
          .array(
            z
              .discriminatedUnion('disposition', [
                EmailSendingEmailInlineAttachmentSchema,
                EmailSendingEmailAttachmentSchema,
              ])
              .openapi({
                discriminator: {
                  mapping: {
                    attachment: '#/components/schemas/email-sending_EmailAttachment',
                    inline: '#/components/schemas/email-sending_EmailInlineAttachment',
                  },
                  propertyName: 'disposition',
                },
              }),
          )
          .exactOptional()
          .openapi({
            description: 'File attachments and inline images.',
            example: [
              {
                content: 'JVBERi0xLjQK...',
                disposition: 'attachment',
                filename: 'report.pdf',
                type: 'application/pdf',
              },
            ],
          }),
        bcc: z
          .xor([
            EmailSendingEmailAddressStringSchema,
            EmailSendingEmailAddressObjectSchema,
            z.array(
              z.xor([EmailSendingEmailAddressStringSchema, EmailSendingEmailAddressObjectSchema]),
            ),
          ])
          .exactOptional()
          .openapi({
            description:
              'Blind carbon copy recipient(s). Optional. A single email string, a named address object, or an array of either.',
            example: ['bcc-recipient@example.com'],
          }),
        cc: z
          .xor([
            EmailSendingEmailAddressStringSchema,
            EmailSendingEmailAddressObjectSchema,
            z.array(
              z.xor([EmailSendingEmailAddressStringSchema, EmailSendingEmailAddressObjectSchema]),
            ),
          ])
          .exactOptional()
          .openapi({
            description:
              'Carbon copy recipient(s). Optional. A single email string, a named address object, or an array of either.',
            example: ['cc-recipient@example.com'],
          }),
        from: z
          .xor([EmailSendingEmailAddressStringSchema, EmailSendingEmailAddressObjectSchema])
          .openapi({
            description:
              'Sender email address. Either a plain string or an object with address and name.',
            example: 'sender@example.com',
          }),
        headers: z
          .record(z.string(), z.string())
          .exactOptional()
          .openapi({
            description: 'Custom email headers as key-value pairs.',
            example: { 'X-Custom-Header': 'value' },
          }),
        html: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'HTML body of the email. Provide at least one of text or html (non-empty).',
            example: '<h1>Hello</h1><p>Please find your report attached.</p>',
          }),
        reply_to: z
          .xor([EmailSendingEmailAddressStringSchema, EmailSendingEmailAddressObjectSchema])
          .exactOptional()
          .openapi({
            description:
              'Reply-to address. Either a plain string or an object with address and name.',
            example: 'replies@example.com',
          }),
        subject: z
          .string()
          .openapi({ description: 'Email subject line.', example: 'Monthly Report' }),
        text: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Plain text body of the email. Provide at least one of text or html (non-empty).',
            example: 'Hello\n\nPlease find your report attached.',
          }),
        to: z
          .xor([
            EmailSendingEmailAddressStringSchema,
            EmailSendingEmailAddressObjectSchema,
            z.array(
              z.xor([EmailSendingEmailAddressStringSchema, EmailSendingEmailAddressObjectSchema]),
            ),
          ])
          .exactOptional()
          .openapi({
            description:
              'Recipient(s). Optional if cc or bcc is provided. A single email string, a named address object, or an array of either.',
            example: ['recipient@example.com'],
          }),
      })
      .openapi({ required: ['from', 'subject'] }),
  )
  .openapi({
    example: {
      attachments: [
        {
          content: 'JVBERi0xLjQK...',
          disposition: 'attachment',
          filename: 'report.pdf',
          type: 'application/pdf',
        },
      ],
      from: 'sender@example.com',
      html: '<h1>Hello</h1><p>Please find your report attached.</p>',
      subject: 'Monthly Report',
      text: 'Hello\n\nPlease find your report attached.',
      to: ['recipient@example.com'],
    },
    required: ['from', 'subject'],
  })
  .openapi('EmailSendingEmailBuilder')

