const FlagshipBaseConditionSchema = z
  .strictObject({
    attribute: z.string().min(1).max(64),
    operator: z.enum([
      'equals',
      'not_equals',
      'greater_than',
      'less_than',
      'greater_than_or_equals',
      'less_than_or_equals',
      'contains',
      'starts_with',
      'ends_with',
      'in',
      'not_in',
      'has',
      'not_has',
    ]),
    value: FlagshipJsonValueSchema,
  })
  .openapi({ required: ['attribute', 'operator', 'value'] })
  .openapi('FlagshipBaseCondition')

const FlagshipLogicalCondition4Schema = z
  .strictObject({
    clauses: z.array(FlagshipBaseConditionSchema).min(1),
    logical_operator: z.enum(['AND', 'OR']),
  })
  .openapi({ required: ['logical_operator', 'clauses'] })
  .openapi('FlagshipLogicalCondition4')

const FlagshipCondition4Schema = z
  .union([FlagshipBaseConditionSchema, FlagshipLogicalCondition4Schema])
  .openapi('FlagshipCondition4')

const FlagshipLogicalCondition3Schema = z
  .strictObject({
    clauses: z.array(FlagshipCondition4Schema).min(1),
    logical_operator: z.enum(['AND', 'OR']),
  })
  .openapi({ required: ['logical_operator', 'clauses'] })
  .openapi('FlagshipLogicalCondition3')

const FlagshipCondition3Schema = z
  .union([FlagshipBaseConditionSchema, FlagshipLogicalCondition3Schema])
  .openapi('FlagshipCondition3')

const FlagshipLogicalCondition2Schema = z
  .strictObject({
    clauses: z.array(FlagshipCondition3Schema).min(1),
    logical_operator: z.enum(['AND', 'OR']),
  })
  .openapi({ required: ['logical_operator', 'clauses'] })
  .openapi('FlagshipLogicalCondition2')

const FlagshipCondition2Schema = z
  .union([FlagshipBaseConditionSchema, FlagshipLogicalCondition2Schema])
  .openapi('FlagshipCondition2')

const FlagshipLogicalCondition1Schema = z
  .strictObject({
    clauses: z.array(FlagshipCondition2Schema).min(1),
    logical_operator: z.enum(['AND', 'OR']),
  })
  .openapi({ required: ['logical_operator', 'clauses'] })
  .openapi('FlagshipLogicalCondition1')

const FlagshipCondition1Schema = z
  .union([FlagshipBaseConditionSchema, FlagshipLogicalCondition1Schema])
  .openapi('FlagshipCondition1')

const FlagshipLogicalConditionSchema = z
  .strictObject({
    clauses: z.array(FlagshipCondition1Schema).min(1),
    logical_operator: z.enum(['AND', 'OR']),
  })
  .openapi({ required: ['logical_operator', 'clauses'] })
  .openapi('FlagshipLogicalCondition')

const FlagshipConditionSchema = z
  .union([FlagshipBaseConditionSchema, FlagshipLogicalConditionSchema])
  .openapi('FlagshipCondition')

const FlagshipRuleSchema = z
  .strictObject({
    conditions: z
      .array(FlagshipConditionSchema)
      .openapi({
        description:
          'Conditions the context must satisfy for this rule to match. An empty array matches all contexts.',
      }),
    priority: z
      .int()
      .min(1)
      .openapi({
        description:
          "Evaluation order: the API evaluates rules with lower numbers first. Must be unique across the flag's rules.",
      }),
    rollout: z
      .strictObject({
        attribute: z
          .string()
          .min(1)
          .max(64)
          .exactOptional()
          .openapi({
            description:
              'Context attribute used for sticky bucketing. Defaults to `targetingKey`. If absent at evaluation time, bucketing is random per request.',
          }),
        percentage: z
          .number()
          .min(0)
          .max(100)
          .multipleOf(0.01)
          .openapi({
            description:
              'Percentage of matching traffic (0–100, up to 2 decimal places) served this variation. For multi-way splits, use cumulative upper bounds across rules (e.g. 30, 70, 100).',
          }),
      })
      .exactOptional()
      .openapi({ required: ['percentage'] }),
    serve_variation: z
      .string()
      .min(1)
      .openapi({
        description:
          'Variation the API serves when this rule matches. Must be a key in `variations`.',
      }),
  })
  .openapi({ required: ['priority', 'conditions', 'serve_variation'] })
  .openapi('FlagshipRule')

const FlagshipFlagSchema = z
  .strictObject({
    default_variation: z
      .string()
      .min(1)
      .openapi({
        description:
          "Variation the API serves when the flag is off, or when it's on but no rule matches the context. Must be a key in `variations`.",
      }),
    description: z
      .string()
      .max(512)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Optional operator-facing description. It does not affect flag evaluation.',
      }),
    enabled: z
      .boolean()
      .openapi({
        description:
          'When false, the flag bypasses all rules and always serves `default_variation`.',
      }),
    key: z
      .string()
      .regex(/^[a-zA-Z0-9_-]+$/)
      .min(1)
      .max(64)
      .openapi({
        description:
          'Unique identifier for the flag within an app. Used in all evaluation and SDK calls.',
      }),
    metadata: z
      .record(z.string(), z.union([z.boolean(), z.string(), z.number()]))
      .refine((val) => Object.keys(val).length <= 32)
      .exactOptional()
      .openapi({
        description:
          'Key-value metadata associated with the flag. Returned only when the flag has metadata.',
      }),
    rules: z
      .array(FlagshipRuleSchema)
      .openapi({
        description:
          'Targeting rules evaluated in ascending `priority`; the first matching rule wins. An empty array means the flag always serves `default_variation`.',
      }),
    type: z
      .enum(['boolean', 'string', 'number', 'json'])
      .openapi({
        description: "Server-inferred value type shared by all of the flag's variations.",
        'x-stainless-terraform-configurability': 'computed_optional',
      }),
    updated_at: z.string().exactOptional(),
    updated_by: z.string().exactOptional(),
    variations: z
      .record(z.string(), FlagshipJsonValueSchema)
      .openapi({
        description:
          'Map of variation name to value. All values share the same type (boolean, string, number, or JSON object/array), and each serialized value stays within 10KB.',
      }),
  })
  .openapi({ required: ['key', 'type', 'default_variation', 'variations', 'rules', 'enabled'] })
  .openapi('FlagshipFlag')

const FlagshipChangelogEntrySchema = z
  .xor([
    z
      .object({ after: FlagshipFlagSchema, event: z.literal('create'), flag_key: z.string() })
      .openapi({ required: ['flag_key', 'event', 'after'] }),
    z
      .object({ after: FlagshipFlagSchema, event: z.literal('delete'), flag_key: z.string() })
      .openapi({ required: ['flag_key', 'event', 'after'] }),
    z
      .object({
        after: FlagshipFlagSchema,
        diff: z.record(
          z.string(),
          z
            .object({
              from: FlagshipJsonValueSchema.exactOptional(),
              to: FlagshipJsonValueSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        ),
        event: z.literal('update'),
        flag_key: z.string(),
      })
      .openapi({ required: ['flag_key', 'event', 'after', 'diff'] }),
  ])
  .openapi('FlagshipChangelogEntry')

const FlagshipChangelogPageSchema = z
  .array(FlagshipChangelogEntrySchema)
