const ManagedDefenseVulnerabilityDiscoveryCreateScanSchema = z
  .strictObject({
    repos: z
      .array(
        z
          .strictObject({
            branch: z
              .string()
              .regex(/^[A-Za-z0-9][A-Za-z0-9._\/-]*$/)
              .min(1)
              .max(255)
              .exactOptional()
              .openapi({
                description: "Branch to scan. Defaults to the repository's default branch.",
              }),
            hosts: z
              .array(
                z
                  .string()
                  .regex(/^[A-Za-z0-9][A-Za-z0-9.-]*[A-Za-z0-9]$/)
                  .min(1)
                  .max(253),
              )
              .min(1)
              .max(20)
              .superRefine((items, ctx) => {
                const seen = new Map()
                for (const [i, val] of items.entries()) {
                  const key = JSON.stringify(val)
                  if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                  else seen.set(key, i)
                }
              })
              .exactOptional()
              .openapi({
                description:
                  'Explicit hostname scopes. Every hostname must be authorized for this repository before review admission; rejected scopes return 422 and do not persist a scan request.',
              }),
            name: z
              .string()
              .regex(/^[a-zA-Z0-9_.-]+$/)
              .min(1)
              .max(255),
          })
          .openapi({ required: ['name'] }),
      )
      .min(1)
      .max(100)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({ description: 'Repository names must be unique within a request.' }),
    telemetry_window: ManagedDefenseVulnerabilityDiscoveryTelemetryWindowSchema.exactOptional(),
  })
  .openapi({ required: ['repos'] })
  .openapi('ManagedDefenseVulnerabilityDiscoveryCreateScan')

