const MconnTelemetryEventSchema = z
  .looseObject({
    k: z
      .enum([
        'Init',
        'Leave',
        'StartAttestation',
        'FinishAttestationSuccess',
        'FinishAttestationFailure',
        'StartRotateCryptKey',
        'FinishRotateCryptKeySuccess',
        'FinishRotateCryptKeyFailure',
        'StartRotatePki',
        'FinishRotatePkiSuccess',
        'FinishRotatePkiFailure',
        'StartUpgrade',
        'FinishUpgradeSuccess',
        'FinishUpgradeFailure',
        'BlessSlotSuccess',
        'BlessSlotPending',
        'BlessSlotFailure',
        'Reconcile',
        'ConfigureCloudflaredTunnel',
        'RekeyInstallBoth',
        'RekeyStart',
        'RekeyRestart',
        'RekeyAdvance',
        'RekeyComplete',
        'RekeyReset',
        'HaTransition',
        'HaError',
        'HaInit',
        'HaLeave',
      ])
      .openapi({ description: 'Event kind' }),
  })
  .openapi({
    description:
      'Event kind plus event-specific payload fields.\n\nEvent kinds:\n- `Init`: Initialized process\n- `Leave`: Stopped process\n- `StartAttestation`: Started attestation\n- `FinishAttestationSuccess`: Finished attestation\n- `FinishAttestationFailure`: Failed attestation\n- `StartRotateCryptKey`: Started crypt key rotation\n- `FinishRotateCryptKeySuccess`: Finished crypt key rotation\n- `FinishRotateCryptKeyFailure`: Failed crypt key rotation\n- `StartRotatePki`: Started PKI rotation\n- `FinishRotatePkiSuccess`: Finished PKI rotation\n- `FinishRotatePkiFailure`: Failed PKI rotation\n- `StartUpgrade`: Started upgrade\n- `FinishUpgradeSuccess`: Finished upgrade\n- `FinishUpgradeFailure`: Failed upgrade\n- `BlessSlotSuccess`: Blessed boot entry slot\n- `BlessSlotPending`: Boot entry slot is not yet blessed\n- `BlessSlotFailure`: Failed to bless boot entry slot\n- `Reconcile`: Reconciled\n- `ConfigureCloudflaredTunnel`: Configured Cloudflared tunnel\n- `RekeyInstallBoth`: Installed initial inbound and outbound keys\n- `RekeyStart`: Installed new inbound key, kept old outbound\n- `RekeyRestart`: Restarted in-progress rekey with newer key material\n- `RekeyAdvance`: Confirmed traffic on new inbound key, swapped outbound to new\n- `RekeyComplete`: Deleted old keys\n- `RekeyReset`: Deleted all keys after receiving an unexpected key\n- `HaTransition`: Completed HA state transition\n- `HaError`: Received unexpected HA error\n- `HaInit`: Initialized HA subsystem\n- `HaLeave`: Stopped HA subsystem',
    required: ['k'],
  })
  .openapi('MconnTelemetryEvent')

const MconnTelemetryRecordedEventSchema = z
  .object({
    e: MconnTelemetryEventSchema,
    n: z
      .number()
      .openapi({ description: 'Sequence number, used to order events with the same timestamp' }),
    t: z
      .number()
      .openapi({ description: 'Time the Event was recorded (seconds since the Unix epoch)' }),
    v: z.string().exactOptional().openapi({ description: 'Version' }),
  })
  .openapi({ description: 'Recorded Event', required: ['t', 'n', 'e'] })
  .openapi('MconnTelemetryRecordedEvent')

