const PostureApiMessagesSchema = z
  .array(
    z
      .object({
        code: z.int().min(1000).openapi({ description: 'Error or message code.', example: 1000 }),
        documentation_url: z
          .url()
          .exactOptional()
          .openapi({
            description: 'Link to relevant documentation.',
            example: 'https://developers.cloudflare.com/api/operations/list-findings',
          }),
        message: z
          .string()
          .openapi({
            description: 'Human-readable message.',
            example: 'Request processed successfully',
          }),
        source: z
          .object({
            pointer: z
              .string()
              .exactOptional()
              .openapi({
                description: 'JSON pointer to the source of the error.',
                example: '/data/attributes/name',
              }),
          })
          .exactOptional()
          .openapi({ required: [] }),
      })
      .openapi({ required: ['code', 'message'] }),
  )
  .superRefine((items, ctx) => {
    const seen = new Map()
    for (const [i, val] of items.entries()) {
      const key = JSON.stringify(val)
      if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
      else seen.set(key, i)
    }
  })
  .openapi({ example: [] })
  .openapi('PostureApiMessages')

