const R2RuleSchema = z
  .object({
    actions: z
      .array(R2R2ActionSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'Array of R2 object actions that will trigger notifications.',
        example: ['PutObject', 'CopyObject'],
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A description that can be used to identify the event notification rule after creation.',
        example: 'Notifications from source bucket to queue',
        'x-auditable': true,
      }),
    prefix: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Notifications will be sent only for objects with this prefix.',
        example: 'img/',
        'x-auditable': true,
      }),
    suffix: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Notifications will be sent only for objects with this suffix.',
        example: '.jpeg',
        'x-auditable': true,
      }),
  })
  .openapi({ required: ['actions'] })
  .openapi('R2Rule')

