const RealtimekitStorageConfigSchema = z
  .xor([
    z.object({ type: z.literal('gcs').exactOptional() }).openapi({ required: [] }),
    z
      .object({
        access_key: z.unknown().superRefine((val, ctx) => {
          if (typeof val === 'string') {
            if ([...val].length < 1) {
              ctx.addIssue({ code: 'custom' })
            }
          }
        }),
        region: z.unknown().superRefine((val, ctx) => {
          if (typeof val === 'string') {
            if ([...val].length < 1) {
              ctx.addIssue({ code: 'custom' })
            }
          }
        }),
        type: z.enum(['aws', 'azure', 'digitalocean']).exactOptional(),
      })
      .openapi({ required: ['access_key', 'region'] }),
    z
      .xor([
        z
          .object({ auth_method: z.literal('KEY').exactOptional() })
          .openapi({ required: ['private_key'] }),
        z
          .object({ auth_method: z.literal('PASSWORD').exactOptional() })
          .openapi({ required: ['password'] }),
      ])
      .openapi({ required: ['access_key', 'region', 'auth_method', 'username', 'host', 'port'] }),
  ])
  .nullable()
  .openapi({ required: ['type', 'bucket'], title: 'StorageConfig' })
  .openapi('RealtimekitStorageConfig')

