const RealtimekitStartReasonSchema = z
  .object({
    caller: z
      .object({
        name: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Name of the user who started the recording.',
            example: 'RealtimeKit_test',
          }),
        type: z
          .enum(['ORGANIZATION', 'USER'])
          .exactOptional()
          .openapi({
            description:
              'The type can be an App or a user. If the type is `user`, then only the `user_Id` and `name` are returned.',
          }),
        user_Id: z
          .uuid()
          .exactOptional()
          .openapi({
            description: 'The user ID of the person who started the recording.',
            example: 'd61f6956-e68f-4375-bf10-c38a704d1bec',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
    reason: z
      .enum(['API_CALL', 'RECORD_ON_START'])
      .exactOptional()
      .openapi({
        description:
          'Specifies if the recording was started using the "Start a Recording"API or using the parameter RECORD_ON_START in the "Create a meeting" API. \n\nIf the recording is initiated using the "RECORD_ON_START" parameter, the user details will not be populated.',
      }),
  })
  .openapi({ title: 'startReason', required: [] })
  .openapi('RealtimekitStartReason')

