const RegistrarApiSandboxRegistrationSchema = z
  .object({
    auto_renew: z
      .boolean()
      .openapi({
        description: 'Whether automatic renewal occurs before expiration.',
        example: true,
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'When the domain was registered. Present when the registration resource exists.',
        example: '2025-01-15T10:00:00Z',
      }),
    domain_name: RegistrarApiSandboxDomainNameSchema,
    expires_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description:
          'When the domain registration expires. Ready registrations include this value; only `registration_pending` and `transfer_pending` may return null.',
        example: '2026-01-15T10:00:00Z',
      }),
    locked: z
      .boolean()
      .openapi({ description: 'Whether the domain is locked for transfer.', example: true }),
    privacy_mode: z
      .enum(['off', 'redaction'])
      .openapi({
        description: 'Current WHOIS privacy mode for the registration.',
        example: 'redaction',
      }),
    status: z
      .enum([
        'active',
        'registration_pending',
        'transfer_pending',
        'expired',
        'suspended',
        'redemption_period',
        'pending_delete',
      ])
      .openapi({
        description:
          'Current registration status.\n- `active`: The domain operates with an active registration.\n- `registration_pending`: Registration remains in progress.\n- `transfer_pending`: Domain transfer is in progress.\n- `expired`: The domain registration expired.\n- `suspended`: The registry suspended the domain.\n- `redemption_period`: The domain entered the redemption grace period.\n- `pending_delete`: The registry scheduled the domain for deletion.\n',
        example: 'active',
      }),
  })
  .openapi({
    description:
      'A domain registration resource representing the current state of a registered domain.',
    required: [
      'domain_name',
      'status',
      'created_at',
      'expires_at',
      'auto_renew',
      'privacy_mode',
      'locked',
    ],
  })
  .openapi('RegistrarApiSandboxRegistration')

