const RegistrarApiSandboxWorkflowStatusSchema = z
  .object({
    completed: z
      .boolean()
      .openapi({
        description:
          'Indicates whether the workflow reached a terminal state. A `succeeded` or `failed` state returns `true`; `pending`, `in_progress`, `action_required`, and `blocked` return `false`.',
        example: false,
      }),
    context: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Provides workflow-specific data.\n\nFor domain-centric workflows, `context.domain_name` identifies the\nworkflow subject.\n',
      }),
    created_at: z.iso.datetime({ offset: true }),
    error: RegistrarApiSandboxWorkflowErrorSchema.nullable().exactOptional(),
    links: RegistrarApiSandboxWorkflowLinksSchema,
    state: z
      .enum(['pending', 'in_progress', 'action_required', 'blocked', 'succeeded', 'failed'])
      .openapi({
        description:
          "Describes the workflow lifecycle state.\n- `pending`: The workflow awaits processing.\n- `in_progress`: Processing started. Continue polling `links.self`.\n  An internal deadline limits the duration of this state.\n- `action_required`: The workflow pauses for user action. See\n  `context.action` for details. Stop automated polling until the user\n  completes the required action.\n- `blocked`: A third party, such as the domain extension's registry or\n  a losing registrar, prevents progress. Continue polling because the\n  block may resolve when the third party responds.\n- `succeeded`: Terminal state. The operation completed successfully.\n  `completed` equals `true`. For registrations,\n  `context.registration` contains the resulting registration resource.\n- `failed`: Terminal state. The operation failed. `completed` equals\n  `true`. See `error.code` and `error.message` for the reason. Require\n  user review before retrying.\n",
        example: 'in_progress',
      }),
    updated_at: z.iso.datetime({ offset: true }),
  })
  .openapi({
    description: 'Status of an async registration workflow.',
    required: ['state', 'completed', 'created_at', 'updated_at', 'links'],
  })
  .openapi('RegistrarApiSandboxWorkflowStatus')

