const RegistrarApiDomainSearchResultSchema = z
  .object({
    name: z
      .string()
      .openapi({
        description:
          'The fully qualified domain name (FQDN) in punycode format for internationalized domain names (IDNs).',
        example: 'example.com',
      }),
    pricing: RegistrarApiPricingRegistrationSchema.exactOptional(),
    reason: z
      .enum([
        'extension_not_supported_via_api',
        'extension_not_supported',
        'extension_disallows_registration',
        'domain_premium',
        'domain_unavailable',
      ])
      .exactOptional()
      .openapi({
        description:
          "Appears only when `registrable` is `false` and explains the advisory search result. Use POST /domain-check for authoritative status.\n- `extension_not_supported_via_api`: Cloudflare Registrar supports this extension in the dashboard but currently excludes it from programmatic registration through this API.\n- `extension_not_supported`: Cloudflare Registrar excludes this extension entirely.\n- `extension_disallows_registration`: The extension's registry temporarily or permanently freezes new registrations.\n- `domain_premium`: The domain carries premium pricing. This API currently supports standard registrations only.\n- `domain_unavailable`: The domain appears unavailable.",
        example: 'domain_unavailable',
      }),
    registrable: z
      .boolean()
      .openapi({
        description:
          'Indicates domain availability according to potentially stale, non-authoritative search data.\n- `true`: The domain appears available. Use POST /domain-check to confirm before registration.\n- `false`: Search results mark the domain ineligible for registration through this API. See `reason` for details.',
        example: true,
      }),
    tier: z
      .enum(['standard', 'premium'])
      .exactOptional()
      .openapi({
        description:
          'The pricing tier for this domain.\nA `registrable` value of `true` always\nincludes this field, which defaults to `standard` for most domains. A\n`registrable` value of `false` may omit it.\n- `standard`: Standard registry pricing.\n- `premium`: Premium domain with higher pricing from the registry.\n',
        example: 'standard',
      }),
  })
  .openapi({
    description:
      'Describes a single domain suggestion from the Search endpoint. Search results use non-authoritative data that may come from a cache. Use POST /domain-check to confirm real-time availability and pricing before registration.',
    required: ['name', 'registrable'],
  })
  .openapi('RegistrarApiDomainSearchResult')

