const RegistrarApiRegistrationContactsSchema = z
  .object({
    administrator: RegistrarApiRegistrationContactSchema.exactOptional().openapi({
      description:
        'Optional administrator contact. Accepted only when the extension\nschema includes this role. When the registry requires an omitted\ncontact, Cloudflare may derive it from `contacts.registrant`.\n',
    }),
    billing: RegistrarApiRegistrationContactSchema.exactOptional().openapi({
      description:
        'Optional billing contact. Accepted only when the extension schema\nincludes this role. When the registry requires an omitted contact,\nCloudflare may derive it from `contacts.registrant`.\n',
    }),
    registrant: RegistrarApiRegistrationContactSchema.exactOptional().openapi({
      description:
        "Optional registrant contact. If omitted, the account's default\naddress book entry is used instead.\n",
    }),
    technical: RegistrarApiRegistrationContactSchema.exactOptional().openapi({
      description:
        'Optional technical contact. Accepted only when the extension schema\nincludes this role. When the registry requires an omitted contact,\nCloudflare may derive it from `contacts.registrant`.\n',
    }),
  })
  .openapi({
    description:
      "Provides contact data for the registration request.\n\nThe per-extension schema from\n`GET /accounts/{account_id}/registrar/extensions/{extension}` defines the\naccepted contact roles. Every currently supported extension requires only\n`contacts.registrant` from API callers. Callers may provide additional roles\nsuch as `technical`, `administrator`, and `billing` when the extension\nschema includes them. When a registry requires an omitted role, Cloudflare\nmay derive that contact from `contacts.registrant`.\n\nWhen the request omits either the entire `contacts` object or\n`contacts.registrant`, the system uses the account's default address book\nentry as the registrant contact. The account owner must configure this\ndefault at `https://dash.cloudflare.com/{account_id}/domains/registrations`,\nwhere they can create or update the address book entry and accept the\nrequired agreement. Dashboard settings currently provide the only way to\nmanage address book entries.\n\nWithout either a default address book entry or a registrant contact, the\nregistration request fails validation.\n",
    required: [],
  })
  .openapi('RegistrarApiRegistrationContacts')

const RegistrarApiRegistrationCreateRequestSchema = z
  .object({
    acknowledgements: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Provides user acknowledgements for a specific extension or premium\nregistration flow. The extension registration schema from the\nextension discovery endpoint identifies the required keys.\n',
        example: { fees: { currency: 'USD', registration_fee: 10, renewal_fee: 10 } },
      }),
    auto_renew: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "Enable or disable automatic renewal. Defaults to `false` if omitted.\nSetting this field to `true` is an explicit opt-in authorizing\nCloudflare to charge the account's default payment method up to 30\ndays before domain expiry to renew the domain automatically.\nRenewal pricing may change over time based on registry pricing.\n",
        example: false,
      }),
    contact_extensions: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          "Provides registry-specific contact extension values for the registrant.\n`GET /accounts/{account_id}/registrar/extensions/{extension}` identifies\nthe required keys and allowed values for each extension in the\n`registration_schema.properties.contact_extensions` object.\n\nExamples include `.us` nexus fields, `.uk` registrant type fields,\nand `.ca` legal type fields. Omit this object when the extension's\nregistration schema excludes `contact_extensions`.\n",
        example: { application_purpose: 'P3', nexus_category: 'C11' },
      }),
    contacts: RegistrarApiRegistrationContactsSchema.exactOptional(),
    domain_name: RegistrarApiDomainNameSchema,
    privacy_mode: z
      .enum(['off', 'redaction'])
      .default('redaction')
      .exactOptional()
      .openapi({
        description:
          'Sets the WHOIS privacy mode for the registration. Defaults to `redaction`.\n- `off`: Disables WHOIS privacy.\n- `redaction`: Requests WHOIS redaction where the extension supports it.\n  Some extensions exclude privacy and redaction.\n',
        example: 'redaction',
      }),
    years: z
      .int()
      .min(1)
      .max(10)
      .exactOptional()
      .openapi({
        description:
          "Sets the registration term from 1 to 10 years. When omitted, this\nfield defaults to the registry's minimum registration period for the\nextension. Most extensions require 1 year, while some require longer\nminimum terms (e.g., `.ai` requires 2 years).\n\nEach registry may also enforce its own maximum registration term. A\nrequest above that maximum fails. When uncertain, omit this field to\nuse the default.\n",
        example: 1,
      }),
  })
  .openapi({ required: ['domain_name'] })
  .openapi('RegistrarApiRegistrationCreateRequest')

const RegistrarApiRegistrationUpdateRequestSchema = z
  .object({
    auto_renew: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "Enable or disable automatic renewal.\nSetting this field to `true` authorizes Cloudflare to charge the\naccount's default payment method up to 30 days before domain expiry\nto renew the domain automatically. Renewal pricing may change over\ntime based on registry pricing.\n",
        example: true,
      }),
  })
  .refine((val) => Object.keys(val).length >= 1)
  .openapi({
    description:
      'Request to update an existing domain registration.\n\nThis endpoint currently supports updating `auto_renew` only.\n',
    required: [],
  })
  .openapi('RegistrarApiRegistrationUpdateRequest')

const RegistrarApiTransferInCreateRequestSchema = z
  .object({
    auth_code: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The EPP/authorization code from your current registrar, base64-encoded\nper RFC 4648 §4. Obtain this from your current registrar's control panel.\nRequired for all extensions, except for UK.\n",
        example: 'bml4b3M+Pj5hcmNoLWxpbnV4',
      }),
    auto_renew: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Enable or disable automatic renewal after transfer. Defaults to `false` if omitted.\n',
        example: false,
      }),
    contact_extensions: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          "Registry-specific contact extension values for the registrant.\n`GET /accounts/{account_id}/registrar/extensions/{extension}` documents the\nrequired keys and allowed values for each extension in the\n`transfer_schema.properties.contact_extensions` object.\n\nExamples include `.us` nexus fields, `.uk` registrant type fields,\nand `.ca` legal type fields. Include this object only when the extension's\ntransfer schema defines `contact_extensions`.\n",
        example: { application_purpose: 'P3', nexus_category: 'C11' },
      }),
    contacts: RegistrarApiRegistrationContactsSchema.exactOptional(),
    privacy_mode: z
      .enum(['off', 'redaction'])
      .exactOptional()
      .openapi({
        description:
          "WHOIS privacy mode to apply after transfer completes. Defaults to\nthe extension's default privacy mode (typically `redaction`).\n",
        example: 'redaction',
      }),
  })
  .openapi({ required: [] })
  .openapi('RegistrarApiTransferInCreateRequest')

const RegistrarApiWorkflowErrorSchema = z
  .object({
    code: z
      .string()
      .openapi({
        description: 'Machine-readable error code identifying the failure reason.',
        example: 'registry_rejected',
      }),
    message: z
      .string()
      .openapi({
        description:
          'Human-readable explanation of the failure. May include registry-specific details.',
        example: 'Registry rejected the request.',
      }),
  })
  .openapi({
    description:
      'Provides error details when a workflow reaches the `failed` state. The workflow type (registration, update, etc.) and underlying registry response determine the specific codes and messages. Workflow error codes differ from immediate HTTP error `errors[].code` values in non-2xx responses. Surface `error.message` to the user for context.',
    required: ['code', 'message'],
  })
  .openapi('RegistrarApiWorkflowError')

const RegistrarApiWorkflowLinksSchema = z
  .object({
    resource: z
      .string()
      .exactOptional()
      .openapi({
        description: 'URL to the domain resource.',
        example: '/accounts/{account_id}/registrar/registrations/example.com',
      }),
    self: z
      .string()
      .openapi({
        description: 'URL to this status resource.',
        example: '/accounts/{account_id}/registrar/registrations/example.com/registration-status',
      }),
  })
  .openapi({ required: ['self'] })
  .openapi('RegistrarApiWorkflowLinks')

const RegistrarApiWorkflowStatusSchema = z
  .object({
    completed: z
      .boolean()
      .openapi({
        description:
          'Indicates whether the workflow reached a terminal state. A `succeeded` or `failed` state returns `true`; `pending`, `in_progress`, `action_required`, and `blocked` return `false`.',
        example: false,
      }),
    context: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Provides workflow-specific data.\n\nFor domain-centric workflows, `context.domain_name` identifies the\nworkflow subject.\n',
      }),
    created_at: z.iso.datetime({ offset: true }),
    error: RegistrarApiWorkflowErrorSchema.nullable().exactOptional(),
    links: RegistrarApiWorkflowLinksSchema,
    state: z
      .enum(['pending', 'in_progress', 'action_required', 'blocked', 'succeeded', 'failed'])
      .openapi({
        description:
          "Describes the workflow lifecycle state.\n- `pending`: The workflow awaits processing.\n- `in_progress`: Processing started. Continue polling `links.self`.\n  An internal deadline limits the duration of this state.\n- `action_required`: The workflow pauses for user action. See\n  `context.action` for details. Stop automated polling until the user\n  completes the required action.\n- `blocked`: A third party, such as the domain extension's registry or\n  a losing registrar, prevents progress. Continue polling because the\n  block may resolve when the third party responds.\n- `succeeded`: Terminal state. The operation completed successfully.\n  `completed` equals `true`. For registrations,\n  `context.registration` contains the resulting registration resource.\n- `failed`: Terminal state. The operation failed. `completed` equals\n  `true`. See `error.code` and `error.message` for the reason. Require\n  user review before retrying.\n",
        example: 'in_progress',
      }),
    updated_at: z.iso.datetime({ offset: true }),
  })
  .openapi({
    description: 'Status of an async registration workflow.',
    required: ['state', 'completed', 'created_at', 'updated_at', 'links'],
  })
  .openapi('RegistrarApiWorkflowStatus')

const RegistrarApiWorkflowStatusResponseSingleSchema = RegistrarApiApiResponseCommonSchema.and(
  z.object({ result: RegistrarApiWorkflowStatusSchema.exactOptional() }).openapi({ required: [] }),
).openapi('RegistrarApiWorkflowStatusResponseSingle')

