const TeamsDevicesVirtualNetworksSchema = z
  .object({
    allowed: z
      .array(z.uuid().openapi({ 'x-auditable': true }))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'List of virtual network IDs the device is allowed to access. When virtual_networks is set, at least one entry is required.',
        example: ['f174e90a-fafe-4643-bbbc-4a0ed4fc8415'],
      }),
    default: z
      .uuid()
      .openapi({
        description: 'The default virtual network ID. Must be included in the `allowed` list.',
        example: 'f174e90a-fafe-4643-bbbc-4a0ed4fc8415',
        'x-auditable': true,
      }),
  })
  .nullable()
  .openapi({
    description: 'Virtual network access settings for the device.',
    required: ['allowed', 'default'],
  })
  .openapi('TeamsDevicesVirtualNetworks')

