const TeamsDevicesKolideInputRequestSchema = z
  .object({
    auth_state: z
      .array(z.enum(['Good', 'Notified', 'Will Block', 'Blocked']).openapi({ 'x-auditable': true }))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'The set of Kolide device authentication states that pass the posture check. Device must match one of the specified states.',
        example: ['Good', 'Notified'],
      }),
    connection_id: z
      .string()
      .openapi({
        description: 'Posture Integration ID.',
        example: 'bc7cbfbb-600a-42e4-8a23-45b5e85f804f',
        'x-auditable': true,
      }),
    countOperator: z
      .enum(['<', '<=', '>', '>=', '=='])
      .exactOptional()
      .openapi({ description: 'Count Operator.', example: '>', 'x-auditable': true }),
    issue_count: z
      .string()
      .exactOptional()
      .openapi({ description: 'The Number of Issues.', example: '1', 'x-auditable': true }),
  })
  .openapi({ required: ['connection_id'], title: 'Kolide S2S Input' })
  .openapi('TeamsDevicesKolideInputRequest')

