const VulnScannerBolaHttpStatusRangeSchema = z
  .object({
    max: z
      .int()
      .min(0)
      .max(65535)
      .openapi({ description: 'Maximum (inclusive) status code of the range.' }),
    min: z
      .int()
      .min(0)
      .max(65535)
      .openapi({ description: 'Minimum (inclusive) status code of the range.' }),
  })
  .openapi({ description: 'Range of HTTP status codes.', required: ['min', 'max'] })
  .openapi('VulnScannerBolaHttpStatusRange')

const VulnScannerBolaAssertionKindSchema = z
  .xor([
    z
      .object({
        parameters: VulnScannerBolaHttpStatusRangeSchema,
        type: z.literal('http_status_within_range'),
      })
      .openapi({
        description:
          'Assert that an HTTP status code is within a range, e.g. to assert success for the 2xx range, or expected failure for the 4xx/5xx range.',
        required: ['type', 'parameters'],
      }),
  ])
  .openapi({ description: 'The kind of assertion to make.' })
  .openapi('VulnScannerBolaAssertionKind')

const VulnScannerBolaBodyResponseNotFoundSchema = z
  .object({ kind: z.literal('not_found') })
  .openapi({ description: 'No body was received.', required: ['kind'] })
  .openapi('VulnScannerBolaBodyResponseNotFound')

const VulnScannerBolaBodyResponseBytesSchema = z
  .object({ contents: z.string(), kind: z.literal('bytes'), truncated: z.boolean() })
  .openapi({
    description: 'Body received but unable to read as UTF-8. Raw bytes, base64-encoded.',
    required: ['kind', 'contents', 'truncated'],
  })
  .openapi('VulnScannerBolaBodyResponseBytes')

const VulnScannerBolaBodyResponseTextSchema = z
  .object({ contents: z.string(), kind: z.literal('text'), truncated: z.boolean() })
  .openapi({
    description: 'Body received as valid UTF-8 text but not valid JSON.',
    required: ['kind', 'contents', 'truncated'],
  })
  .openapi('VulnScannerBolaBodyResponseText')

const VulnScannerBolaBodyResponseJsonSchema = z
  .object({ contents: z.string(), kind: z.literal('json'), truncated: z.boolean() })
  .openapi({
    description: 'Body received as valid JSON.',
    required: ['kind', 'contents', 'truncated'],
  })
  .openapi('VulnScannerBolaBodyResponseJson')

const VulnScannerBolaBodyResponseSchema = z
  .discriminatedUnion('kind', [
    VulnScannerBolaBodyResponseNotFoundSchema,
    VulnScannerBolaBodyResponseBytesSchema,
    VulnScannerBolaBodyResponseTextSchema,
    VulnScannerBolaBodyResponseJsonSchema,
  ])
  .openapi({
    description: 'HTTP response body preview.',
    discriminator: {
      mapping: {
        bytes: '#/components/schemas/vuln_scanner_bola-body-response-bytes',
        json: '#/components/schemas/vuln_scanner_bola-body-response-json',
        not_found: '#/components/schemas/vuln_scanner_bola-body-response-not-found',
        text: '#/components/schemas/vuln_scanner_bola-body-response-text',
      },
      propertyName: 'kind',
    },
  })
  .openapi('VulnScannerBolaBodyResponse')

const VulnScannerBolaCredentialRoleSchema = z
  .enum(['owner', 'attacker'])
  .openapi({
    description:
      'Identifies the role a request was made with. The credential set governs this role. `owner` is the resource owner, `attacker` attempts to access resources.',
  })
