const WorkersObservabilityQuerySchema = z
  .object({
    adhoc: z.boolean().openapi({ description: "If the query wasn't explcitly saved" }),
    created: z.iso.datetime({ offset: true }),
    createdBy: z.string(),
    description: z.string().max(1000).nullable().openapi({ example: 'Query description' }),
    id: z.string(),
    name: z.string().min(1).max(250).openapi({ description: 'Query name' }),
    parameters: z
      .object({
        calculations: z
          .array(
            z
              .discriminatedUnion('operator', [
                z
                  .object({
                    alias: z.string().exactOptional(),
                    key: z.string().exactOptional(),
                    keyType: z.enum(['string', 'number', 'boolean']).exactOptional(),
                    operator: z.enum(['count', 'COUNT']),
                  })
                  .openapi({ required: ['operator'] }),
                z
                  .object({
                    alias: z.string().exactOptional(),
                    key: z.string().regex(/\S/),
                    keyType: z.enum(['string', 'number', 'boolean']).exactOptional(),
                    operator: z.enum([
                      'uniq',
                      'max',
                      'min',
                      'sum',
                      'avg',
                      'median',
                      'p001',
                      'p01',
                      'p05',
                      'p10',
                      'p25',
                      'p75',
                      'p90',
                      'p95',
                      'p99',
                      'p999',
                      'stddev',
                      'variance',
                      'COUNT_DISTINCT',
                      'MAX',
                      'MIN',
                      'SUM',
                      'AVG',
                      'MEDIAN',
                      'P001',
                      'P01',
                      'P05',
                      'P10',
                      'P25',
                      'P75',
                      'P90',
                      'P95',
                      'P99',
                      'P999',
                      'STDDEV',
                      'VARIANCE',
                    ]),
                  })
                  .openapi({ required: ['key', 'operator'] }),
              ])
              .openapi({ discriminator: { propertyName: 'operator' } }),
          )
          .exactOptional()
          .openapi({ description: 'Create Calculations to compute as part of the query.' }),
        datasets: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description: 'Set the Datasets to query. Leave it empty to query all the datasets.',
            example: [],
          }),
        filterCombination: z
          .enum(['and', 'or', 'AND', 'OR'])
          .exactOptional()
          .openapi({
            description: 'Set a Flag to describe how to combine the filters on the query.',
          }),
        filters: z
          .array(WorkersObservabilityFilterNodeSchema)
          .exactOptional()
          .openapi({
            description:
              "Configure the Filters to apply to the query. Supports nested groups via kind: 'group'.",
          }),
        groupBys: z
          .array(
            z
              .object({ type: z.enum(['string', 'number', 'boolean']), value: z.string() })
              .openapi({ required: ['type', 'value'] }),
          )
          .exactOptional()
          .openapi({ description: 'Define how to group the results of the query.' }),
        havings: z
          .array(
            z
              .object({
                key: z.string(),
                operation: z.enum(['eq', 'neq', 'gt', 'gte', 'lt', 'lte']),
                value: z.number(),
              })
              .openapi({ required: ['key', 'operation', 'value'] }),
          )
          .exactOptional()
          .openapi({
            description:
              'Configure the Having clauses that filter on calculations in the query result.',
          }),
        limit: z
          .int()
          .min(0)
          .max(100)
          .exactOptional()
          .openapi({
            description: 'Set a limit on the number of results / records returned by the query',
          }),
        needle: z
          .object({
            isRegex: z.boolean().exactOptional(),
            matchCase: z.boolean().exactOptional(),
            value: z.union([z.string(), z.number(), z.boolean()]).and(z.string().max(1000)),
          })
          .exactOptional()
          .openapi({
            description: 'Define an expression to search using full-text search.',
            required: ['value'],
          }),
        orderBy: z
          .object({
            order: z
              .enum(['asc', 'desc'])
              .exactOptional()
              .openapi({ description: 'Set the order of the results' }),
            value: z
              .string()
              .openapi({ description: 'Configure which Calculation to order the results by.' }),
          })
          .exactOptional()
          .openapi({
            description: 'Configure the order of the results returned by the query.',
            required: ['value'],
          }),
      })
      .openapi({ required: [] }),
    updated: z.iso.datetime({ offset: true }),
    updatedBy: z.string(),
  })
  .openapi({
    required: [
      'id',
      'name',
      'description',
      'adhoc',
      'parameters',
      'created',
      'createdBy',
      'updated',
      'updatedBy',
    ],
  })
  .openapi('WorkersObservabilityQuery')

