const WorkersPreviewDeploymentConfigSchema = z
  .object({
    annotations: z
      .object({
        'workers/commit_sha': z
          .string()
          .max(64)
          .exactOptional()
          .openapi({
            description:
              'Full commit SHA associated with the deployment, detected from the CI environment. Maximum 64 bytes.',
            example: '8b6aeb38455e2f92e170deb46313b90166ccc1e5',
            'x-auditable': true,
          }),
        'workers/message': z
          .string()
          .max(1000)
          .exactOptional()
          .openapi({
            description:
              'Human-readable message about the deployment. Truncated to 1000 bytes if longer.',
            example: 'Fixed bug.',
            'x-auditable': true,
          }),
        'workers/pull_request_number': z
          .string()
          .max(20)
          .exactOptional()
          .openapi({
            description:
              'Number of the pull or merge request associated with the deployment, detected from the CI environment. Maximum 20 bytes.',
            example: '14966',
            'x-auditable': true,
          }),
        'workers/pull_request_title': z
          .string()
          .max(512)
          .exactOptional()
          .openapi({
            description:
              'Title of the pull or merge request associated with the deployment, detected from the CI environment. Maximum 512 bytes.',
            example: 'Add a cool new feature',
            'x-auditable': true,
          }),
        'workers/pull_request_url': z
          .string()
          .max(512)
          .exactOptional()
          .openapi({
            description:
              'URL of the pull or merge request associated with the deployment, detected from the CI environment. Maximum 512 bytes.',
            example: 'https://github.com/cloudflare/workers-sdk/pull/14966',
            'x-auditable': true,
          }),
        'workers/repository_url': z
          .string()
          .max(512)
          .exactOptional()
          .openapi({
            description:
              'URL of the source repository the deployment was built from, detected from the CI environment. Maximum 512 bytes.',
            example: 'https://github.com/cloudflare/workers-sdk',
            'x-auditable': true,
          }),
        'workers/tag': z
          .string()
          .max(100)
          .exactOptional()
          .openapi({
            description: 'User-provided identifier for the deployment. Maximum 100 bytes.',
            example: 'v1.0.1',
            'x-auditable': true,
          }),
        'workers/triggered_by': z
          .string()
          .exactOptional()
          .openapi({
            description: 'Operation that triggered the creation of the deployment.',
            example: 'create_preview_deployment_api',
            readOnly: true,
            'x-auditable': true,
          }),
      })
      .exactOptional()
      .openapi({ description: 'Metadata about the deployment.', required: [] }),
    assets: WorkersAssetsSchema.exactOptional(),
    bindings: WorkersBindingsSchema.exactOptional().openapi({
      description:
        'Bindings attached to the deployment, as an array of objects\nthat each name themselves. An upload can send `env` or\n`bindings`, and a read returns both. Uploads to a Preview whose\nparent Worker has a previews base config must use `env`.\n',
    }),
    cache_options: WorkersCacheOptionsSchema.exactOptional(),
    compatibility_date: WorkersCompatibilityDateSchema.exactOptional(),
    compatibility_flags: WorkersCompatibilityFlagsSchema.exactOptional(),
    containers: WorkersContainersSchema.exactOptional(),
    env: WorkersEnvSchema.exactOptional().openapi({
      description:
        'Bindings attached to the deployment, keyed by binding name. An\nupload can send `env` or `bindings`, and a read returns both.\n',
    }),
    exports: WorkersExportsConfigMapSchema.exactOptional().openapi({
      description:
        'Declarative exports for the deployment, including Durable\nObject classes (with their `storage` backend) and named Worker\nentrypoints. On reads, tombstoned lifecycle entries are\nomitted, so only live exports (`created` and\n`expecting-transfer`) are returned. `exports` and `migrations`\nare mutually exclusive on upload.\n',
    }),
    limits: z
      .object({
        cpu_ms: z
          .int()
          .exactOptional()
          .openapi({ description: 'CPU time limit in milliseconds.', example: 50 }),
        subrequests: z
          .int()
          .exactOptional()
          .openapi({ description: 'Subrequest limit per request.', example: 1000 }),
      })
      .exactOptional()
      .openapi({
        description: 'Resource limits enforced at runtime.',
        'x-stainless-terraform-configurability': 'computed_optional',
        required: [],
      }),
    main_module: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The name of the module that exports a `fetch` handler. Multipart uploads reference the file part by filename.',
        example: 'index.js',
        'x-auditable': true,
      }),
    migrations: z
      .xor([WorkersSingleStepMigrationsSchema, WorkersMultipleStepMigrationsSchema])
      .exactOptional()
      .openapi({
        description:
          'Migrations for Durable Objects associated with the deployment. Migrations are applied when the deployment is created.',
      }),
    placement: WorkersPlacementInfoNoStatusSchema.exactOptional(),
    usage_model: z
      .enum(['standard', 'bundled', 'unbound'])
      .default('standard')
      .exactOptional()
      .openapi({
        description: 'Usage model for the deployment.',
        example: 'standard',
        deprecated: true,
        'x-auditable': true,
      }),
  })
  .openapi({
    description: 'Configuration shared by JSON and multipart preview deployment uploads.',
    required: [],
  })
  .openapi('WorkersPreviewDeploymentConfig')

