const WorkersExportsReconciliationScenarioSchema = z
  .enum([
    'code_class_not_in_exports',
    'provisioned_class_missing_from_config',
    'config_export_not_in_code',
    'config_references_nonexistent_class',
    'orphaned_provisioned_namespace',
    'storage_type_mismatch',
    'free_tier_requires_sqlite',
    'invalid_export',
    'tombstone_delete_class_still_in_code',
    'tombstone_delete_blocked_by_external_bindings',
    'tombstone_renamed_to_occupied',
    'transferred_pending_not_found',
    'transferred_target_missing',
    'transferred_target_mismatch',
    'phase_one_transfer_source_missing',
    'phase_one_transfer_source_namespace_missing',
    'phase_one_transfer_target_class_provisioned',
    'phase_one_transfer_after_commit_mismatch',
    'phase_one_transfer_duplicate',
    'phase_one_transfer_target_in_dispatch_namespace',
    'phase_one_transfer_source_in_dispatch_namespace',
    'transferred_source_in_dispatch_namespace',
    'transferred_target_in_dispatch_namespace',
    'container_undeclared_reference',
    'container_class_not_durable_object',
    'container_wiring_inconsistent',
    'container_multiple_durable_objects',
    'transfer_container_parity_mismatch',
    'transfer_container_parity_mismatch_on_commit',
    'tombstone_class_still_in_code',
    'stale_tombstone',
    'transfer_receive_already_applied',
    'transfer_receive_cleanup_complete',
  ])
  .openapi({
    description:
      'Stable, machine-readable tag identifying which reconciliation\nscenario produced an error, warning, or info entry. Clients may\nbranch on this value instead of parsing `message`.\n',
  })
  .openapi('WorkersExportsReconciliationScenario')

const WorkersExportsReconciliationInfoSchema = z
  .object({
    class: z.string().openapi({ description: 'The class name the info entry is about.' }),
    message: z.string().openapi({ description: 'Human-readable explanation.' }),
    namespace_id: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'The provisioned namespace the entry relates to, when applicable.' }),
    referencing_scripts: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Other Workers in the account that still bind to the affected\nclass. Advisory: while non-empty the tombstone is not yet safe\nto remove — redeploy these Workers with bindings re-pointed\nfirst.\n',
      }),
    scenario: WorkersExportsReconciliationScenarioSchema,
  })
  .openapi({
    description:
      'A non-blocking reconciliation info entry. Emitted for stale\ntombstones (a no-op on this deploy) and for tombstones applied\nwith the source class still in code (the supported zero-downtime\nrollout pattern).\n',
    required: ['class', 'scenario', 'message'],
  })
