const ZonesCiphersValueSchema = z
  .array(z.string())
  .superRefine((items, ctx) => {
    const seen = new Map()
    for (const [i, val] of items.entries()) {
      const key = JSON.stringify(val)
      if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
      else seen.set(key, i)
    }
  })
  .default([])
  .openapi({
    description: 'Value of the zone setting.',
    example: ['ECDHE-RSA-AES128-GCM-SHA256', 'AES128-SHA'],
  })
  .openapi('ZonesCiphersValue')

const ZonesCiphersSchema = ZonesBaseSchema.and(
  z
    .object({
      id: z
        .literal('ciphers')
        .exactOptional()
        .openapi({ description: 'ID of the zone setting.', example: 'ciphers' }),
      value: ZonesCiphersValueSchema.exactOptional(),
    })
    .openapi({ required: [] }),
)
  .default([])
  .openapi({
    description:
      'An allowlist of ciphers for TLS termination. These ciphers must be in the BoringSSL format.',
    title: 'Zone ciphers allowed for TLS termination',
  })
  .openapi('ZonesCiphers')

