const ZonesNameSchema = z
  .string()
  .regex(/^([a-zA-Z0-9][\-a-zA-Z0-9]*\.)+[\-a-zA-Z0-9]{2,20}$/)
  .max(253)
  .openapi({
    description:
      'The domain name. Per [RFC 1035](https://datatracker.ietf.org/doc/html/rfc1035#section-2.3.4) the overall zone name can be up to 253 characters, with each segment ("label") not exceeding 63 characters.',
    example: 'example.com',
    'x-auditable': true,
  })
  .openapi('ZonesName')

const ZonesPrioritySchema = z
  .int()
  .default(1)
  .openapi({
    description:
      'The priority of the rule, used to define which Page Rule is processed\nover another. A higher number indicates a higher priority. For example,\nif you have a catch-all Page Rule (rule A: `/images/*`) but want a more\nspecific Page Rule to take precedence (rule B: `/images/special/*`),\nspecify a higher priority for rule B so it overrides rule A.\n',
    'x-auditable': true,
  })
  .openapi('ZonesPriority')

const ZonesStatusSchema = z
  .enum(['active', 'disabled'])
  .default('disabled')
  .openapi({ description: 'The status of the Page Rule.', example: 'active', 'x-auditable': true })
  .openapi('ZonesStatus')

const ZonesStringConstraintSchema = z
  .object({
    operator: z
      .enum(['matches', 'contains', 'equals', 'not_equal', 'not_contain'])
      .default('contains')
      .openapi({
        description:
          "The matches operator can use asterisks and pipes as wildcard and 'or' operators.",
        'x-auditable': true,
      }),
    value: z
      .string()
      .openapi({ description: 'The value to apply the operator to.', 'x-auditable': true }),
  })
  .openapi({ description: 'String constraint.', required: ['operator', 'value'] })
  .openapi('ZonesStringConstraint')

const ZonesUrlTargetSchema = z
  .object({
    constraint: ZonesStringConstraintSchema.and(
      z
        .object({
          value: z
            .string()
            .regex(
              /^(https?:\/\/)?(([-a-zA-Z0-9*]*\.)+[-a-zA-Z0-9]{2,20})(:(8080|8443|443|80))?(\/[\S]+)?$/,
            )
            .exactOptional()
            .openapi({
              description:
                "The URL pattern to match against the current request. The pattern may contain up to four asterisks ('*') as placeholders.",
              example: '*example.com/images/*',
              'x-auditable': true,
            }),
        })
        .openapi({ required: [] }),
    )
      .exactOptional()
      .openapi({ description: 'The constraint of a target.' }),
    target: z
      .literal('url')
      .exactOptional()
      .openapi({
        description: 'A target based on the URL of the request.',
        example: 'url',
        'x-auditable': true,
      }),
  })
  .openapi({ description: 'URL target.', required: [] })
  .openapi('ZonesUrlTarget')

const ZonesTargetSchema = z
  .xor([ZonesUrlTargetSchema])
  .openapi({ description: 'A request condition target.', required: ['target', 'constraint'] })
  .openapi('ZonesTarget')

const ZonesTargetsSchema = z
  .array(ZonesTargetSchema)
  .openapi({
    description: 'The rule targets to evaluate on each request.',
    example: [
      { constraint: { operator: 'matches', value: '*example.com/images/*' }, target: 'url' },
    ],
    'x-stainless-skip': ['terraform'],
  })
  .openapi('ZonesTargets')

const ZonesPageRuleSchema = z
