export const getAccountsAccountIdAccessCertificatesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/access/certificates',
  tags: ['Access mTLS authentication'],
  summary: 'List mTLS certificates',
  description: 'Lists all mTLS root certificates.',
  operationId: 'access-mtls-authentication-list-mtls-certificates',
  request: {
    params: z.object({
      account_id: AccessIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/access_identifier' },
        },
      }),
    }),
    query: z.object({
      page: AccessPageParamsSchema,
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(1000),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of results per page.',
              type: 'integer',
              default: 50,
              maximum: 1000,
            },
            required: false,
          },
          description: 'Number of results per page.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List mTLS certificates response',
      content: { 'application/json': { schema: AccessResponseCollection_6Schema } },
    },
    '4XX': {
      description: 'List mTLS certificates response failure',
      content: { 'application/json': { schema: AccessApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

