export const patchAccountsAccountIdAiSearchNamespacesNamespaceInstancesIdRoute = createRoute({
  method: 'patch',
  path: '/accounts/{account_id}/ai-search/namespaces/{namespace}/instances/{id}',
  tags: ['AI Search Namespaces'],
  summary: 'Move an instance to a different namespace.',
  description:
    "Moves an instance from its current namespace to the specified target namespace. Use 'default' with --destination-namespace to move the instance back to the default namespace. Fails with 400 if the target namespace already has an instance with the same id (ids must be unique within a namespace — the same id can exist in different namespaces).",
  operationId: 'ai-search-move-instance',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            required: true,
            schema: { type: 'string', example: 'c3dc5f0b34a14ff8e1b3ec04895e1b22' },
          },
          example: 'c3dc5f0b34a14ff8e1b3ec04895e1b22',
        }),
      namespace: z
        .string()
        .openapi({
          param: {
            name: 'namespace',
            in: 'path',
            description: 'Current namespace of the instance.',
            required: true,
            schema: {
              description: 'Current namespace of the instance.',
              type: 'string',
              example: 'production',
            },
            'x-fern-parameter-name': 'source-namespace',
          },
          description: 'Current namespace of the instance.',
          example: 'production',
        }),
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            description: 'Instance id.',
            required: true,
            schema: { description: 'Instance id.', type: 'string', example: 'my-blog' },
            'x-fern-parameter-name': 'instance-id',
          },
          description: 'Instance id.',
          example: 'my-blog',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              new_namespace: z
                .string()
                .regex(/^[a-z0-9]([a-z0-9-]{0,26}[a-z0-9])?$/)
                .openapi({
                  description: 'Target namespace to move the instance into.',
                  example: 'staging',
                  'x-fern-property-name': 'destination-namespace',
                }),
            })
            .openapi({ required: ['new_namespace'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Instance moved.',
      content: {
        'application/json': {
          schema: z
            .object({ result: z.strictObject({}), success: z.literal(true) })
            .openapi({ required: ['success', 'result'] }),
        },
      },
    },
    400: {
      description: 'Ai search with this name already exist.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'errors'] }),
        },
      },
    },
    404: {
      description: 'Ai search not found.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'errors'] }),
        },
      },
    },
    409: {
      description:
        'Instance modified concurrently please retry move; Ai search instance deletion in progress.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z.union([
                  z
                    .object({ code: z.literal(7108), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                  z
                    .object({ code: z.literal(7124), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                ]),
              ),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'errors'] }),
        },
      },
      headers: z.object({
        'Retry-After': {
          description: 'Seconds to wait before retrying.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Seconds to wait before retrying.',
              param: { required: false },
              example: '10',
            }),
        },
      }),
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

