export const postAccountsAccountIdAiWebsearchRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/ai/websearch',
  tags: ['AI Gateway'],
  summary: 'Search the web through AI Gateway',
  description: 'Run a web search through a configured AI Gateway.',
  operationId: 'workers-ai-ai-gateway-web-search',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            required: true,
            schema: { type: 'string', example: '023e105f4ecef8ad9ca31a8372d0c353' },
          },
          example: '023e105f4ecef8ad9ca31a8372d0c353',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              byokAlias: z
                .string()
                .regex(/^[A-Za-z0-9_-]{1,64}$/)
                .exactOptional(),
              limit: z.int().min(1).max(10).exactOptional(),
              options: z
                .object({
                  gateway: z.object({ id: z.string().min(1) }).openapi({ required: ['id'] }),
                })
                .openapi({ required: ['gateway'] }),
              provider: z.string().min(1).max(1024).exactOptional(),
              query: z.string().min(1),
            })
            .openapi({ required: ['query', 'options'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Web search results',
      content: {
        'application/json': {
          schema: z
            .object({
              items: z.array(
                z
                  .object({
                    description: z.string().exactOptional(),
                    faviconUrl: z.url().exactOptional(),
                    imageUrl: z.url().exactOptional(),
                    lastModifiedDate: z.iso.datetime({ offset: true }).exactOptional(),
                    title: z.string(),
                    url: z.url(),
                  })
                  .openapi({ required: ['url', 'title'] }),
              ),
              metadata: z
                .object({ latencyMs: z.number(), query: z.string(), requestId: z.string() })
                .openapi({ required: ['query', 'requestId', 'latencyMs'] }),
            })
            .openapi({ required: ['items', 'metadata'] }),
        },
      },
    },
    400: {
      description: 'Invalid request or gateway configuration',
      content: {
        'application/json': {
          schema: z.union([
            z
              .object({
                errors: z.array(
                  z
                    .object({ code: z.number(), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                ),
                messages: z.array(z.any().nullable()),
                result: z.union([z.any().nullable(), z.object({}), z.any().nullable()]),
                success: z.literal(false),
              })
              .openapi({ required: ['success', 'errors', 'messages', 'result'] }),
            z
              .object({
                error: z
                  .object({
                    category: z.enum(['gateway', 'credential', 'provider', 'internal']),
                    code: z.string(),
                    gatewayRequestId: z.string(),
                    retryable: z.boolean(),
                    status: z.int(),
                  })
                  .openapi({
                    required: ['category', 'code', 'status', 'retryable', 'gatewayRequestId'],
                  }),
                ok: z.literal(false),
              })
              .openapi({ required: ['ok', 'error'] }),
          ]),
        },
      },
    },
    403: {
      description: 'Web search is not enabled',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({
                  category: z.enum(['gateway', 'credential', 'provider', 'internal']),
                  code: z.string(),
                  gatewayRequestId: z.string(),
                  retryable: z.boolean(),
                  status: z.int(),
                })
                .openapi({
                  required: ['category', 'code', 'status', 'retryable', 'gatewayRequestId'],
                }),
              ok: z.literal(false),
            })
            .openapi({ required: ['ok', 'error'] }),
        },
      },
    },
    502: {
      description: 'Web search provider failure',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({
                  category: z.enum(['gateway', 'credential', 'provider', 'internal']),
                  code: z.string(),
                  gatewayRequestId: z.string(),
                  retryable: z.boolean(),
                  status: z.int(),
                })
                .openapi({
                  required: ['category', 'code', 'status', 'retryable', 'gatewayRequestId'],
                }),
              ok: z.literal(false),
            })
            .openapi({ required: ['ok', 'error'] }),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

