export const getAccountsAccountIdAlertingV3HistoryRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/alerting/v3/history',
  tags: ['Notification History'],
  summary: 'List History',
  description:
    'Gets a list of history records for notifications sent to an account. The records are displayed for last `x` number of days based on the zone plan (free = 30, pro = 30, biz = 30, ent = 90).',
  operationId: 'notification-history-list-history',
  request: {
    params: z.object({
      account_id: AaaAccountIdSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/aaa_account-id' },
        },
      }),
    }),
    query: z.object({
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          AaaPerPageSchema.openapi({
            param: {
              name: 'per_page',
              in: 'query',
              schema: { $ref: '#/components/schemas/aaa_per_page' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      before: AaaBeforeSchema.openapi({
        param: {
          name: 'before',
          in: 'query',
          schema: { $ref: '#/components/schemas/aaa_before' },
          required: false,
        },
      }).exactOptional(),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'since',
            in: 'query',
            schema: {
              description:
                'Limit the returned results to history records newer than the specified date. This must be a timestamp that conforms to RFC3339.',
              type: 'string',
              format: 'date-time',
              example: '2022-05-19T20:29:58.679897Z',
            },
            required: false,
          },
          description:
            'Limit the returned results to history records newer than the specified date. This must be a timestamp that conforms to RFC3339.',
          example: '2022-05-19T20:29:58.679897Z',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List History response',
      content: {
        'application/json': { schema: AaaHistoryComponentsSchemasResponseCollectionSchema },
      },
    },
    '4XX': {
      description: 'List History response failure',
      content: {
        'application/json': {
          schema: AaaHistoryComponentsSchemasResponseCollectionSchema.and(
            AaaApiResponseCommonFailure_3Schema,
          ),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

