export const getAccountsAccountIdBotnetFeedAsnAsnIdDayReportRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/botnet_feed/asn/{asn_id}/day_report',
  tags: ['Botnet Threat Feed'],
  summary: 'Get daily report',
  description:
    'Gets all the data the botnet tracking database has for a given ASN registered to user account for given date. If no date is given, it will return results for the previous day.',
  operationId: 'botnet-threat-feed-get-day-report',
  request: {
    params: z.object({
      account_id: DosIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/dos_identifier' },
        },
      }),
      asn_id: z.preprocess(
        (val) =>
          typeof val === 'string' &&
          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
            ? Number(val)
            : val,
        DosAsnSchema.openapi({
          param: {
            name: 'asn_id',
            in: 'path',
            required: true,
            schema: { $ref: '#/components/schemas/dos_asn' },
          },
        }),
      ),
    }),
    query: z.object({
      date: DosTimestampSchema.openapi({
        param: {
          name: 'date',
          in: 'query',
          schema: { $ref: '#/components/schemas/dos_timestamp' },
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'Get botnet feed report for day',
      content: {
        'application/json': {
          schema: DosApiResponseCommonSchema.and(
            z
              .object({
                result: z
                  .object({
                    cidr: z.string().exactOptional().openapi({ example: '1.1.1.1/32' }),
                    date: z.iso
                      .datetime({ offset: true })
                      .exactOptional()
                      .openapi({ example: '2014-01-01T05:20:00.12345Z' }),
                    offense_count: z.int().exactOptional().openapi({ example: 1000 }),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Get botnet feed report for day response failure',
      content: { 'application/json': { schema: DosApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

