export const getAccountsAccountIdBrowserExtensionConfigInventoriesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/browser-extension/config/inventories',
  tags: ['Browser Extension Inventories'],
  summary: 'List browser extension inventories',
  description:
    'Returns the installed extension inventory for each registered browser\nextension device in the account. Each device reports its inventory\nperiodically; this endpoint returns the latest known snapshot per device.\n\nResults are paginated by cursor. Pass the `cursor` from a previous\nresponse to fetch the next page. `per_page` controls page size\n(default 50, max 200).\n',
  operationId: 'accounts-browser-extension-inventories-list',
  request: {
    params: z.object({ account_id: BrexAccountIdParamsSchema }),
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            description: 'Opaque cursor from a previous response to fetch the next page.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(200),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Number of results per page (default 50, max 200).',
            schema: { type: 'integer', default: 50, maximum: 200, minimum: 1 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Browser extension inventories response.',
      content: { 'application/json': { schema: BrexInventoriesResponseSchema } },
    },
    401: BrexUnauthorizedResponse,
    403: BrexForbiddenResponse,
    500: BrexInternalServerErrorResponse,
    503: BrexServiceUnavailableResponse,
  },
  security: [{ api_token: [] }],
})

