export const postAccountsAccountIdBulkSubscriptionsRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/bulk/subscriptions',
  tags: ['Account Subscriptions'],
  summary: 'Create Subscriptions',
  description: 'Creates multiple subscriptions for an account in a single request.',
  operationId: 'account-subscriptions-bulk-create-subscription',
  request: {
    params: z.object({
      account_id: BillSubsApiIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/bill-subs-api_identifier' },
        },
      }),
    }),
    query: z.object({
      idemp_key: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'idemp_key', in: 'query', schema: { type: 'string' }, required: false },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              coupon_code: z.string().exactOptional(),
              payment_hold_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({ type: 'integer', format: 'int64' }),
              subscriptions: z.array(BillSubsApiSubscriptionV2Schema).exactOptional(),
              user_is_on_session: z.boolean().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Create Subscriptions response',
      content: { 'application/json': { schema: BillSubsApiBulkAccountSubscriptionResponseSchema } },
    },
    '4XX': {
      description: 'Create Subscriptions response failure',
      content: { 'application/json': { schema: BillSubsApiApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

