export const postAccountsAccountIdCloudforceOneV2BrandProtectionQueriesQueryIdMatchesDomainIdDismissRoute =
  createRoute({
    method: 'post',
    path: '/accounts/{account_id}/cloudforce-one/v2/brand-protection/queries/{query_id}/matches/{domain_id}/dismiss',
    tags: ['Brand Protection'],
    summary: 'Dismiss a match',
    description:
      'Mark a specific domain as dismissed for a given query. Dismissals are per-query — dismissing a domain in one query does not affect other queries.',
    operationId: 'post_DismissMatch',
    request: {
      params: z.object({
        account_id: z
          .string()
          .min(1)
          .openapi({
            param: {
              name: 'account_id',
              in: 'path',
              required: true,
              schema: { type: 'string', minLength: 1 },
            },
          }),
        query_id: z
          .preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            z.int().positive(),
          )
          .openapi({
            param: {
              name: 'query_id',
              in: 'path',
              required: true,
              schema: { type: 'integer', exclusiveMinimum: true, minimum: 0 },
            },
          }),
        domain_id: z
          .preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            z.int().positive(),
          )
          .openapi({
            param: {
              name: 'domain_id',
              in: 'path',
              required: true,
              schema: { type: 'integer', exclusiveMinimum: true, minimum: 0 },
            },
          }),
      }),
    },
    responses: {
      200: {
        description: 'Match dismissed successfully',
        content: {
          'application/json': {
            schema: z
              .object({
                result: z
                  .object({ dismissed: z.boolean(), domain_id: z.int(), query_id: z.int() })
                  .openapi({ required: ['query_id', 'domain_id', 'dismissed'] }),
                success: z.boolean(),
              })
              .openapi({ required: ['success', 'result'] }),
          },
        },
      },
      '4XX': CloudforceOneEventsApiV4ClientErrorResponse,
    },
    security: [{ api_token: [] }],
  })

