export const putAccountsAccountIdCloudforceOneV2PriorityIntelligencePriorityIdRoute = createRoute({
  method: 'put',
  path: '/accounts/{account_id}/cloudforce-one/v2/priority-intelligence/{priority_id}',
  tags: ['Priority Intelligence Requirements'],
  summary: 'Update a priority intelligence requirement',
  description:
    'Updates a Priority Intelligence Requirement for the authenticated account. Changing the query increments its version; editing the requirement without saving a query marks the query stale. Activating a draft needs a free slot in the active PIR quota; setting `active` on a PIR the matcher paused resumes it without one.',
  operationId: 'put_PirUpdate',
  request: {
    params: z.object({
      account_id: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            required: true,
            schema: { type: 'string', minLength: 1 },
          },
        }),
      priority_id: z
        .uuid()
        .openapi({
          param: {
            name: 'priority_id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              confirm_query: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Write-only. `true` confirms the query still fits the requirement, clearing `query_stale` without changing the query or its version. Requires a query.',
                }),
              dataset_scope: z
                .xor([
                  z.strictObject({ type: z.literal('default') }).openapi({ required: ['type'] }),
                  z
                    .strictObject({
                      dataset_ids: z.array(z.uuid()).min(1).max(50),
                      type: z.literal('datasets'),
                    })
                    .openapi({ required: ['type', 'dataset_ids'] }),
                ])
                .exactOptional()
                .openapi({
                  description:
                    "`default`: every event dataset the account can read: Cloudforce One intelligence, datasets shared with the account, and the account's own datasets, such as Threat Signals. `datasets`: explicit dataset IDs. Analytics datasets are not matched. An active PIR can cover at most 50 datasets. Access is rechecked whenever the PIR is matched.",
                }),
              digest_interval_hours: z
                .union([z.literal(6), z.literal(12), z.literal(24)])
                .exactOptional()
                .openapi({
                  description:
                    'Hours between digests: 6, 12, or 24. Used only when `notification_mode` is `digest`.',
                }),
              intent: z
                .strictObject({
                  clauses: z
                    .array(
                      z
                        .strictObject({
                          actors: z.array(z.string().min(1).max(200)).max(20),
                          attacker_countries: z.array(z.string().min(1).max(200)).max(20),
                          categories: z.array(z.string().min(1).max(200)).max(20),
                          cves: z.array(z.string().min(1).max(200)).max(20),
                          keywords: z.array(z.string().min(1).max(200)).max(5),
                          target_countries: z.array(z.string().min(1).max(200)).max(20),
                          target_industries: z.array(z.string().min(1).max(200)).max(20),
                          techniques: z.array(z.string().min(1).max(200)).max(20),
                        })
                        .openapi({
                          required: [
                            'actors',
                            'attacker_countries',
                            'target_countries',
                            'target_industries',
                            'categories',
                            'techniques',
                            'cves',
                            'keywords',
                          ],
                        }),
                    )
                    .min(1)
                    .max(8),
                  indicators: z.array(z.string().min(1).max(200)).max(20),
                  unsupported_terms: z.array(z.string().min(1).max(200)).max(20),
                })
                .nullable()
                .exactOptional()
                .openapi({ required: ['clauses', 'indicators', 'unsupported_terms'] }),
              labels: z.array(z.string().max(100)).max(50).exactOptional(),
              model: z.string().min(1).max(200).nullable().exactOptional(),
              notification_mode: z
                .enum(['none', 'immediate', 'digest'])
                .exactOptional()
                .openapi({
                  description:
                    '`none` or `digest`. Notifications are opt-in. `immediate` is reserved and currently rejected.',
                }),
              priority: z.int().min(0).exactOptional(),
              query: z
                .strictObject({
                  branches: z
                    .array(
                      z
                        .array(
                          z.union([
                            z
                              .strictObject({
                                field: z.enum([
                                  'attacker',
                                  'attackerCountry',
                                  'category',
                                  'createdAt',
                                  'date',
                                  'event',
                                  'indicator',
                                  'indicatorType',
                                  'mitreAttack',
                                  'mitreCapec',
                                  'tags',
                                  'targetCountry',
                                  'targetIndustry',
                                  'tlp',
                                  'uuid',
                                ]),
                                op: z.enum([
                                  'equals',
                                  'not',
                                  'gt',
                                  'gte',
                                  'lt',
                                  'lte',
                                  'like',
                                  'contains',
                                  'startsWith',
                                  'endsWith',
                                  'find',
                                ]),
                                value: z.string().min(1).max(512),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                            z
                              .strictObject({
                                field: z.enum([
                                  'attacker',
                                  'attackerCountry',
                                  'category',
                                  'createdAt',
                                  'date',
                                  'event',
                                  'indicator',
                                  'indicatorType',
                                  'mitreAttack',
                                  'mitreCapec',
                                  'tags',
                                  'targetCountry',
                                  'targetIndustry',
                                  'tlp',
                                  'uuid',
                                ]),
                                op: z.literal('in'),
                                value: z.array(z.string().min(1).max(512)).min(1).max(100),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                            z
                              .strictObject({
                                field: z.literal('killChain'),
                                op: z.enum(['equals', 'not', 'gt', 'gte', 'lt', 'lte']),
                                value: z.union([
                                  z.number(),
                                  z.string().regex(/^-?(?:\d+\.?\d*|\.\d+)$/),
                                ]),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                            z
                              .strictObject({
                                field: z.literal('killChain'),
                                op: z.literal('in'),
                                value: z
                                  .array(
                                    z.union([
                                      z.number(),
                                      z.string().regex(/^-?(?:\d+\.?\d*|\.\d+)$/),
                                    ]),
                                  )
                                  .min(1)
                                  .max(100),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                            z
                              .strictObject({
                                field: z.literal('hasChildren'),
                                op: z.enum(['equals', 'not', 'gt', 'gte', 'lt', 'lte']),
                                value: z.union([
                                  z.boolean(),
                                  z.literal('true'),
                                  z.literal('false'),
                                  z.literal(1),
                                  z.literal(0),
                                  z.literal('1'),
                                  z.literal('0'),
                                ]),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                            z
                              .strictObject({
                                field: z.literal('hasChildren'),
                                op: z.literal('in'),
                                value: z
                                  .array(
                                    z.union([
                                      z.boolean(),
                                      z.literal('true'),
                                      z.literal('false'),
                                      z.literal(1),
                                      z.literal(0),
                                      z.literal('1'),
                                      z.literal('0'),
                                    ]),
                                  )
                                  .min(1)
                                  .max(100),
                              })
                              .openapi({ required: ['field', 'op', 'value'] }),
                          ]),
                        )
                        .min(1)
                        .max(10),
                    )
                    .min(1)
                    .max(8)
                    .openapi({
                      description:
                        'Event List `searchBranches`: filters within a branch are ANDed, branches are ORed.',
                    }),
                  version: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description:
                        'Ignored. Accepted so a PIR read from the API can be sent back unchanged.',
                    }),
                })
                .nullable()
                .exactOptional()
                .openapi({ required: ['branches'] }),
              query_source: z.enum(['generated', 'edited']).nullable().exactOptional(),
              requirement: z.string().min(1).max(4000).exactOptional(),
              status: z
                .enum(['draft', 'active'])
                .exactOptional()
                .openapi({
                  description:
                    '`draft`: not monitored. `active`: monitored, unless `pause_reason` is set. Setting `active` on a PIR with a `pause_reason` resumes it. Moving a PIR back to `draft` and activating it again starts matching afresh with a 30-day backfill.',
                }),
              title: z.string().min(1).max(200).nullable().exactOptional(),
              tlp: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: { description: 'PIR updated successfully' },
    400: { description: 'Invalid update, such as activating a PIR without a query' },
    403: { description: 'Account not entitled to activate PIRs' },
    404: { description: 'PIR not found' },
    409: { description: 'PIR was modified concurrently' },
    429: { description: 'Active PIR quota exceeded' },
  },
  security: [{ api_token: [] }],
})

