export const putAccountsAccountIdCloudforceOneV2ThreatSignalsFeedsFeedIdSkillsRoute = createRoute({
  method: 'put',
  path: '/accounts/{account_id}/cloudforce-one/v2/threat-signals/feeds/{feed_id}/skills',
  tags: ['Threat Signals'],
  summary: 'Set Threat Signals feed skills',
  description:
    'Replaces the ordered custom skills assigned to a Threat Signals feed. Requires a paid Threat Signals subscription.',
  operationId: 'rssFeedSkillsSet',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
      feed_id: z
        .uuid()
        .openapi({
          param: {
            name: 'feed_id',
            in: 'path',
            required: true,
            schema: {
              description: 'UUID of the Threat Signals feed',
              type: 'string',
              format: 'uuid',
            },
          },
          description: 'UUID of the Threat Signals feed',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              skill_ids: z
                .array(z.uuid())
                .max(20)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .openapi({
                  description:
                    "Ordered array of Custom Skill UUIDs (max 20). Replaces the feed's custom skill assignments. Free accounts cannot assign custom skills. Managed default skills are unaffected.",
                }),
            })
            .openapi({ required: ['skill_ids'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Threat Signals response.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(z.object({ message: z.string() }).openapi({ required: ['message'] })),
              messages: z.array(
                z
                  .object({
                    code: z.number().exactOptional(),
                    custom_feed_count: z
                      .int()
                      .min(0)
                      .exactOptional()
                      .openapi({
                        description: 'The current count of custom feeds for the account.',
                      }),
                    custom_feed_limit: z
                      .int()
                      .min(0)
                      .exactOptional()
                      .openapi({ description: 'The custom feed limit for the account.' }),
                    expected: z.string().exactOptional(),
                    message: z.string(),
                    path: z.array(z.string()).exactOptional(),
                    reason: z
                      .enum([
                        'threat_signals_feed_limit',
                        'free_custom_skills_disabled',
                        'free_skill_run_disabled',
                        'free_tier_reconciliation_in_progress',
                        'free_tier_reconciliation_failed',
                        'raw_content_expired',
                        'curated_visibility_changed',
                      ])
                      .exactOptional(),
                  })
                  .openapi({ required: ['message'] }),
              ),
              result: z
                .object({
                  feed_id: z.uuid(),
                  skills: z.array(
                    z
                      .object({
                        position: z.int().openapi({ description: 'Zero-based pipeline position.' }),
                        skill_id: z.string(),
                      })
                      .openapi({ required: ['skill_id', 'position'] }),
                  ),
                })
                .openapi({ required: ['feed_id', 'skills'] }),
              success: z.literal(true),
            })
            .openapi({ required: ['result', 'success', 'errors', 'messages'] }),
        },
      },
    },
    '4XX': CloudforceOneEventsApiV4ClientErrorResponse,
  },
  security: [{ api_token: [] }],
})

