export const getAccountsAccountIdD1DatabaseRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/d1/database',
  tags: ['D1'],
  summary: 'List D1 Databases',
  description: 'List D1 databases in your account.',
  operationId: 'd1-list-databases',
  request: {
    params: z.object({
      account_id: D1AccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/d1_account-identifier' },
        },
      }),
    }),
    query: z.object({
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            schema: { description: 'a database name to search for.', type: 'string' },
            required: false,
          },
          description: 'a database name to search for.',
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(10).max(10000),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of items per page.',
              type: 'number',
              default: 1000,
              maximum: 10000,
              minimum: 10,
            },
            required: false,
          },
          description: 'Number of items per page.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List D1 databases response',
      content: {
        'application/json': {
          schema: D1ApiResponseCommonSchema.and(
            z
              .object({
                result: z.array(D1DatabaseResponseSchema).exactOptional(),
                result_info: z
                  .object({
                    count: z
                      .number()
                      .exactOptional()
                      .openapi({
                        description: 'Total number of results for the requested service',
                        example: 1,
                      }),
                    page: z
                      .number()
                      .exactOptional()
                      .openapi({
                        description: 'Current page within paginated list of results',
                        example: 1,
                      }),
                    per_page: z
                      .number()
                      .exactOptional()
                      .openapi({
                        description: 'Number of results per page of results',
                        example: 20,
                      }),
                    total_count: z
                      .number()
                      .exactOptional()
                      .openapi({
                        description: 'Total results available without any search parameters',
                        example: 2000,
                      }),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'List D1 databases response failure',
      content: { 'application/json': { schema: D1ApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

