export const postAccountsAccountIdD1DatabaseDatabaseIdImportRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/d1/database/{database_id}/import',
  tags: ['D1'],
  summary: 'Import SQL into your D1 Database',
  description:
    'Generate a temporary URL for uploading an SQL file to, then instruct the D1 to import it\nand poll it for status updates. Imports block the D1 for their duration.\n',
  operationId: 'd1-import-database',
  request: {
    params: z.object({
      account_id: D1AccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/d1_account-identifier' },
        },
      }),
      database_id: D1DatabaseIdentifierSchema.openapi({
        param: {
          name: 'database_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/d1_database-identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                action: z
                  .literal('init')
                  .openapi({
                    description: 'Indicates you have a new SQL file to upload.',
                    'x-auditable': true,
                  }),
                etag: z
                  .string()
                  .openapi({
                    description:
                      "Required when action is 'init' or 'ingest'. An md5 hash of the file you're uploading. Used to check if it already exists, and validate its contents before ingesting.",
                    'x-auditable': true,
                  }),
              })
              .openapi({ required: ['action', 'etag'], title: 'init' }),
            z
              .object({
                action: z
                  .literal('ingest')
                  .openapi({
                    description:
                      "Indicates you've finished uploading to tell the D1 to start consuming it",
                    'x-auditable': true,
                  }),
                etag: z
                  .string()
                  .openapi({
                    description:
                      "An md5 hash of the file you're uploading. Used to check if it already exists, and validate its contents before ingesting.",
                    'x-auditable': true,
                  }),
                filename: z
                  .string()
                  .openapi({
                    description: 'The filename you have successfully uploaded.',
                    'x-auditable': true,
                  }),
              })
              .openapi({ required: ['action', 'etag', 'filename'], title: 'ingest' }),
            z
              .object({
                action: z
                  .literal('poll')
                  .openapi({
                    description:
                      "Indicates you've finished uploading to tell the D1 to start consuming it",
                    'x-auditable': true,
                  }),
                current_bookmark: z
                  .string()
                  .openapi({
                    description:
                      'This identifies the currently-running import, checking its status.',
                    'x-auditable': true,
                  }),
              })
              .openapi({ required: ['action', 'current_bookmark'], title: 'poll' }),
          ]),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Successful action. Import is either ready to start, under way, or finished (succeeded or failed).',
      content: {
        'application/json': {
          schema: D1ApiResponseCommonSchema.and(
            z
              .object({
                result: z
                  .object({
                    at_bookmark: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The current time-travel bookmark for your D1, used to poll for updates. Will not change for the duration of the import. Only returned if an import process is currently running or recently finished.',
                        'x-auditable': true,
                      }),
                    error: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          "Only present when status = 'error'. Contains the error message that prevented the import from succeeding.",
                        'x-auditable': true,
                      }),
                    filename: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          "Derived from the database ID and etag, to use in avoiding repeated uploads. Only returned when for the 'init' action.",
                        'x-auditable': true,
                      }),
                    messages: z
                      .array(z.string().openapi({ 'x-auditable': true }))
                      .exactOptional()
                      .openapi({ description: 'Logs since the last time you polled' }),
                    result: z
                      .object({
                        final_bookmark: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'The time-travel bookmark if you need restore your D1 to directly after the import succeeded.',
                            'x-auditable': true,
                          }),
                        meta: D1QueryMetaSchema.exactOptional(),
                        num_queries: z
                          .number()
                          .exactOptional()
                          .openapi({
                            description:
                              'The total number of queries that were executed during the import.',
                            'x-auditable': true,
                          }),
                      })
                      .exactOptional()
                      .openapi({
                        description: "Only present when status = 'complete'",
                        required: [],
                      }),
                    status: z
                      .enum(['complete', 'error'])
                      .exactOptional()
                      .openapi({ 'x-auditable': true }),
                    success: z.boolean().exactOptional().openapi({ 'x-auditable': true }),
                    type: z.literal('import').exactOptional().openapi({ 'x-auditable': true }),
                    upload_url: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          "The R2 presigned URL to use for uploading. Only returned when for the 'init' action.",
                      }),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    202: {
      description: 'Polled successfully, task is currently running',
      content: {
        'application/json': {
          schema: D1ApiResponseCommonSchema.and(
            z
              .object({
                result: z
                  .object({
                    at_bookmark: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The current bookmark for your D1, used to poll for updates. Will not change for the duration of the import.',
                        'x-auditable': true,
                      }),
                    messages: z
                      .array(z.string().openapi({ 'x-auditable': true }))
                      .exactOptional()
                      .openapi({ description: 'Logs since the last time you polled' }),
                    status: z.literal('active').exactOptional().openapi({ 'x-auditable': true }),
                    success: z.boolean().exactOptional().openapi({ 'x-auditable': true }),
                    type: z.literal('import').exactOptional().openapi({ 'x-auditable': true }),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Poll failed (API error)',
      content: { 'application/json': { schema: D1ApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

