export const postAccountsAccountIdD1DatabaseDatabaseIdUndeleteRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/d1/database/{database_id}/undelete',
  tags: ['D1'],
  summary: 'Undelete D1 Database',
  description:
    "Restore a deleted D1 database. The database is restored with the name it had when it was deleted,\nunless `new_name` is provided. The restored database counts against the account's limits.\nUndeleting a database that is not deleted succeeds without changes, unless `new_name` differs from its current name which errors.\nA database can only be undeleted within 7 days (7 * 24 hours) of its deletion.\n\nOnce a database is undeleted, Time Travel (point-in-time recovery) cannot restore it to a bookmark or\ntimestamp at or before the undeletion. Only states after the undeletion can be restored.\n",
  operationId: 'd1-undelete-database',
  request: {
    params: z.object({
      account_id: D1AccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/d1_account-identifier' },
        },
      }),
      database_id: D1DatabaseIdentifierSchema.openapi({
        param: {
          name: 'database_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/d1_database-identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              new_name: D1DatabaseNameSchema.exactOptional().openapi({
                description:
                  'Restore the database with this name instead of the name it had when it was deleted. Required if another database in the account already uses that name.',
              }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: "Returns the undeleted D1 database's metadata",
      content: {
        'application/json': {
          schema: D1ApiResponseCommonSchema.and(
            z
              .object({ result: D1DatabaseDetailsResponseSchema.exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Undelete D1 database response failure',
      content: { 'application/json': { schema: D1ApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

