export const getAccountsAccountIdDataSecurityPostureFindingTypesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/data-security/posture/finding_types',
  tags: ['finding_types'],
  summary: 'List all finding types',
  description: 'List all available finding types with pagination support.',
  operationId: 'ListFindingTypes',
  request: {
    params: z.object({ account_id: PostureApiAccountTagParamsSchema }),
    query: z.object({
      page: PostureApiPageParamsSchema,
      per_page: PostureApiPerPageParamsSchema,
      vendors: PostureApiFindingTypeVendorsParamsSchema,
      types: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(PostureApiFindingCategoryTypeEnumSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'types',
            in: 'query',
            description:
              'Filter finding types by category type. Supports multiple comma-separated, case-insensitive values.',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/posture-api_FindingCategoryTypeEnum' },
            },
            explode: false,
            style: 'form',
            required: false,
          },
        }),
      origins: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(PostureApiFindingTypeOriginEnumSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'origins',
            in: 'query',
            description:
              'Filter finding types by origin. Supports multiple comma-separated, case-insensitive values.',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/posture-api_FindingTypeOriginEnum' },
            },
            explode: false,
            style: 'form',
            required: false,
          },
        }),
      severities: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(PostureApiFindingTypeSeverityEnumSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'severities',
            in: 'query',
            description:
              'Filter finding types by severity. Supports multiple comma-separated, case-insensitive values.',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/posture-api_FindingTypeSeverityEnum' },
            },
            explode: false,
            style: 'form',
            required: false,
          },
        }),
      search: PostureApiFindingTypeSearchParamsSchema,
      quarantined: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'quarantined',
            in: 'query',
            description:
              'When true, return only quarantined finding types; when false, return only non-quarantined finding types. Omit to return both.',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      min_updated_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'min_updated_at',
            in: 'query',
            description:
              'Return only finding types updated at or after this RFC 3339 timestamp (inclusive).',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      max_updated_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'max_updated_at',
            in: 'query',
            description:
              'Return only finding types updated at or before this RFC 3339 timestamp (inclusive).',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      order: z
        .enum(['created', 'updated', 'match_count', 'name', 'vendor', 'type', 'origin', 'severity'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            description:
              "Field to sort by (case-insensitive). Defaults to 'created'.\nName and vendor sorting is case-insensitive; vendor uses friendly provider names.\nAscending order: type Content then Posture; origin custom then system;\nseverity Low, Medium, High, Critical.",
            schema: {
              type: 'string',
              enum: [
                'created',
                'updated',
                'match_count',
                'name',
                'vendor',
                'type',
                'origin',
                'severity',
              ],
            },
            required: false,
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            description:
              "Sort direction for the primary field. Defaults to 'desc'.\nTies are resolved by case-insensitive name, then ID, both ascending regardless of direction.",
            schema: { type: 'string', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK: Successful HTTP request',
      content: { 'application/json': { schema: PostureApiPaginatedFindingTypeListSchema } },
    },
    400: { description: 'Bad Request: Invalid request parameters' },
    403: {
      description:
        'Forbidden: The min_updated_at and max_updated_at filters are not available in this deployment',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    429: PostureApiRateLimitedResponse,
  },
  security: [{ api_token: [] }],
})

