export const postAccountsAccountIdDataSecurityPostureFindingTypesValidateRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/data-security/posture/finding_types/validate',
  tags: ['finding_types'],
  summary: 'Validate a custom finding type',
  description:
    'Check a candidate custom finding type without creating it, so problems can\nbe corrected before publishing. The request body is the same shape as\n`CreateFindingType`, and the candidate is checked against the same rules, so\na valid result means the definition itself is sound. It is not a reservation:\na create can still be rejected for a reason that does not belong to the\ndefinition, such as the account already holding the maximum number of custom\nfinding types.\n\nA candidate that fails validation is still a **200** with\n`result.valid: false` and one entry in `result.errors` per problem — that is\nthe answer this endpoint exists to give. `4xx` is reserved for a request\nthat could not be processed at all, such as a body that will not parse.',
  operationId: 'ValidateFindingType',
  request: {
    params: z.object({ account_id: PostureApiAccountTagParamsSchema }),
    body: {
      content: { 'application/json': { schema: PostureApiCreateFindingTypeRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK: Validation completed, whether or not the candidate is valid',
      content: { 'application/json': { schema: PostureApiValidateFindingTypeResponseSchema } },
    },
    400: {
      description: 'Bad Request: Request body could not be parsed',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized: Authentication required',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden: Insufficient permissions to validate finding types',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    429: PostureApiRateLimitedResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

