export const getAccountsAccountIdDataSecurityPosturePolicyLogsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/data-security/posture/policy_logs',
  tags: ['policies'],
  summary: 'List policy invocation logs',
  description:
    "Returns a list of policy invocation logs for the given account, sourced from ClickHouse via Ready Analytics. Each entry represents one execution of a policy against a finding instance, including the actions (remediation jobs and webhooks) it dispatched.\n\nResults are scoped to the requesting account's CASB integrations. The `integration_id` query parameter, when supplied, is intersected against the account's integration allowlist; values outside the allowlist are silently dropped.\n\nPagination is offset-based. The response does not include a total row count; clients should treat a result with fewer than `per_page` entries as the end of the list.\n",
  operationId: 'ListPolicyLogEntries',
  request: {
    params: z.object({ account_id: PostureApiAccountTagParamsSchema }),
    query: z.object({
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'since',
            in: 'query',
            description:
              'Lower bound on the log entry timestamp. Accepts ISO 8601 / RFC3339 or epoch seconds. Defaults to 7 days before `until`. The window between `since` and `until` cannot exceed 180 days.',
            schema: { type: 'string', format: 'date-time' },
            example: '2026-04-01T00:00:00Z',
            required: false,
          },
        }),
      until: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'until',
            in: 'query',
            description:
              'Upper bound on the log entry timestamp. Accepts ISO 8601 / RFC3339 or epoch seconds. Defaults to the current time. Must be greater than or equal to `since`.',
            schema: { type: 'string', format: 'date-time' },
            example: '2026-04-08T00:00:00Z',
            required: false,
          },
        }),
      integration_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'integration_id',
            in: 'query',
            description:
              "Comma-separated list of CASB integration IDs to filter by. At most 100 values, each at most 128 characters. Values outside the account's tenancy allowlist are silently ignored. When omitted, results are scoped to the full allowlist.",
            schema: { type: 'string' },
            example: '497f6eca-6276-4993-bfeb-53cbbbba6f08',
            required: false,
          },
        }),
      policy_name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'policy_name',
            in: 'query',
            description:
              'Comma-separated list of policy display names to filter by. At most 100 values, each at most 255 characters.',
            schema: { type: 'string' },
            example: 'Auto-remediate publicly shared files',
            required: false,
          },
        }),
      page: PostureApiPageParamsSchema,
      per_page: PostureApiPerPageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'OK: Policy logs retrieved successfully',
      content: {
        'application/json': {
          schema: PostureApiApiResponseCollectionSchema.and(
            z
              .object({ result: z.array(PostureApiPolicyLogResponseSchema).exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad Request: Invalid query parameters',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized: Authentication required',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden: Insufficient permissions',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    429: PostureApiRateLimitedResponse,
    502: {
      description: 'Bad Gateway: Policy logs backend (ClickHouse) is unavailable',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
    504: {
      description: 'Gateway Timeout: Policy logs query timed out',
      content: { 'application/json': { schema: PostureApiErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

