export const getAccountsAccountIdDevicesClientVersionsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/devices/client-versions',
  tags: ['Client Versions'],
  summary: 'List client versions',
  description:
    'Lists available WARP client versions for a specific target environment and release track. This endpoint is in Beta.',
  operationId: 'list-client-versions',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      target_environment: z
        .string()
        .openapi({
          param: {
            name: 'target_environment',
            in: 'query',
            description: 'The target environment for the client version (e.g., windows, macos).',
            required: true,
            schema: { type: 'string' },
          },
        }),
      release_track: z
        .enum(['ga', 'beta'])
        .openapi({
          param: {
            name: 'release_track',
            in: 'query',
            description: 'The release track (ga for General Availability, beta for Beta releases).',
            required: true,
            schema: { type: 'string', enum: ['ga', 'beta'] },
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'The page number to return.',
            schema: { type: 'integer', default: 1, minimum: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'The maximum number of versions to return per page.',
            schema: { type: 'integer', default: 20, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List client versions response.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(TeamsDevicesV4ResponseMessageSchema),
              messages: z.array(TeamsDevicesV4ResponseMessageSchema),
              result: z.array(TeamsDevicesClientVersionSchema),
              result_info: TeamsDevicesPaginationInfoSchema,
              success: z
                .boolean()
                .openapi({ description: 'Indicates whether the API call was successful.' }),
            })
            .openapi({ required: ['result', 'result_info', 'success', 'errors', 'messages'] }),
        },
      },
    },
    '4XX': {
      description: 'Client error response.',
      content: { 'application/json': { schema: TeamsDevicesV4ErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

