export const getAccountsAccountIdDevicesIpProfilesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/devices/ip-profiles',
  tags: ['IP Profiles'],
  summary: 'List IP profiles',
  description: 'Lists WARP Device IP profiles.',
  operationId: 'list-ip-profiles',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'The page number to return.',
            schema: { type: 'integer', default: 1, minimum: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'The number of IP profiles to return per page.',
            schema: { type: 'integer', default: 50, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Device IP profiles response.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(TeamsDevicesV4ResponseMessageSchema),
              messages: z.array(TeamsDevicesV4ResponseMessageSchema),
              result: z.array(TeamsDevicesIpProfileSchema),
              result_info: TeamsDevicesPaginationInfoSchema.exactOptional(),
              success: z.boolean().openapi({ description: 'Whether the API call was successful.' }),
            })
            .openapi({ required: ['result', 'success', 'errors', 'messages'] }),
        },
      },
    },
    '4XX': {
      description: 'Client error response.',
      content: { 'application/json': { schema: TeamsDevicesV4ErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

