export const getAccountsAccountIdDexColosRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/dex/colos',
  tags: ['DEX Synthetic Application Monitoring'],
  summary: 'List Cloudflare colos',
  description:
    "List Cloudflare colos that account's devices were connected to during a time period, sorted by usage starting from the most used colo. Colos without traffic are also returned and sorted alphabetically.",
  operationId: 'dex-endpoints-list-colos',
  request: {
    params: z.object({
      account_id: DigitalExperienceMonitoringAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          description: 'Unique Cloudflare account ID.',
          required: true,
          schema: { $ref: '#/components/schemas/digital-experience-monitoring_account_identifier' },
        },
      }),
    }),
    query: z.object({
      from: z
        .string()
        .openapi({
          param: {
            name: 'from',
            in: 'query',
            description: 'Start time for connection period in ISO (RFC3339 - ISO 8601) format.',
            required: true,
            schema: { type: 'string', example: '2023-08-20T20:45:00Z' },
          },
          example: '2023-08-20T20:45:00Z',
        }),
      to: z
        .string()
        .openapi({
          param: {
            name: 'to',
            in: 'query',
            description: 'End time for connection period in ISO (RFC3339 - ISO 8601) format.',
            required: true,
            schema: { type: 'string', example: '2023-08-24T20:45:00Z' },
          },
          example: '2023-08-24T20:45:00Z',
        }),
      sortBy: z
        .enum(['fleet-status-usage', 'application-tests-usage'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sortBy',
            in: 'query',
            description:
              'Type of usage that colos should be sorted by. If unspecified, returns all Cloudflare colos sorted alphabetically.',
            schema: { type: 'string', enum: ['fleet-status-usage', 'application-tests-usage'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List colos response.',
      content: {
        'application/json': {
          schema: DigitalExperienceMonitoringApiResponseCommonSchema.and(
            z
              .object({ result: DigitalExperienceMonitoringColosResponseSchema.exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'List colos failure response.',
      content: {
        'application/json': { schema: DigitalExperienceMonitoringApiResponseCommonFailureSchema },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { user_service_key: [] }],
})

export const getAccountsAccountIdDexCommandsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/dex/commands',
  tags: ['DEX Remote Commands'],
  summary: 'List account commands',
  description:
    'Retrieves a paginated list of commands issued to devices under the specified account, optionally filtered by time range, device, or other parameters',
  operationId: 'get-commands',
  request: {
    params: z.object({
      account_id: DigitalExperienceMonitoringAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          description: 'Unique Cloudflare account ID.',
          required: true,
          schema: { $ref: '#/components/schemas/digital-experience-monitoring_account_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Page number of paginated results.',
            required: true,
            schema: { type: 'number', example: 1, default: 1, minimum: 1 },
          },
          example: 1,
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(50),
        )
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Number of results per page.',
            required: true,
            schema: { type: 'number', example: 10, maximum: 50, minimum: 1 },
          },
          example: 10,
        }),
      from: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'from',
            in: 'query',
            description: 'Start time for the query in ISO (RFC3339 - ISO 8601) format.',
            schema: { type: 'string', format: 'date-time', example: '2023-08-20T20:45:00Z' },
            required: false,
          },
          example: '2023-08-20T20:45:00Z',
        }),
      to: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'to',
            in: 'query',
            description: 'End time for the query in ISO (RFC3339 - ISO 8601) format.',
            schema: { type: 'string', format: 'date-time', example: '2023-08-24T20:45:00Z' },
            required: false,
          },
          example: '2023-08-24T20:45:00Z',
        }),
      device_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'device_id',
            in: 'query',
            description: 'Unique identifier for a device.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      user_email: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'user_email',
            in: 'query',
            description: 'Email tied to the device.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      command_type: z
        .enum(['pcap', 'speed-test', 'warp-diag'])
        .exactOptional()
        .openapi({
          param: {
            name: 'command_type',
            in: 'query',
            description: 'Optionally filter executed commands by command type.',
            schema: { type: 'string', enum: ['pcap', 'speed-test', 'warp-diag'] },
            required: false,
          },
        }),
      status: z
        .enum(['PENDING_EXEC', 'PENDING_UPLOAD', 'SUCCESS', 'FAILED'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description: 'Optionally filter executed commands by status.',
            schema: {
              type: 'string',
              enum: ['PENDING_EXEC', 'PENDING_UPLOAD', 'SUCCESS', 'FAILED'],
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get commands response.',
      content: {
        'application/json': {
          schema: DigitalExperienceMonitoringApiResponseCollectionSchema.and(
            z
              .object({
                result: DigitalExperienceMonitoringGetCommandsResponseSchema.exactOptional(),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Get commands failure response.',
      content: {
        'application/json': { schema: DigitalExperienceMonitoringApiResponseCommonFailureSchema },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { user_service_key: [] }],
})

export const postAccountsAccountIdDexCommandsRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/dex/commands',
  tags: ['DEX Remote Commands'],
  summary: 'Create account commands',
  description: 'Initiate commands for up to 10 devices per account.',
  operationId: 'post-commands',
  request: {
    params: z.object({
      account_id: DigitalExperienceMonitoringAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          description: 'Unique Cloudflare account ID.',
          required: true,
          schema: { $ref: '#/components/schemas/digital-experience-monitoring_account_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              commands: z
                .array(
                  z
                    .object({
                      args: z
                        .xor([
                          z
                            .strictObject({
                              'test-all-routes': z
                                .boolean()
                                .default(true)
                                .exactOptional()
                                .openapi({
                                  description:
                                    "Test an IP address from all included or excluded ranges. Essentially the same as running 'route get <ip>' and collecting the results. This option may increase the time taken to collect the warp-diag.",
                                  'x-auditable': true,
                                }),
                            })
                            .openapi({ title: 'warp-diag args', required: [] }),
                          z
                            .strictObject({
                              'max-file-size-mb': z
                                .number()
                                .min(1)
                                .default(5)
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Maximum file size (in MB) for the capture file. If the capture artifact exceeds the specified max file size, it will NOT be uploaded.',
                                  'x-auditable': true,
                                }),
                              'packet-size-bytes': z
                                .number()
                                .min(1)
                                .default(160)
                                .exactOptional()
                                .openapi({
                                  description: 'Maximum number of bytes to save for each packet',
                                  'x-auditable': true,
                                }),
                              'time-limit-min': z
                                .number()
                                .min(1)
                                .default(5)
                                .exactOptional()
                                .openapi({
                                  description: 'Limit on capture duration (in minutes)',
                                  'x-auditable': true,
                                }),
                            })
                            .openapi({ title: 'pcap args', required: [] }),
                          z
                            .strictObject({
                              interfaces: z
                                .array(
                                  z.enum(['default', 'tunnel']).openapi({ 'x-auditable': true }),
                                )
                                .exactOptional()
                                .openapi({
                                  description: 'List of interfaces to run the speed test on',
                                }),
                            })
                            .openapi({ title: 'speed-test args', required: [] }),
                        ])
                        .exactOptional()
                        .openapi({
                          description: 'Command arguments. Allowed fields depend on `type`.',
                        }),
                      device_id: z
                        .string()
                        .openapi({ description: 'Unique identifier for the physical device' }),
                      registration_id: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Unique identifier for the device registration. Required for multi-user devices to target the correct user session.',
                        }),
                      type: z
                        .enum(['pcap', 'speed-test', 'warp-diag'])
                        .openapi({
                          description: 'Type of command to execute on the device',
                          'x-auditable': true,
                        }),
                      user_email: z.string().openapi({ description: 'Email tied to the device' }),
                    })
                    .openapi({ required: ['device_id', 'user_email', 'type'] }),
                )
                .max(20)
                .openapi({ description: 'List of device-level commands to execute' }),
            })
            .openapi({ required: ['commands'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Create commands response.',
      content: {
        'application/json': {
          schema: DigitalExperienceMonitoringApiResponseCollectionSchema.and(
            z
              .object({
                result: DigitalExperienceMonitoringPostCommandsResponseSchema.exactOptional(),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Create commands failure response.',
      content: {
        'application/json': { schema: DigitalExperienceMonitoringApiResponseCommonFailureSchema },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { user_service_key: [] }],
})

