export const postAccountsAccountIdDlpDatasetsDatasetIdUploadVersionRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/dlp/datasets/{dataset_id}/upload/{version}',
  tags: ['DLP Datasets'],
  summary: 'Upload a new version of a dataset',
  description:
    'This is used for single-column EDMv1 and Custom Word Lists. The EDM format\ncan only be created in the Cloudflare dashboard. For other clients, this\noperation can only be used for non-secret Custom Word Lists. The body must\nbe a UTF-8 encoded, newline (NL or CRNL) separated list of words to be matched.',
  operationId: 'dlp-datasets-upload-version',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
      dataset_id: z
        .uuid()
        .openapi({
          param: {
            name: 'dataset_id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      version: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'version',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            'x-fern-parameter-name': 'dataset-version',
          },
        }),
    }),
    body: {
      description:
        'Dataset. For custom wordlists this contains UTF-8 patterns separated by newline characters.',
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Dataset version uploaded successfully.',
      content: {
        'application/json': {
          schema: DlpApiResponseSingleSchema.and(
            z.object({ result: DlpDatasetSchema.exactOptional() }).openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Dataset version upload failed.',
      content: { 'application/json': { schema: DlpApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

