export const deleteAccountsAccountIdDlpProfilesIntegrationProfileIdRoute = createRoute({
  method: 'delete',
  path: '/accounts/{account_id}/dlp/profiles/integration/{profile_id}',
  tags: ['DLP Profiles'],
  summary: 'Delete integration profile',
  description:
    'Deletes a DLP integration profile whose integration no longer exists. If the profile owns\nentries, `recursive=1` is required. This also deletes the entries and removes all references to\nthem, as listed by the references endpoint.',
  operationId: 'dlp-profiles-delete-integration-profile',
  request: {
    query: z.object({
      recursive: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(0).max(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'recursive',
            in: 'query',
            description:
              'Set to `1` to also delete the entries owned by the profile and remove all references to\nthem, as listed by the references endpoint. Required if the profile owns any entries.\nDefaults to `0`.',
            schema: { type: 'integer', format: 'int32', maximum: 1, minimum: 0 },
            required: false,
          },
        }),
    }),
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
      profile_id: z
        .uuid()
        .openapi({
          param: {
            name: 'profile_id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Delete integration profile response.',
      content: {
        'application/json': {
          schema: DlpApiResponseSingleSchema.and(
            z.object({ result: DlpEmptySchema.exactOptional() }).openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Delete integration profile failure response.',
      content: { 'application/json': { schema: DlpApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

