export const getAccountsAccountIdDlsRegionalServicesPrefixBindingsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/dls/regional_services/prefix_bindings',
  tags: ['Prefix Bindings'],
  summary: 'List DLS prefix bindings for an account',
  description: 'List the BYOIP prefix bindings configured for an account.',
  operationId: 'publicListPrefixBindings',
  request: {
    params: z.object({
      account_id: DlsAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/dls_account_identifier' },
        },
      }),
    }),
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            description:
              'Opaque token for cursor-based pagination. Omit for the first page. Pass the value from a previous response to fetch the next page.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: { type: 'integer', default: 25, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of bindings.',
      content: { 'application/json': { schema: DlsPrefixBindingPaginatedListResponseSchema } },
    },
    400: {
      description: 'Bad request.',
      content: { 'application/json': { schema: DlsBadResponseSchema } },
    },
    401: {
      description: 'Unauthorized.',
      content: { 'application/json': { schema: DlsBadResponseSchema } },
    },
    403: {
      description: 'Forbidden.',
      content: { 'application/json': { schema: DlsBadResponseSchema } },
    },
    500: {
      description: 'Internal server error.',
      content: { 'application/json': { schema: DlsBadResponseSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

