export const postAccountsAccountIdEmailSecuritySettingsAllowPoliciesBatchRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/email-security/settings/allow_policies/batch',
  tags: ['Email Security Settings'],
  summary: 'Batch allow policy operations',
  description:
    'Executes multiple allow policy operations atomically: delete, partially update,\nreplace, and create allow policies in a single request. All four operation arrays\n(deletes, patches, puts, posts) are required and executed in order.\nSend empty arrays for unused operations.\n',
  operationId: 'email_security_batch_allow_policies',
  request: {
    params: z.object({ account_id: EmailSecurityAccountIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              deletes: z
                .array(
                  z.object({ id: EmailSecurityAllowPolicyIdSchema }).openapi({ required: ['id'] }),
                )
                .max(1000)
                .openapi({ description: 'IDs of the allow policies to delete.' }),
              patches: z
                .array(
                  EmailSecurityUpdateAllowPolicySchema.and(
                    z
                      .object({ id: EmailSecurityAllowPolicyIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Partial updates to apply — each entry carries the policy's ID and only the fields to change.",
                }),
              posts: z
                .array(EmailSecurityCreateAllowPolicySchema)
                .max(1000)
                .openapi({ description: 'Allow policies to create.' }),
              puts: z
                .array(
                  EmailSecurityCreateAllowPolicySchema.and(
                    z
                      .object({ id: EmailSecurityAllowPolicyIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Full replacements to apply — each entry carries the policy's ID and every field of its new value.",
                }),
            })
            .openapi({ required: ['deletes', 'patches', 'puts', 'posts'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Batch operation results.',
      content: {
        'application/json': {
          schema: EmailSecurityApiResponseSingleSchema.and(
            z
              .object({
                result: z
                  .object({
                    deletes: z.array(EmailSecurityDeletedAllowPolicySchema).exactOptional(),
                    patches: EmailSecurityAllowPolicyListSchema.exactOptional(),
                    posts: EmailSecurityAllowPolicyListSchema.exactOptional(),
                    puts: EmailSecurityAllowPolicyListSchema.exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': EmailSecurityClientErrorResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

