export const postAccountsAccountIdEmailSecuritySettingsBlockSendersBatchRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/email-security/settings/block_senders/batch',
  tags: ['Email Security Settings'],
  summary: 'Batch blocked sender operations',
  description:
    'Executes multiple blocked sender operations atomically: delete, partially update,\nreplace, and create blocked sender patterns in a single request. All four operation\narrays (deletes, patches, puts, posts) are required and executed in order.\nSend empty arrays for unused operations.\n',
  operationId: 'email_security_batch_blocked_senders',
  request: {
    params: z.object({ account_id: EmailSecurityAccountIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              deletes: z
                .array(
                  z
                    .object({ id: EmailSecurityBlockedSenderIdSchema })
                    .openapi({ required: ['id'] }),
                )
                .max(1000)
                .openapi({ description: 'IDs of the blocked sender patterns to delete.' }),
              patches: z
                .array(
                  EmailSecurityUpdateBlockedSenderSchema.and(
                    z
                      .object({ id: EmailSecurityBlockedSenderIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Partial updates to apply — each entry carries the pattern's ID and only the fields to change.",
                }),
              posts: z
                .array(EmailSecurityCreateBlockedSenderSchema)
                .max(1000)
                .openapi({ description: 'Blocked sender patterns to create.' }),
              puts: z
                .array(
                  EmailSecurityCreateBlockedSenderSchema.and(
                    z
                      .object({ id: EmailSecurityBlockedSenderIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Full replacements to apply — each entry carries the pattern's ID and every field of its new value.",
                }),
            })
            .openapi({ required: ['deletes', 'patches', 'puts', 'posts'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Batch operation results.',
      content: {
        'application/json': {
          schema: EmailSecurityApiResponseSingleSchema.and(
            z
              .object({
                result: z
                  .object({
                    deletes: z.array(EmailSecurityDeletedBlockedSenderSchema).exactOptional(),
                    patches: EmailSecurityBlockedSenderListSchema.exactOptional(),
                    posts: EmailSecurityBlockedSenderListSchema.exactOptional(),
                    puts: EmailSecurityBlockedSenderListSchema.exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': EmailSecurityClientErrorResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

