export const postAccountsAccountIdEmailSecuritySettingsDomainsBatchRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/email-security/settings/domains/batch',
  tags: ['Email Security Settings'],
  summary: 'Batch domain operations',
  description:
    'Executes multiple domain operations in a single request. All four operation arrays\n(deletes, patches, puts, posts) are required and executed in order.\nSend empty arrays for unused operations.\n',
  operationId: 'email_security_batch_domains',
  request: {
    params: z.object({ account_id: EmailSecurityAccountIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              deletes: z
                .array(z.object({ id: EmailSecurityDomainIdSchema }).openapi({ required: ['id'] }))
                .max(1000)
                .openapi({ description: 'IDs of the domains to remove protection from.' }),
              patches: z
                .array(
                  EmailSecurityUpdateDomainSchema.and(
                    z.object({ id: EmailSecurityDomainIdSchema }).openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Partial updates to apply — each entry carries the domain's ID and only the fields to change.",
                }),
              posts: z
                .array(EmailSecurityCreateDomainSchema)
                .max(1000)
                .openapi({ description: 'Domains to add protection for.' }),
              puts: z
                .array(
                  EmailSecurityReplaceDomainSchema.and(
                    z.object({ id: EmailSecurityDomainIdSchema }).openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Full replacements to apply — each entry carries the domain's ID and every field of its new value.",
                }),
            })
            .openapi({ required: ['deletes', 'patches', 'puts', 'posts'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Batch operation results.',
      content: {
        'application/json': {
          schema: EmailSecurityApiResponseSingleSchema.and(
            z
              .object({
                result: z
                  .object({
                    deletes: z.array(EmailSecurityDeletedDomainSchema),
                    patches: EmailSecurityDomainListSchema,
                    posts: EmailSecurityDomainListSchema,
                    puts: EmailSecurityDomainListSchema,
                  })
                  .exactOptional()
                  .openapi({ required: ['deletes', 'patches', 'puts', 'posts'] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': EmailSecurityClientErrorResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

