export const postAccountsAccountIdEmailSecuritySettingsTrustedDomainsBatchRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/email-security/settings/trusted_domains/batch',
  tags: ['Email Security Settings'],
  summary: 'Batch trusted domain operations',
  description:
    'Executes multiple trusted domain operations atomically: delete, partially update,\nreplace, and create trusted domain patterns in a single request. All four operation\narrays (deletes, patches, puts, posts) are required and executed in order.\nSend empty arrays for unused operations.\n',
  operationId: 'email_security_batch_trusted_domains',
  request: {
    params: z.object({ account_id: EmailSecurityAccountIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              deletes: z
                .array(
                  z
                    .object({ id: EmailSecurityTrustedDomainIdSchema })
                    .openapi({ required: ['id'] }),
                )
                .max(1000)
                .openapi({ description: 'IDs of the trusted domain patterns to delete.' }),
              patches: z
                .array(
                  EmailSecurityUpdateTrustedDomainSchema.and(
                    z
                      .object({ id: EmailSecurityTrustedDomainIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Partial updates to apply — each entry carries the pattern's ID and only the fields to change.",
                }),
              posts: z
                .array(EmailSecurityCreateTrustedDomainSchema)
                .max(1000)
                .openapi({ description: 'Trusted domain patterns to create.' }),
              puts: z
                .array(
                  EmailSecurityCreateTrustedDomainSchema.and(
                    z
                      .object({ id: EmailSecurityTrustedDomainIdSchema })
                      .openapi({ required: ['id'] }),
                  ),
                )
                .max(1000)
                .openapi({
                  description:
                    "Full replacements to apply — each entry carries the pattern's ID and every field of its new value.",
                }),
            })
            .openapi({ required: ['deletes', 'patches', 'puts', 'posts'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Batch operation results.',
      content: {
        'application/json': {
          schema: EmailSecurityApiResponseSingleSchema.and(
            z
              .object({
                result: z
                  .object({
                    deletes: z.array(EmailSecurityDeletedTrustedDomainSchema).exactOptional(),
                    patches: EmailSecurityTrustedDomainListSchema.exactOptional(),
                    posts: EmailSecurityTrustedDomainListSchema.exactOptional(),
                    puts: EmailSecurityTrustedDomainListSchema.exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': EmailSecurityClientErrorResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

