export const getAccountsAccountIdEventSubscriptionsSubscriptionsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/event_subscriptions/subscriptions',
  tags: ['Queue'],
  summary: 'List Event Subscriptions',
  description:
    'Returns a paginated list of Queue event subscriptions with optional sorting and filtering.',
  operationId: 'subscriptions-list',
  request: {
    params: z.object({
      account_id: MqIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/mq_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Page number for pagination',
            schema: { type: 'integer', default: 1, minimum: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Number of items per page',
            schema: { type: 'integer', default: 20, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
      order: z
        .enum(['created_at', 'name', 'enabled', 'source'])
        .default('name')
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            description: 'Field to sort by',
            schema: {
              type: 'string',
              default: 'name',
              enum: ['created_at', 'name', 'enabled', 'source'],
            },
            required: false,
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .default('asc')
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            description: 'Sort direction',
            schema: { type: 'string', default: 'asc', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of event subscriptions',
      content: {
        'application/json': {
          schema: MqApiV4SuccessSchema.and(
            z
              .object({
                result: z.array(MqEventSubscriptionSchema).exactOptional(),
                result_info: z
                  .object({
                    count: z.int().openapi({ description: 'Number of items in current page' }),
                    page: z.int().openapi({ description: 'Current page number' }),
                    per_page: z.int().openapi({ description: 'Items per page' }),
                    total_count: z.int().openapi({ description: 'Total number of items' }),
                    total_pages: z.int().openapi({ description: 'Total number of pages' }),
                  })
                  .exactOptional()
                  .openapi({
                    required: ['count', 'total_count', 'page', 'per_page', 'total_pages'],
                  }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Failure response',
      content: { 'application/json': { schema: MqApiV4FailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

