export const putAccountsAccountIdFieldExtractorsExtractorRoute = createRoute({
  method: 'put',
  path: '/accounts/{account_id}/field_extractors/{extractor}',
  tags: ['Field Extractors'],
  summary: 'Update Field Extractor',
  description:
    'Replaces all custom extraction rules for an extractor type. Omitted rules are deleted.',
  operationId: 'updateFieldExtractor',
  request: {
    params: z.object({
      account_id: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            description: 'Cloudflare account ID.',
            required: true,
            schema: {
              description: 'Cloudflare account ID.',
              type: 'string',
              example: '123456',
              minLength: 1,
            },
          },
          description: 'Cloudflare account ID.',
          example: '123456',
        }),
      extractor: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'extractor',
            in: 'path',
            description: 'Extractor type.',
            required: true,
            schema: {
              description: 'Extractor type.',
              type: 'string',
              example: 'llm_prompts',
              minLength: 1,
            },
          },
          description: 'Extractor type.',
          example: 'llm_prompts',
        }),
    }),
    body: {
      description: 'Desired-state replacement of all rules for this extractor type.',
      content: {
        'application/json': {
          schema: z
            .object({
              rules: z
                .array(
                  z
                    .object({
                      description: z.string().max(4096).exactOptional(),
                      fields: z
                        .array(
                          z
                            .object({
                              expression: z.string().min(1).max(4096),
                              name: z.string().min(1),
                            })
                            .openapi({ required: ['name', 'expression'] }),
                        )
                        .min(1),
                      ref: z
                        .string()
                        .regex(/^[a-zA-Z0-9_-]+$/)
                        .min(1)
                        .max(64),
                    })
                    .openapi({ required: ['ref', 'fields'] }),
                )
                .min(1)
                .max(10),
            })
            .openapi({ required: ['rules'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Rules replaced successfully.',
      content: { 'application/json': { schema: FieldExtractorsSuccessResponseSchema } },
    },
    400: {
      description: 'Validation error.',
      content: { 'application/json': { schema: FieldExtractorsErrorResponseSchema } },
    },
    404: {
      description: 'Unknown extractor type.',
      content: { 'application/json': { schema: FieldExtractorsErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

