export const getAccountsAccountIdGatewayListsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/gateway/lists',
  tags: ['Zero Trust lists'],
  summary: 'List Zero Trust lists',
  description: 'Fetch all Zero Trust lists for an account.',
  operationId: 'zero-trust-lists-list-zero-trust-lists',
  request: {
    params: z.object({
      account_id: ZeroTrustGatewayIdentifier_2Schema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/zero-trust-gateway_identifier-2' },
        },
      }),
    }),
    query: z.object({
      type: ZeroTrustGatewayType_2Schema.openapi({
        param: {
          name: 'type',
          in: 'query',
          schema: { $ref: '#/components/schemas/zero-trust-gateway_type-2' },
          deprecated: true,
          'x-fern-availability': 'deprecated',
          required: false,
        },
      }).exactOptional(),
      filter: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.union([
              z.string().regex(/^name:.*$/),
              z.string().regex(/^id:.*$/),
              z
                .string()
                .regex(/^type:(IP|URL|DOMAIN|CATEGORY|EMAIL|SERIAL|LOCATION|DEVICE|AAGUID)$/),
              z.string().regex(/^item_count:[0-9]+$/),
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'filter',
            in: 'query',
            description:
              'Filter the returned lists by one or more `field:value` pairs.\nRepeat the parameter to apply multiple filters; they are combined with\nlogical AND (a list must satisfy every filter to be returned).\n\nSupported fields and their matching behaviour:\n  * `name` — case-insensitive substring match on the list name.\n  * `id` — substring match on the list ID (UUID), with or without dashes.\n  * `type` — exact match on the list type. Supersedes the legacy `type` query\n    parameter when both are supplied. Must be one of the valid type values.\n  * `item_count` — exact integer match on the number of items in the list.\n\nEach entry must match one of the per-field patterns below: the field must be\none of `name`, `id`, `type`, or `item_count`; `name`/`id` accept any value,\n`type` is restricted to the valid list type values, and `item_count` must be\na non-negative integer.',
            schema: {
              type: 'array',
              items: {
                anyOf: [
                  { pattern: '^name:.*$', type: 'string' },
                  { pattern: '^id:.*$', type: 'string' },
                  {
                    pattern: '^type:(IP|URL|DOMAIN|CATEGORY|EMAIL|SERIAL|LOCATION|DEVICE|AAGUID)$',
                    type: 'string',
                  },
                  { pattern: '^item_count:[0-9]+$', type: 'string' },
                ],
                type: 'string',
              },
            },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description:
              'Case-insensitive substring match on the list name or description. When\ncombined with `filter`, both must match (logical AND).',
            schema: { type: 'string' },
            required: false,
          },
        }),
      order_by: z
        .enum(['name', 'created_at', 'updated_at', 'item_count'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description:
              'Field to sort the returned lists by. When omitted, results are ordered by\n`created_at` in ascending order (i.e. creation order) for backwards\ncompatibility. Supported values:\n  * `name` — sort alphabetically by list name.\n  * `created_at` — sort by creation time; defaults to descending unless `direction` is set.\n  * `updated_at` — sort by last-modified time; defaults to descending unless `direction` is set.\n  * `item_count` — sort by number of items in the list.',
            schema: { type: 'string', enum: ['name', 'created_at', 'updated_at', 'item_count'] },
            required: false,
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            description:
              'Sort direction. Applies to the field named in `order_by`; when `order_by`\nis omitted it applies to the default `created_at` ordering. When\n`direction` is omitted the default is field-specific: explicitly choosing\n`created_at` or `updated_at` defaults to descending (newest first); `name`\nand `item_count` default to ascending; and the default `created_at`\nordering used when `order_by` is omitted is ascending (for backwards\ncompatibility).\n  * `asc` — ascending.\n  * `desc` — descending.',
            schema: { type: 'string', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Zero Trust lists response.',
      content: { 'application/json': { schema: ZeroTrustGatewayResponseCollection_3Schema } },
    },
    '4XX': {
      description: 'List Zero Trust lists response failure.',
      content: {
        'application/json': {
          schema: ZeroTrustGatewayResponseCollection_3Schema.and(
            ZeroTrustGatewayApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

