export const getAccountsAccountIdGatewayLocationsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/gateway/locations',
  tags: ['Zero Trust Gateway locations'],
  summary: 'List Zero Trust Gateway locations',
  description: 'List Zero Trust Gateway locations for an account.',
  operationId: 'zero-trust-gateway-locations-list-zero-trust-gateway-locations',
  request: {
    params: z.object({
      account_id: ZeroTrustGatewayIdentifier_2Schema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/zero-trust-gateway_identifier-2' },
        },
      }),
    }),
    query: z.object({
      filter: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.union([
              z.string().regex(/^name:.*$/),
              z.string().regex(/^id:.*$/),
              z.string().regex(/^is_default:(true|false)$/),
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'filter',
            in: 'query',
            description:
              'Filter the returned locations by one or more `field:value` pairs.\nRepeat the parameter to apply multiple filters; they are combined with\nlogical AND (a location must satisfy every filter to be returned).\n\nSupported fields and their matching behaviour:\n  * `name` — case-insensitive substring match on the location name.\n  * `id` — substring match on the location ID (UUID), with or without dashes.\n  * `is_default` — whether it is the default for the account.\n\nEach entry must match one of the per-field patterns below:\n  * the field must be one of `name`, `id`, or `is_default`;\n  * `name`/`id` accept any value;\n  * `is_default` only accepts `true` or `false`; any other value returns `400`',
            schema: {
              type: 'array',
              items: {
                anyOf: [
                  { pattern: '^name:.*$', type: 'string' },
                  { pattern: '^id:.*$', type: 'string' },
                  { pattern: '^is_default:(true|false)$', type: 'string' },
                ],
                type: 'string',
              },
            },
            examples: {
              filterByIsDefault: { summary: 'Only default locations', value: ['is_default:true'] },
              filterByNameAndIsDefault: {
                summary: 'Default locations whose name contains "prod"',
                value: ['name:prod', 'is_default:true'],
              },
            },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description:
              'Case-insensitive substring match on the location name. When combined\nwith `filter`, both must match (logical AND).',
            schema: { type: 'string' },
            required: false,
          },
        }),
      order_by: z
        .enum(['name', 'created_at', 'updated_at'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description:
              'Field to sort the returned locations by. When omitted, the order of\nresults is unspecified. Supported values:\n  * `name` — sort alphabetically by location name.\n  * `created_at` — sort by creation time; defaults to descending unless `direction` is set.\n  * `updated_at` — sort by last-modified time; defaults to descending unless `direction` is set.',
            schema: { type: 'string', enum: ['name', 'created_at', 'updated_at'] },
            required: false,
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            description:
              'Sort direction. Only takes effect when `order_by` is also provided; it\nis ignored otherwise. When `direction` is omitted the effective\ndirection is field-specific: `created_at` and `updated_at` default to\ndescending (newest first); `name` defaults to ascending.\n  * `asc` — ascending.\n  * `desc` — descending.',
            schema: { type: 'string', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Lists Zero Trust Gateway locations response.',
      content: { 'application/json': { schema: ZeroTrustGatewayResponseCollection_5Schema } },
    },
    '4XX': {
      description: 'Lists Zero Trust Gateway locations response failure.',
      content: {
        'application/json': {
          schema: ZeroTrustGatewayResponseCollection_5Schema.and(
            ZeroTrustGatewayApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

