export const getAccountsAccountIdImagesV2Route = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/images/v2',
  tags: ['Cloudflare Images'],
  summary: 'List images V2',
  description:
    "List up to 10000 images from CF Images, with up to 1000 results per page. Use the optional parameters below to get a specific range of images.\nPagination is supported via continuation_token.\n\n**Metadata Filtering (Optional):**\n\nYou can optionally filter images by custom metadata fields using the `meta.<field>[<operator>]=<value>` syntax.\n\n**Supported Operators:**\n- `eq` / `eq:string` / `eq:number` / `eq:boolean` - Exact match\n- `gt` / `gt:number` - Greater than (number only)\n- `gte` / `gte:number` - Greater than or equal (number only)\n- `lt` / `lt:number` - Less than (number only)\n- `lte` / `lte:number` - Less than or equal (number only)\n- `in` / `in:string` / `in:number` - Match any value in list (pipe-separated)\n\n**Metadata Filter Constraints:**\n- Maximum 5 metadata filters per request\n- Maximum 5 levels of nesting (e.g., `meta.first.second.third.fourth.fifth`)\n- Maximum 10 elements for list operators (`in`)\n- Supports string, number, and boolean value types\n- Range operators (`gt`, `gte`, `lt`, `lte`) only accept numeric values\n\n**Filter Consistency:**\nFilters are combined with AND logic. The system does not validate whether filter combinations are logically consistent. For example, `meta.priority[eq:number]=5&meta.priority[lte:number]=3` will return zero results because no value can satisfy both conditions simultaneously. It is the caller's responsibility to ensure filter combinations make sense.\n\n**Examples:**\n```\n# List all images\n/images/v2\n\n# Filter by metadata [eq]\n/images/v2?meta.status[eq:string]=active\n\n# Filter by metadata [in]\n/images/v2?meta.status[in]=pending|deleted|flagged\n\n# Filter by metadata [in:number]\n/images/v2?meta.ratings[in:number]=4|5\n\n# Filter by metadata range [gte:number]\n/images/v2?meta.priority[gte:number]=1\n\n# Filter by bounded range\n/images/v2?meta.priority[gte:number]=1&meta.priority[lte:number]=5\n\n# Filter by nested metadata\n/images/v2?meta.region.name[eq]=eu-west\n\n# Combine metadata filters with creator\n/images/v2?meta.status[eq]=active&creator=user123\n\n# Multiple metadata filters (AND logic)\n/images/v2?meta.status[eq]=active&meta.priority[eq:number]=5\n```\n",
  operationId: 'cloudflare-images-list-images-v2',
  request: {
    params: z.object({
      account_id: ImagesAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/images_account_identifier' },
        },
      }),
    }),
    query: z.object({
      continuation_token: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        ImagesImagesListContinuationTokenSchema.openapi({
          param: {
            name: 'continuation_token',
            in: 'query',
            schema: { $ref: '#/components/schemas/images_images_list_continuation_token' },
            required: false,
          },
        }),
      ).exactOptional(),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(10).max(10000),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of items per page',
              type: 'number',
              default: 1000,
              maximum: 10000,
              minimum: 10,
            },
            required: false,
          },
          description: 'Number of items per page',
        }),
      sort_order: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort_order',
            in: 'query',
            schema: {
              description: 'Sorting order by upload time',
              type: 'string',
              default: 'desc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Sorting order by upload time',
        }),
      creator: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'creator',
            in: 'query',
            schema: {
              description:
                'Internal user ID set within the creator field. Setting to empty string "" will return images where creator field is not set',
              type: 'string',
              nullable: true,
            },
            required: false,
          },
          description:
            'Internal user ID set within the creator field. Setting to empty string "" will return images where creator field is not set',
        }),
      'meta.<field>[<operator>]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'meta.<field>[<operator>]',
            in: 'query',
            description:
              'Optional metadata filter(s). Multiple filters can be combined with AND logic.\n\n**Operators:**\n- `eq`, `eq:string`, `eq:number`, `eq:boolean` - Exact match\n- `gt`, `gt:number` - Greater than (number only)\n- `gte`, `gte:number` - Greater than or equal (number only)\n- `lt`, `lt:number` - Less than (number only)\n- `lte`, `lte:number` - Less than or equal (number only)\n- `in`, `in:string`, `in:number` - Match any value in pipe-separated list\n\n**Examples:**\n- `meta.status[eq]=active`\n- `meta.priority[eq:number]=5`\n- `meta.enabled[eq:boolean]=true`\n- `meta.priority[gte:number]=1`\n- `meta.score[lt:number]=100`\n- `meta.region[in]=us-east|us-west|eu-west`\n\n**Note:** Filter consistency is not validated. Contradictory filters (e.g., `meta.priority[eq:number]=5&meta.priority[lte:number]=3`) will return zero results.\n',
            schema: { type: 'string' },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List images response',
      content: { 'application/json': { schema: ImagesImagesListResponseV2Schema } },
    },
    400: {
      description: 'Bad request',
      content: {
        'application/json': {
          schema: ImagesApiResponseCommonFailureSchema,
          examples: {
            invalid_operator: {
              summary: 'Invalid metadata operator',
              value: {
                errors: [{ code: 5400, message: "Unsupported metadata filter operator: 'not-eq'" }],
                messages: [],
                result: null,
                success: false,
              },
            },
            too_many_filters: {
              summary: 'Too many metadata filters',
              value: {
                errors: [
                  {
                    code: 5400,
                    message: 'Too many metadata filters: 6 provided, maximum 5 allowed',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
    '4XX': {
      description: 'List images response failure',
      content: { 'application/json': { schema: ImagesApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const postAccountsAccountIdImagesV2DirectUploadRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/images/v2/direct_upload',
  tags: ['Cloudflare Images'],
  summary: 'Create authenticated direct upload URL V2',
  description:
    'Direct uploads allow users to upload images without API keys. A common use case are web apps, client-side applications, or mobile devices where users upload content directly to Cloudflare Images. This method creates a draft record for a future image. It returns an upload URL and an image identifier. To verify if the image itself has been uploaded, send an image details request (accounts/:account_identifier/images/v1/:identifier), and check that the `draft: true` property is not present.',
  operationId: 'cloudflare-images-create-authenticated-direct-upload-url-v-2',
  request: {
    params: z.object({
      account_id: ImagesAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/images_account_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              creator: z
                .string()
                .exactOptional()
                .openapi({ description: 'Can set the creator field with an internal user ID.' }),
              expiry: z.iso
                .datetime({ offset: true })
                .default('Now + 30 minutes')
                .exactOptional()
                .openapi({
                  description:
                    'The date after which the upload will not be accepted. Minimum: Now + 2 minutes. Maximum: Now + 6 hours.',
                  example: '2021-01-02T02:20:00Z',
                  'x-auditable': true,
                }),
              id: z
                .string()
                .max(1024)
                .exactOptional()
                .openapi({
                  description:
                    'Optional Image Custom ID. Up to 1024 chars. Can include any number of subpaths, and utf8 characters. Cannot start nor end with a / (forward slash). Cannot be a UUID.',
                  example: 'this/is/my-customid',
                  'x-auditable': true,
                }),
              metadata: z
                .object({})
                .exactOptional()
                .openapi({
                  description:
                    'User modifiable key-value store. Can be used for keeping references to another system of record, for managing images.',
                }),
              requireSignedURLs: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Indicates whether the image requires a signature token to be accessed.',
                  example: true,
                  'x-auditable': true,
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Create authenticated direct upload URL V2 response',
      content: { 'application/json': { schema: ImagesImageDirectUploadResponseV2Schema } },
    },
    '4XX': {
      description: 'Create authenticated direct upload URL V2 response failure',
      content: {
        'application/json': {
          schema: z.union([
            ImagesImageDirectUploadResponseV2Schema,
            ImagesApiResponseCommonFailureSchema,
          ]),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

