export const getAccountsAccountIdIntelDomainBulkRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/intel/domain/bulk',
  tags: ['Domain Intelligence'],
  summary: 'Get Multiple Domain Details',
  description:
    'Returns security details and statistics about multiple domains in a\nsingle request.\n\n**Behavior change — domain ranking is becoming opt-in.** This endpoint\npreviously included domain ranking data in every response and accepted\na `skip_ranking=true` query parameter to opt out. That parameter is\nbeing deprecated and ranking will no longer be returned by default.\nCallers that want ranking data must pass `include_ranking=true`. The\n`skip_ranking` parameter will be silently ignored once the change ships.\n',
  operationId: 'domain-intelligence-get-multiple-domain-details',
  request: {
    params: z.object({
      account_id: IntelIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/intel_identifier' },
        },
      }),
    }),
    query: z.object({
      domain: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'domain',
            in: 'query',
            description:
              'Accepts multiple values like `?domain=cloudflare.com&domain=example.com`.',
            schema: { type: 'array', items: { type: 'string' } },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      include_ranking: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_ranking',
            in: 'query',
            description:
              'Whether to include domain ranking data in the response. Defaults to\n`false` — ranking lookups are expensive at bulk scale and most\ncallers do not need them. Set to `true` to opt in. This parameter\nreplaces the deprecated `skip_ranking` (see below).\n',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      skip_ranking: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'skip_ranking',
            in: 'query',
            description:
              "**Deprecated.** Previously controlled whether the ranking lookup\nwas skipped (defaulted to `false`, meaning ranking ran). The\nendpoint's default behavior is being flipped — ranking is now\nopt-in via `include_ranking=true` — and this parameter will be\nsilently ignored. Remove it from your callers and use\n`include_ranking` instead.\n",
            schema: { type: 'boolean' },
            deprecated: true,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get Multiple Domain Details response.',
      content: { 'application/json': { schema: IntelCollectionResponseSchema } },
    },
    '4XX': {
      description: 'Get Multiple Domain Details response failure.',
      content: {
        'application/json': {
          schema: IntelCollectionResponseSchema.and(IntelApiResponseCommonFailureSchema),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

