export const putAccountsAccountIdIntelIndicatorFeedsFeedIdSnapshotRoute = createRoute({
  method: 'put',
  path: '/accounts/{account_id}/intel/indicator-feeds/{feed_id}/snapshot',
  tags: ['Custom Indicator Feeds'],
  summary: 'Update indicator feed data',
  description:
    'Revises the raw data entries in a custom threat indicator feed.\n\nAccepts both plain and gzipped STIX2/CRDF bodies. Gzip is\ndetected by RFC 1952 magic bytes (`0x1f 0x8b`) and/or a `.gz`\nfilename suffix (case-insensitive) — either signal alone is\nsufficient to trigger the gzip path; if the body is not valid\ngzip, the upload fails fast. Customers are encouraged to gzip\nlarger uploads — the api-gateway 500 MB body cap applies to\nthe on-the-wire (compressed) size, so gzip lets a single\nupload carry several GiB of decompressed STIX.\n',
  operationId: 'custom-indicator-feeds-update-indicator-feed-data',
  request: {
    params: z.object({
      account_id: CustomIndicatorFeedsIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/custom-indicator-feeds_identifier' },
        },
      }),
      feed_id: z.preprocess(
        (val) =>
          typeof val === 'string' &&
          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
            ? Number(val)
            : val,
        CustomIndicatorFeedsFeedIdSchema.openapi({
          param: {
            name: 'feed_id',
            in: 'path',
            required: true,
            schema: { $ref: '#/components/schemas/custom-indicator-feeds_feed_id' },
          },
        }),
      ),
    }),
    headers: z.object({
      'Cf-Async-Upload': z
        .literal('1')
        .exactOptional()
        .openapi({
          param: {
            name: 'Cf-Async-Upload',
            in: 'header',
            description:
              'Set to the literal value `1` to enqueue the upload and receive a\n`202` response with a polling URL. Any other value uses the legacy\nsynchronous response.\n',
            schema: { type: 'string', enum: ['1'] },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              source: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The file to upload. Either a plain STIX2/CRDF body\nor a gzipped one (recognised by `0x1f 0x8b` magic\nbytes or a `.gz` filename suffix).\n',
                  example: '@/Users/me/test.stix2.gz',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Get indicator feed metadata',
      content: { 'application/json': { schema: CustomIndicatorFeedsUpdateFeedResponseSchema } },
    },
    202: {
      description: 'Upload accepted for asynchronous processing',
      content: { 'application/json': { schema: CustomIndicatorFeedsEnqueueUploadResponseSchema } },
    },
    413: {
      description:
        'Decompressed upload exceeds the maximum allowed size. The\nserver caps the decompressed body at a configured limit\n(default 6 GiB) as a gzip-bomb defence; this response is\nreturned before any feed state changes. Resubmit a smaller\n(or non-pathologically-compressed) body.\n',
      content: {
        'application/json': { schema: CustomIndicatorFeedsApiResponseCommonFailureSchema },
      },
    },
    '4XX': {
      description: 'Get indicator feeds response failure',
      content: {
        'application/json': { schema: CustomIndicatorFeedsApiResponseCommonFailureSchema },
      },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

export const getAccountsAccountIdIntelIndicatorFeedsFeedIdUploadsUploadIdRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/intel/indicator-feeds/{feed_id}/uploads/{upload_id}',
  tags: ['Custom Indicator Feeds'],
  summary: 'Get indicator feed upload status',
  description:
    'Polls an asynchronously accepted upload. Continue polling after the\nrecommended `poll_after_seconds` delay until status is `Unified` or\n`Error`. `Unified` is returned only after the durable loader finishes.\n',
  operationId: 'custom-indicator-feeds-get-upload-status',
  request: {
    params: z.object({
      account_id: CustomIndicatorFeedsIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/custom-indicator-feeds_identifier' },
        },
      }),
      feed_id: z.preprocess(
        (val) =>
          typeof val === 'string' &&
          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
            ? Number(val)
            : val,
        CustomIndicatorFeedsFeedIdSchema.openapi({
          param: {
            name: 'feed_id',
            in: 'path',
            required: true,
            schema: { $ref: '#/components/schemas/custom-indicator-feeds_feed_id' },
          },
        }),
      ),
      upload_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'upload_id',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Current upload status',
      content: { 'application/json': { schema: CustomIndicatorFeedsUploadStatusResponseSchema } },
    },
    '4XX': {
      description: 'Upload status lookup failure',
      content: {
        'application/json': {
          schema: CustomIndicatorFeedsUploadStatusResponseSchema.and(
            CustomIndicatorFeedsApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

