export const getAccountsAccountIdLogpushTransformersTransformerIdContentRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/logpush/transformers/{transformer_id}/content',
  tags: ['Logpush transformers'],
  summary: 'Get transformer content',
  description:
    'Returns the SQL query content for a transformer. Without query params, returns the latest version. With `version_id`, returns the specified version.',
  operationId: 'get-accounts-account_id-logpush-transformers-transformer_id-content',
  request: {
    params: z.object({
      account_id: LogpushIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/logpush_identifier' },
        },
      }),
      transformer_id: z.preprocess(
        (val) =>
          typeof val === 'string' &&
          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
            ? Number(val)
            : val,
        LogpushTransformerIdentifierSchema.openapi({
          param: {
            name: 'transformer_id',
            in: 'path',
            required: true,
            schema: { $ref: '#/components/schemas/logpush_transformer_identifier' },
          },
        }),
      ),
    }),
    query: z.object({
      version_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'version_id',
            in: 'query',
            description:
              'Specific version ID to retrieve. When omitted, the latest version is returned.',
            schema: { type: 'integer', format: 'int64' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get transformer content response.',
      content: { 'application/json': { schema: LogpushTransformerContentResponseSchema } },
    },
    '4XX': {
      description: 'Get transformer content response failure.',
      content: { 'application/json': { schema: LogpushApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

