export const getAccountsAccountIdMagicCloudResourcesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/magic/cloud/resources',
  tags: ['Resources'],
  summary: 'List Resources',
  description: 'List resources in the Resource Catalog (Closed Beta).',
  operationId: 'resources-catalog-list',
  request: {
    params: z.object({
      account_id: McnAccountIdSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/mcn_account_id' },
        },
      }),
    }),
    query: z.object({
      provider_id: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'provider_id', in: 'query', schema: { type: 'string' }, required: false },
        }),
      resource_type: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(McnResourceTypeSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'resource_type',
            in: 'query',
            schema: { type: 'array', items: { $ref: '#/components/schemas/mcn_resource_type' } },
            required: false,
          },
        }),
      resource_id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(McnResourceIdSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'resource_id',
            in: 'query',
            schema: { type: 'array', items: { $ref: '#/components/schemas/mcn_resource_id' } },
            required: false,
          },
        }),
      region: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'region', in: 'query', schema: { type: 'string' }, required: false },
        }),
      resource_group: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'resource_group',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      managed: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { name: 'managed', in: 'query', schema: { type: 'boolean' }, required: false },
        }),
      search: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            schema: { type: 'array', items: { type: 'string' } },
            required: false,
          },
        }),
      order_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description: 'One of ["id", "resource_type", "region"].',
            schema: { type: 'string' },
            required: false,
          },
        }),
      desc: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { name: 'desc', in: 'query', schema: { type: 'boolean' }, required: false },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: { type: 'integer', minimum: 1 },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: { type: 'integer', minimum: 1 },
            required: false,
          },
        }),
      cloudflare: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { name: 'cloudflare', in: 'query', schema: { type: 'boolean' }, required: false },
        }),
      v2: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { name: 'v2', in: 'query', schema: { type: 'boolean' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK.',
      content: { 'application/json': { schema: McnReadAccountResourcesResponseSchema } },
    },
    400: {
      description: 'Bad Request.',
      content: { 'application/json': { schema: McnBadResponseSchema } },
    },
    401: {
      description: 'Invalid Credentials.',
      content: { 'application/json': { schema: McnBadResponseSchema } },
    },
    403: {
      description: 'Forbidden.',
      content: { 'application/json': { schema: McnBadResponseSchema } },
    },
    404: {
      description: 'Not Found.',
      content: { 'application/json': { schema: McnBadResponseSchema } },
    },
    500: {
      description: 'Internal Server Error.',
      content: { 'application/json': { schema: McnBadResponseSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

