export const getAccountsAccountIdMembersRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/members',
  tags: ['Account Members'],
  summary: 'List Members',
  description: 'List all members of an account.',
  operationId: 'account-members-list-members',
  request: {
    params: z.object({
      account_id: IamAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/iam_account_identifier' },
        },
      }),
    }),
    query: z.object({
      order: z
        .enum(['user.first_name', 'user.last_name', 'user.email', 'status'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              description: 'Field to order results by.',
              example: 'status',
              enum: ['user.first_name', 'user.last_name', 'user.email', 'status'],
            },
            required: false,
          },
          description: 'Field to order results by.',
          example: 'status',
        }),
      status: z
        .enum(['accepted', 'pending', 'rejected'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            schema: {
              description: "A member's status in the account.",
              type: 'string',
              example: 'accepted',
              enum: ['accepted', 'pending', 'rejected'],
            },
            required: false,
          },
          description: "A member's status in the account.",
          example: 'accepted',
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Maximum number of results per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Maximum number of results per page.',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Direction to order results.',
              type: 'string',
              example: 'desc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Direction to order results.',
          example: 'desc',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Members response',
      content: { 'application/json': { schema: IamCollectionMemberResponseWithPoliciesSchema } },
    },
    '4XX': {
      description: 'List Members response failure',
      content: { 'application/json': { schema: IamApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

