export const getAccountsAccountIdMoqRelaysRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/moq/relays',
  tags: ['MoQ Relays'],
  summary: 'List relays',
  description:
    'Lists all MoQ relays for the account. Returns only metadata.\nConfig, status, and tokens are omitted.\n\nResults are cursor-paginated (keyset on the `created` timestamp).\nUse `created_before` / `created_after` with the `created` value of the\nfirst/last item in a page to fetch the adjacent page. `result_info`\nreports the page `count` and the `total` matching the cursor filters.\n',
  operationId: 'moq-relays-list',
  request: {
    params: z.object({ account_id: MoqAccountIdParamsSchema }),
    query: z.object({
      created_before: MoqCreatedBeforeParamsSchema,
      created_after: MoqCreatedAfterParamsSchema,
      per_page: MoqPerPageParamsSchema,
      asc: MoqAscParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Relay list retrieved successfully.',
      content: {
        'application/json': {
          schema: MoqApiResponseCommonSchema.and(
            z
              .object({
                result: z.array(MoqRelayListItemSchema).exactOptional(),
                result_info: MoqResultInfoSchema.exactOptional(),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Error 10005: Invalid cursor, pagination, or sort parameter.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    500: {
      description: 'Error 21006: Unexpected server error.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
  },
  security: [{ api_token: [] }],
})

export const postAccountsAccountIdMoqRelaysRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/moq/relays',
  tags: ['MoQ Relays'],
  summary: 'Create a relay',
  description:
    'Provisions a new MoQ relay instance. Auto-creates a publish+subscribe\ntoken and a subscribe-only token. Token values are included in the\nresponse (shown once). Config is always set to defaults (upstreams\noff) and cannot be supplied here — sending a non-empty `config` is\nrejected (21014); `null` or `{}` is accepted as absent. Use PUT to\nconfigure the relay after it exists.\n',
  operationId: 'moq-relays-create',
  request: {
    params: z.object({ account_id: MoqAccountIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .min(1)
                .openapi({
                  description: 'Human-readable name for the relay.',
                  example: 'Production Live Stream',
                }),
            })
            .openapi({ required: ['name'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Relay created successfully.',
      content: {
        'application/json': {
          schema: MoqApiResponseCommonSchema.and(
            z
              .object({ result: MoqRelayCreateResponseSchema.exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    400: {
      description:
        'Bad request. Possible errors:\n- 21002: Request body too small\n- 21004: Failed to decode body (invalid JSON)\n- 21011: Invalid relay name (must not be empty)\n- 21014: Config cannot be set on create (set it via PUT after the relay exists)\n',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    409: {
      description: 'Error 21008: Relay limit exceeded for this account.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    413: {
      description: 'Error 21001: Request body too large.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    500: {
      description: 'Error 21006: Unexpected server error.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
  },
  security: [{ api_token: [] }],
})

