export const postAccountsAccountIdMoqRelaysRelayIdTokensRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/moq/relays/{relay_id}/tokens',
  tags: ['MoQ Relays'],
  summary: 'Create a token',
  description:
    "Mints a new relay-scoped token and adds it to the relay's accepted-auth\nregistry. The token value (secret) is shown once in the response. A relay\nmay hold up to 10 tokens; creating an 11th is rejected.\n",
  operationId: 'moq-relays-tokens-create',
  request: {
    params: z.object({ account_id: MoqAccountIdParamsSchema, relay_id: MoqRelayIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              expires: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'Optional expiry (RFC 3339). Defaults to 1 year from creation;\nrejected if more than 1 year in the future.\n',
                  example: '2027-03-27T15:00:00Z',
                }),
              label: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Optional, customer-set label.',
                  example: 'primary-encoder',
                }),
              operations: z
                .array(z.enum(['publish', 'subscribe']))
                .min(1)
                .openapi({
                  description:
                    'Non-empty subset of the V1 roles the token is allowed to\nperform. Signed into the token.\n',
                  example: ['publish', 'subscribe'],
                }),
            })
            .openapi({ required: ['operations'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Token created. The secret is shown once.',
      content: {
        'application/json': {
          schema: MoqApiResponseCommonSchema.and(
            z.object({ result: MoqTokensEnvelopeSchema.exactOptional() }).openapi({ required: [] }),
          ),
        },
      },
    },
    400: {
      description:
        'Bad request. Possible errors: 21003 (relay ID should be 32 hex characters), 21004 (failed to decode body, invalid JSON), 21010 (invalid operations), 21012 (expires more than 1 year out).',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    404: {
      description: 'Error 21007: Relay not found.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    409: {
      description: 'Error 21009: Token limit reached (a relay may hold at most 10 tokens).',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
    500: {
      description: 'Error 21006: Unexpected server error.',
      content: { 'application/json': { schema: MoqApiResponseErrorSchema } },
    },
  },
  security: [{ api_token: [] }],
})

