export const getAccountsAccountIdPagesProjectsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/pages/projects',
  tags: ['Pages Project'],
  summary: 'List Cloudflare Pages projects',
  description: 'List the Cloudflare Pages projects in an account.',
  operationId: 'pages-project-get-projects',
  request: {
    params: z.object({
      account_id: PagesIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/pages_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of results to return.',
              type: 'integer',
              example: 1,
            },
            required: false,
          },
          description: 'Page number of results to return.',
          example: 1,
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of results to return per page.',
              type: 'integer',
              example: 10,
            },
            required: false,
          },
          description: 'Number of results to return per page.',
          example: 10,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get projects response.',
      content: {
        'application/json': {
          schema: PagesApiResponseCollectionSchema.and(
            z.object({ result: z.array(PagesProjectSchema) }).openapi({ required: ['result'] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Get projects response failure.',
      content: { 'application/json': { schema: PagesApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

