export const getAccountsAccountIdPayPerUseEnabledDomainsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/pay-per-use/enabled-domains',
  tags: ['ppu_enabled_domains'],
  summary: 'List enabled Pay Per Use domains',
  description:
    'Returns publisher domains associated with the requesting Pay Per Use operator through an accepted price agreement. License expiration is the earlier non-null boundary from the price agreement and publisher zone lifecycles. A future expiration remains active and is exposed to the operator. After expiration, the license remains listed as expired for one calendar month before it is omitted; an active agreement for the same domain takes precedence. The requesting account must be an active Pay Per Use operator.',
  operationId: 'pay-per-use.listEnabledDomains',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            description: 'Account identifier for the participant',
            required: true,
            schema: { type: 'string' },
            'x-auditable': true,
          },
        }),
    }),
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            description:
              'Opaque, account-bound cursor returned by the previous page. Cursors expire after one hour; restart pagination without a cursor after receiving a 400 response for an expired cursor.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Maximum number of domains to return',
            schema: { type: 'integer', default: 100, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Enabled domains returned successfully',
      content: { 'application/json': { schema: PayPerCrawlEnabledDomainsResponseSchema } },
    },
    400: {
      description: 'Invalid cursor or page size',
      content: { 'application/json': { schema: PayPerCrawlApiErrorResponseSchema } },
    },
    401: {
      description: 'Invalid or insufficiently scoped API token',
      content: { 'application/json': { schema: PayPerCrawlApiErrorResponseSchema } },
    },
    403: {
      description: 'Account is not an active Pay Per Use operator',
      content: { 'application/json': { schema: PayPerCrawlApiErrorResponseSchema } },
    },
    500: {
      description: 'Enabled domains could not be retrieved',
      content: { 'application/json': { schema: PayPerCrawlApiErrorResponseSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

