export const getAccountsAccountIdPayPerUseUsageStatsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/pay-per-use/usage-stats',
  tags: ['ppu_usage_stats'],
  summary: 'Get pay-per-use usage statistics',
  description:
    'Returns reported usage and the full gross value across all Pay Per Use zones in a publisher account over an explicit UTC range of at most 31 days. Usage from every domain and snapshotted price is summed by buyer. Ranges up to and including 7 days use hourly data points; longer ranges use daily data points. Because source data is aggregated hourly, both requested bounds are rounded down to the selected UTC interval and the resolved bounds are returned in the response. The resolved range must contain at least one complete interval. Empty periods are omitted. Buyers and their data points are paginated, while totals cover every buyer in the range. Values are raw usage counts and USD microcents; total_price_usd_microcents is the full value before the publisher revenue share.',
  operationId: 'pay-per-crawl.getPPUUsageStats',
  request: {
    params: z.object({ account_id: PayPerCrawlAccountIDParamsSchema }),
    query: z.object({
      since: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'since',
            in: 'query',
            description:
              'Requested inclusive beginning of the statistics range as an RFC3339 timestamp. Rounded down to the selected UTC interval.',
            required: true,
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      until: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'until',
            in: 'query',
            description:
              'Requested exclusive end of the statistics range as an RFC3339 timestamp. Rounded down to the selected UTC interval. The requested duration from since cannot exceed 31 days.',
            required: true,
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      page: PayPerCrawlPPUPageParamsSchema,
      per_page: PayPerCrawlPPUPerPageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Usage statistics returned successfully',
      content: { 'application/json': { schema: PayPerCrawlPPUUsageStatsResponseSchema } },
    },
    400: PayPerCrawlPPUBadRequestResponse,
    403: PayPerCrawlPPUForbiddenResponse,
    500: {
      description: 'Usage statistics could not be retrieved',
      content: { 'application/json': { schema: PayPerCrawlApiErrorResponseSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

