export const getAccountsAccountIdPaymentMethodsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/payment-methods',
  tags: ['Account Payment Methods'],
  summary: 'List Payment Methods',
  description: 'Lists all payment methods for an account.',
  operationId: 'account-billing-list-payment-methods',
  request: {
    params: z.object({
      account_id: BillSubsApiIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/bill-subs-api_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'integer',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of items per page.',
              type: 'integer',
              default: 20,
              minimum: 1,
            },
            required: false,
          },
          description: 'Number of items per page.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Payment Methods response',
      content: { 'application/json': { schema: BillSubsApiPaymentMethodResponseCollectionSchema } },
    },
    '4XX': {
      description: 'List Payment Methods response failure',
      content: { 'application/json': { schema: BillSubsApiApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

