export const deleteAccountsAccountIdR2BucketsBucketNameObjectsRoute = createRoute({
  method: 'delete',
  path: '/accounts/{account_id}/r2/buckets/{bucket_name}/objects',
  tags: ['R2 Object'],
  summary: 'Delete Objects',
  description:
    "Deletes the listed objects from an R2 bucket. Provide a JSON array of 1 to 1000 object\nkeys in the request body.\n\nIf any key cannot be deleted (for example, because it does not exist or is locked), the\nremaining keys are still deleted, but the response is HTTP 200 with `success: false`,\n`result: null` and one entry in `errors` per failed key. The entries in `errors` do not\nidentify which key failed.\n\nTo delete every object under a prefix, or to empty a bucket, create a `prefixDelete` job\nwith the Create Bucket Job endpoint instead. The `prefix` query parameter on this endpoint\nis deprecated; it creates the same job, but responses to it carry a `Deprecation` header\nand a message pointing to Create Bucket Job.\n\nFor most workloads, we recommend using R2's [S3-compatible API](https://developers.cloudflare.com/r2/api/s3/api/) or a [Worker with an R2 binding](https://developers.cloudflare.com/r2/api/workers/workers-api-reference/) instead.\n",
  operationId: 'r2-delete-objects',
  request: {
    params: z.object({
      account_id: R2AccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/r2_account_identifier' },
        },
      }),
      bucket_name: R2BucketNameSchema.openapi({
        param: {
          name: 'bucket_name',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/r2_bucket_name' },
        },
      }),
    }),
    headers: z.object({
      'cf-r2-jurisdiction': R2CfR2JurisdictionParamsSchema,
      'cf-r2-data-catalog-check': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cf-r2-data-catalog-check',
            in: 'header',
            description:
              'Set this header to reject the operation when R2 Data Catalog is enabled for the bucket.',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
    query: z.object({
      prefix: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'prefix',
            in: 'query',
            description:
              'Deprecated. Create a `prefixDelete` job with the Create Bucket Job endpoint instead.\nWhen present, the request body is ignored and a prefix-delete job is created for this\nprefix, exactly as Create Bucket Job does; an empty value empties the bucket. The\nresponse is the job descriptor, with a `Deprecation` header and a deprecation message\nin `messages`.\n',
            schema: { type: 'string' },
            deprecated: true,
            required: false,
          },
        }),
    }),
    body: {
      description:
        'A JSON array of 1 to 1000 object keys to delete. Required unless the deprecated `prefix` parameter is present.',
      content: {
        'application/json': {
          schema: z
            .array(z.string())
            .min(1)
            .max(1000)
            .openapi({ example: ['path/to/object-a.txt', 'path/to/object-b.txt'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'Delete Objects response. When every key is deleted, `result` contains a `{ key }` entry\nfor each deleted object. When any key fails, `success` is `false`, `result` is `null`\nand `errors` has one entry per failed key; the other keys are still deleted. With the\ndeprecated `prefix` parameter, `result` is the created prefix-delete job.\n',
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                errors: R2ErrorsSchema,
                messages: R2MessagesSchema,
                result: z
                  .array(R2R2DeleteObjectResultSchema)
                  .openapi({ description: 'The deleted objects.' }),
                success: z
                  .literal(true)
                  .openapi({ description: 'Whether the API call was successful.' }),
              })
              .openapi({
                required: ['success', 'errors', 'messages', 'result'],
                title: 'All keys deleted',
              }),
            R2V4ResponseFailureSchema,
            z
              .object({
                errors: R2ErrorsSchema,
                messages: R2MessagesSchema,
                result: R2PrefixDeleteJobSchema,
                success: z
                  .literal(true)
                  .openapi({ description: 'Whether the API call was successful.' }),
              })
              .openapi({
                deprecated: true,
                required: ['success', 'errors', 'messages', 'result'],
                title: 'Prefix-delete job created (deprecated)',
              }),
          ]),
          examples: {
            'all-deleted': {
              summary: 'Every key was deleted',
              value: {
                errors: [],
                messages: [],
                result: [{ key: 'path/to/object-a.txt' }, { key: 'path/to/object-b.txt' }],
                success: true,
              },
            },
            'partial-failure': {
              summary: 'One key did not exist; the other key was deleted',
              value: {
                errors: [{ code: 10007, message: 'The specified key does not exist.' }],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
    '4XX': {
      description:
        'Delete Objects response failure. The bucket may not exist, the request may be invalid, or the caller may not be authorized.',
      content: { 'application/json': { schema: R2V4ResponseFailureSchema } },
    },
  },
  security: [{ api_token: [] }],
})

