export const postAccountsAccountIdRealtimeKitAppIdMeetingsMeetingIdLivestreamsRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/realtime/kit/{app_id}/meetings/{meeting_id}/livestreams',
  tags: ['Live streams'],
  summary: 'Start livestreaming a meeting',
  description:
    'Starts livestream of a meeting associated with the given meeting ID. Retreive the meeting ID using the `Create a meeting` API.',
  operationId: 'start-livestreaming',
  request: {
    params: z.object({
      account_id: RealtimekitAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/realtimekit_account_identifier' },
        },
      }),
      app_id: RealtimekitAppIdSchema.openapi({
        param: {
          name: 'app_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/realtimekit_app_id' },
        },
      }),
      meeting_id: z
        .uuid()
        .openapi({
          param: {
            name: 'meeting_id',
            in: 'path',
            description: 'ID of the meeting',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .regex(/^[a-zA-Z0-9-_]*$/)
                .nullable()
                .exactOptional(),
              video_config: z
                .object({
                  height: z
                    .int()
                    .exactOptional()
                    .openapi({ description: 'Height of the livestreaming video in pixels' }),
                  width: z
                    .int()
                    .exactOptional()
                    .openapi({ description: 'Width of the livestreaming video in pixels' }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          examples: { 'example-1': { value: { name: 'prdmmp-xhycsl' } } },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z
                .object({
                  id: z.string().exactOptional().openapi({ description: 'The livestream ID.' }),
                  ingest_server: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The server URL to which the RTMP encoder sends the video and audio data.',
                    }),
                  playback_url: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The web address that viewers can use to watch the livestream.',
                    }),
                  status: z.enum(['LIVE', 'IDLE', 'ERRORED', 'INVOKED']).exactOptional(),
                  stream_key: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'Unique key for accessing each livestream.',
                      'x-sensitive': true,
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              success: z.boolean().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            'example-1': {
              value: {
                data: {
                  id: '7088bba8-f522-49a8-b59b-3cd0e946bbb0',
                  ingest_server: 'rtmps://live.cloudflare.com:443/live/',
                  playback_url:
                    'https://customer-s8oj0c1n5ek8ah1e.cloudflarestream.com/7de6a3fec0f9c05bf1df140950d3a237/manifest/video.m3u8',
                  status: 'INVOKED',
                  stream_key: 'f26566285faca6fbe2e79a73a66rsrrsrrsr3cde23a2bb7dbc6c2c1761b98f4e4',
                },
                success: true,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }],
})

