export const patchAccountsAccountIdRegistrarSandboxRegistrationsDomainNameRoute = createRoute({
  method: 'patch',
  path: '/accounts/{account_id}/registrar-sandbox/registrations/{domain_name}',
  tags: ['Registrar Registration'],
  summary: 'Update Registration',
  description:
    'Updates an existing domain registration.\n\nBy default, the server holds the connection for a bounded, server-defined\namount of time while the update completes. Most updates finish within this\nwindow and return `200 OK` with a completed workflow status.\n\nIf the update is still processing after this synchronous wait window, the\nserver returns `202 Accepted`. Poll the URL in `links.self` to track progress.\n\nTo skip the wait and receive an immediate `202`, send `Prefer: respond-async`.\n\nThis endpoint currently supports updating `auto_renew` only.\n',
  operationId: 'sandbox-registrar-domain-registration-update',
  request: {
    params: z.object({
      account_id: RegistrarApiSandboxIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          description: 'Cloudflare account ID.',
          required: true,
          schema: { $ref: '#/components/schemas/registrar-api-sandbox_identifier' },
        },
      }),
      domain_name: RegistrarApiSandboxDomainNameSchema.openapi({
        param: {
          name: 'domain_name',
          in: 'path',
          description: 'Domain name to update.',
          required: true,
          schema: { $ref: '#/components/schemas/registrar-api-sandbox_domain_name' },
        },
      }),
    }),
    headers: z.object({
      Prefer: z
        .literal('respond-async')
        .exactOptional()
        .openapi({
          param: {
            name: 'Prefer',
            in: 'header',
            description:
              'Set to `respond-async` to receive an immediate `202 Accepted` without\nwaiting for the operation to complete (RFC 7240).\n',
            schema: { type: 'string', enum: ['respond-async'] },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: RegistrarApiSandboxRegistrationUpdateRequestSchema,
          examples: {
            disable_auto_renew: { summary: 'Disable auto-renewal', value: { auto_renew: false } },
            enable_auto_renew: { summary: 'Enable auto-renewal', value: { auto_renew: true } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Update completed successfully within the synchronous wait window.\nThe workflow status will have `state: succeeded` and `completed: true`.\n',
      content: {
        'application/json': {
          schema: RegistrarApiSandboxWorkflowStatusResponseSingleSchema,
          examples: {
            completed: {
              summary: 'Update completed within timeout (most common)',
              value: {
                errors: [],
                messages: [],
                result: {
                  completed: true,
                  context: {
                    domain_name: 'example.com',
                    registration: {
                      auto_renew: true,
                      created_at: '2025-01-15T10:00:00Z',
                      domain_name: 'example.com',
                      expires_at: '2026-01-15T10:00:00Z',
                      locked: true,
                      privacy_mode: 'redaction',
                      status: 'active',
                    },
                  },
                  created_at: '2025-10-27T10:00:00Z',
                  links: {
                    resource: '/accounts/abc/registrar/registrations/example.com',
                    self: '/accounts/abc/registrar/registrations/example.com/update-status',
                  },
                  state: 'succeeded',
                  updated_at: '2025-10-27T10:00:02Z',
                },
                success: true,
              },
            },
          },
        },
      },
      headers: z.object({
        'Preference-Applied': {
          description: 'Echoed when the server honored a `Prefer` header.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Echoed when the server honored a `Prefer` header.',
              param: { required: false },
            }),
        },
      }),
    },
    202: {
      description:
        'Update is still processing. This occurs when the operation did not\ncomplete within the synchronous wait window, or when `Prefer: respond-async`\nwas sent. Poll the URL in `links.self` to track progress.\n',
      content: {
        'application/json': {
          schema: RegistrarApiSandboxWorkflowStatusResponseSingleSchema,
          examples: {
            still_processing: {
              summary: 'Update still in progress after timeout',
              value: {
                errors: [],
                messages: [],
                result: {
                  completed: false,
                  context: { domain_name: 'example.com' },
                  created_at: '2025-10-27T10:00:00Z',
                  links: {
                    resource: '/accounts/abc/registrar/registrations/example.com',
                    self: '/accounts/abc/registrar/registrations/example.com/update-status',
                  },
                  state: 'in_progress',
                  updated_at: '2025-10-27T10:00:10Z',
                },
                success: true,
              },
            },
          },
        },
      },
      headers: z.object({
        Location: {
          description: 'URL of the workflow status resource (same as `links.self`).',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'URL of the workflow status resource (same as `links.self`).',
              param: { required: false },
            }),
        },
        'Preference-Applied': {
          description: 'Set to `respond-async` when the server honored the preference.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Set to `respond-async` when the server honored the preference.',
              param: { required: false },
            }),
        },
      }),
    },
    '4XX': {
      description: 'Update registration failure.',
      content: {
        'application/json': {
          schema: RegistrarApiSandboxApiResponseCommonFailureSchema,
          examples: {
            domain_not_found: {
              summary: 'Domain not found',
              value: {
                errors: [{ code: 10000, message: 'Domain not found' }],
                messages: [],
                result: null,
                success: false,
              },
            },
            invalid_auto_renew: {
              summary: 'Invalid auto_renew value',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'Must be a boolean if present',
                    source: { pointer: '/auto_renew' },
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const getAccountsAccountIdRegistrarSandboxRegistrationsDomainNameRegistrationStatusRoute =
  createRoute({
    method: 'get',
    path: '/accounts/{account_id}/registrar-sandbox/registrations/{domain_name}/registration-status',
    tags: ['Registrar Registration'],
    summary: 'Get Registration Status',
    description:
      "Returns the current status of a domain registration workflow.\n\nUse this endpoint to poll for completion when the POST response\nreturned `202 Accepted`. The URL is provided in the `links.self`\nfield of the workflow status response.\n\nPoll this endpoint until the workflow reaches a terminal state or a\nstate that requires user attention.\n\n**Terminal states:** `succeeded` and `failed` are terminal and always\nhave `completed: true`.\n\n**Non-terminal states:**\n- `action_required` has `completed: false` and will not resolve on its\n  own. The workflow is paused pending user intervention.\n- `blocked` has `completed: false` and indicates the workflow is waiting\n  on a third party such as the extension registry or losing registrar.\n  Continue polling while informing the user of the delay.\n\nUse increasing backoff between polls. When `state: blocked`, use a\nlonger polling interval and do not poll indefinitely.\n\nA naive polling loop that only checks `completed` can run indefinitely\nwhen `state: action_required`. Break explicitly on `action_required`:\n\n```js\nlet status;\ndo {\n  await new Promise(r => setTimeout(r, 2000));\n  status = await cloudflare.request({\n    method: 'GET',\n    path: reg.result.links.self,\n  });\n} while (\n  !status.result.completed &&\n  status.result.state !== 'action_required'\n);\n\nif (status.result.state === 'action_required') {\n  // Surface context.action and context.confirmation_sent_to to the user.\n  // Do not re-submit the registration request.\n}\n```\n",
    operationId: 'sandbox-registrar-domain-registration-get-status',
    request: {
      params: z.object({
        account_id: RegistrarApiSandboxIdentifierSchema.openapi({
          param: {
            name: 'account_id',
            in: 'path',
            description: 'Cloudflare account ID. Required for all Registrar API operations.',
            required: true,
            schema: { $ref: '#/components/schemas/registrar-api-sandbox_identifier' },
          },
        }),
        domain_name: RegistrarApiSandboxDomainNameSchema.openapi({
          param: {
            name: 'domain_name',
            in: 'path',
            required: true,
            schema: { $ref: '#/components/schemas/registrar-api-sandbox_domain_name' },
          },
        }),
      }),
    },
    responses: {
      200: {
        description: 'Registration workflow status.',
        content: {
          'application/json': {
            schema: RegistrarApiSandboxWorkflowStatusResponseSingleSchema,
            examples: {
              action_required: {
                summary: 'User action required',
                description:
                  'Non-terminal but not transient. The workflow is paused and\nrequires user action to proceed. An automated polling loop\nmust break on this state — it will not resolve on its own.\nSurface context.action to the user.\n',
                value: {
                  errors: [],
                  messages: [],
                  result: {
                    completed: false,
                    context: {
                      action: 'registrant_email_confirmation_pending',
                      confirmation_sent_to: 'a***@example.com',
                      domain_name: 'example.com',
                    },
                    created_at: '2025-10-27T10:00:00Z',
                    links: {
                      resource: '/accounts/abc/registrar/registrations/example.com',
                      self: '/accounts/abc/registrar/registrations/example.com/registration-status',
                    },
                    state: 'action_required',
                    updated_at: '2025-10-27T10:01:00Z',
                  },
                  success: true,
                },
              },
              blocked: {
                summary: 'Blocked by third party',
                description:
                  "Non-terminal. The workflow cannot make progress due to a\nthird party (e.g., the extension's registry or a losing\nregistrar). Unlike action_required, no user action will help.\nContinue polling — the block may resolve when the third party\nresponds.\n",
                value: {
                  errors: [],
                  messages: [],
                  result: {
                    completed: false,
                    context: { domain_name: 'example.com' },
                    created_at: '2025-10-27T10:00:00Z',
                    links: {
                      resource: '/accounts/abc/registrar/registrations/example.com',
                      self: '/accounts/abc/registrar/registrations/example.com/registration-status',
                    },
                    state: 'blocked',
                    updated_at: '2025-10-27T10:05:00Z',
                  },
                  success: true,
                },
              },
              failed: {
                summary: 'Registration failed',
                description:
                  'Terminal state. The registration could not be completed.\nSee error.code and error.message for the reason. Do not\nauto-retry without user review.\n',
                value: {
                  errors: [],
                  messages: [],
                  result: {
                    completed: true,
                    context: { domain_name: 'example.com' },
                    created_at: '2025-10-27T10:00:00Z',
                    error: {
                      code: 'registry_rejected',
                      message: 'Registry rejected the registration request.',
                    },
                    links: {
                      resource: '/accounts/abc/registrar/registrations/example.com',
                      self: '/accounts/abc/registrar/registrations/example.com/registration-status',
                    },
                    state: 'failed',
                    updated_at: '2025-10-27T10:00:08Z',
                  },
                  success: true,
                },
              },
              in_progress: {
                summary: 'Registration in progress',
                description:
                  'The registration is still being processed. Continue polling\nthis endpoint. In synchronous mode, the server only waits\nfor a bounded amount of time before returning `202` — this\nstatus is what you see when polling after that timeout. Registrations\nwill not remain in this state indefinitely; the workflow has\nan internal deadline after which it transitions to succeeded,\nfailed, or blocked.\n',
                value: {
                  errors: [],
                  messages: [],
                  result: {
                    completed: false,
                    context: { domain_name: 'example.com' },
                    created_at: '2025-10-27T10:00:00Z',
                    links: {
                      resource: '/accounts/abc/registrar/registrations/example.com',
                      self: '/accounts/abc/registrar/registrations/example.com/registration-status',
                    },
                    state: 'in_progress',
                    updated_at: '2025-10-27T10:00:12Z',
                  },
                  success: true,
                },
              },
              succeeded: {
                summary: 'Registration completed successfully',
                description:
                  'Terminal state. The domain has been registered. The full\nregistration resource is included in context.registration —\nno additional GET request is needed.\n',
                value: {
                  errors: [],
                  messages: [],
                  result: {
                    completed: true,
                    context: {
                      domain_name: 'example.com',
                      registration: {
                        auto_renew: true,
                        created_at: '2025-10-27T10:00:00Z',
                        domain_name: 'example.com',
                        expires_at: '2026-10-27T10:00:00Z',
                        locked: true,
                        privacy_mode: 'redaction',
                        status: 'active',
                      },
                    },
                    created_at: '2025-10-27T10:00:00Z',
                    links: {
                      resource: '/accounts/abc/registrar/registrations/example.com',
                      self: '/accounts/abc/registrar/registrations/example.com/registration-status',
                    },
                    state: 'succeeded',
                    updated_at: '2025-10-27T10:00:03Z',
                  },
                  success: true,
                },
              },
            },
          },
        },
      },
      '4XX': {
        description: 'Get status failure.',
        content: {
          'application/json': {
            schema: RegistrarApiSandboxApiResponseCommonFailureSchema,
            examples: {
              workflow_not_found: {
                summary: 'No workflow found',
                value: {
                  errors: [{ code: 10000, message: 'No workflow found for example.com' }],
                  messages: [],
                  result: null,
                  success: false,
                },
              },
            },
          },
        },
      },
    },
    security: [{ api_token: [] }, { api_email: [], api_key: [] }],
  })

