export const postAccountsAccountIdRegistrarDomainTransferCheckRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/registrar/domain-transfer-check',
  tags: ['Domain Discovery'],
  summary: 'Check domain transfer eligibility',
  description:
    'Performs real-time, authoritative eligibility checks directly against needed requirements.\nUse this endpoint to verify a domain is available before\nattempting a transfer via `POST /registrations/:domain_name/transfer-in`.\n\n**Note:** This endpoint uses POST to accept a list of domains in the request\nbody. It is a read-only operation — it does not create, modify, or reserve\nany domains.\n\n### Behavior\n- Maximum 10 domains per request\n- Pricing is only returned for domains where `transferable: true`\n- Results are not cached; each request queries the registry & other needed upstreams\n\n## Extension Support\n\nAll `.uk` extensions (`.uk`, `.co.uk`, etc) do not support auth codes. As such,\nCloudflare will ignore the `auth_code` section of this request for `.uk` domains.\n\nThis means that a `.uk` domain depends on public data to obtain domain information,\nso it might be a few minutes outdated.\n\n### Workflow\n1. Call this endpoint with domains the user wants to transfer.\n2. For each domain where `transferable: true`, present pricing to the user.\n3. For each domain where `transferable: false`, present reasons to the user\n4. Proceed to `POST /registrations/:domain_name/transfer-in` only for the `transferable: true` domains.\n',
  operationId: 'registrar-domain-discovery-transfer-check',
  request: {
    params: z.object({
      account_id: RegistrarApiIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          description: 'Cloudflare account ID. Required for all Registrar API operations.',
          required: true,
          schema: { $ref: '#/components/schemas/registrar-api_identifier' },
        },
      }),
    }),
    body: {
      description: 'List of transferable domain objects to check.',
      content: {
        'application/json': {
          schema: RegistrarApiDomainTransferCheckRequestSchema,
          examples: {
            dot_uk_domain: {
              summary: 'Check a single `.uk` domain',
              description: 'Nominet, which is the `.uk` registry, does not support auth codes.',
              value: { domains: [{ domain_name: 'example.co.uk' }] },
            },
            multiple_domains: {
              summary: 'Check multiple domains',
              value: {
                domains: [
                  { auth_code: 'YXV0aF9jb2RlCg==', domain_name: 'example.com' },
                  { domain_name: 'example.uk' },
                  { auth_code: 'U2xlZXB5IEhvcnNlcwo=', domain_name: 'example.horse' },
                ],
              },
            },
            single_domain: {
              summary: 'Check single domain',
              value: {
                domains: [{ auth_code: 'SSdtIGEgc2VjcmV0IDozCg==', domain_name: 'example.com' }],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Successfully returned transfer eligibility results.\nEach requested domain appears in `result.domains` keyed by domain\nname. A domain result includes `name`, `transferable`, and `reasons`.\n',
      content: {
        'application/json': {
          schema: RegistrarApiDomainTransferCheckResponseSchema,
          examples: {
            all_transferable: {
              summary: 'All domains transferable',
              description: 'Every requested domain currently meets transfer prerequisites.',
              value: {
                errors: [],
                messages: [],
                result: {
                  domains: {
                    'example.com': {
                      name: 'example.com',
                      pricing: { currency: 'USD', renewal_cost: '10.11', transfer_cost: '8.57' },
                      reasons: [],
                      transferable: true,
                    },
                    'mybrand.net': {
                      name: 'mybrand.net',
                      pricing: { currency: 'USD', renewal_cost: '12.50', transfer_cost: '9.99' },
                      reasons: [],
                      transferable: true,
                    },
                  },
                },
                success: true,
              },
            },
            invalid_auth_code: {
              summary: 'Invalid auth code',
              description: 'The domain exists but the supplied auth code does not pass checks.',
              value: {
                errors: [],
                messages: [],
                result: {
                  domains: {
                    'example.com': {
                      name: 'example.com',
                      reasons: [{ code: 'invalid_auth_code' }],
                      transferable: false,
                    },
                  },
                },
                success: true,
              },
            },
            mixed_eligibility: {
              summary: 'Mixed transferability results',
              description: 'Some domains are transferable while others fail specific checks.',
              value: {
                errors: [],
                messages: [],
                result: {
                  domains: {
                    'cloudflare.com': {
                      name: 'cloudflare.com',
                      reasons: [{ code: 'domain_on_cloudflare' }],
                      transferable: false,
                    },
                    'locked-example.com': {
                      name: 'locked-example.com',
                      reasons: [{ code: 'domain_locked' }],
                      transferable: false,
                    },
                    'move-ready.net': {
                      name: 'move-ready.net',
                      pricing: { currency: 'USD', renewal_cost: '12.50', transfer_cost: '9.99' },
                      reasons: [],
                      transferable: true,
                    },
                    'pending-transfer.dev': {
                      name: 'pending-transfer.dev',
                      reasons: [{ code: 'registry_status' }],
                      transferable: false,
                    },
                  },
                },
                success: true,
              },
            },
            partial_upstream_failure: {
              summary: 'Partial results with top-level errors',
              description:
                'One or more domains failed internal upstream checks while others were evaluated successfully.',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'Internal API failure for domain flaky-example.com',
                    source: { pointer: '/domains/1' },
                  },
                ],
                messages: [],
                result: {
                  domains: {
                    'stable-example.com': {
                      name: 'stable-example.com',
                      pricing: { currency: 'USD', renewal_cost: '10.11', transfer_cost: '8.57' },
                      reasons: [],
                      transferable: true,
                    },
                  },
                },
                success: true,
              },
            },
            unsupported_or_invalid_domain: {
              summary: 'Unsupported extension or invalid domain format',
              description: 'Domain-level validation failures are returned as reason codes.',
              value: {
                errors: [],
                messages: [],
                result: {
                  domains: {
                    'example.horse': {
                      name: 'example.horse',
                      reasons: [{ code: 'extension_not_supported' }],
                      transferable: false,
                    },
                    'invalid@@domain': {
                      name: 'invalid@@domain',
                      reasons: [{ code: 'domain_unsupported' }],
                      transferable: false,
                    },
                  },
                },
                success: true,
              },
            },
          },
        },
      },
    },
    400: {
      description:
        'Invalid request body.\nCommon causes include:\n- Missing `domains` array.\n- Empty `domains` array.\n- More than 10 domains in one request.\n- Missing `domain_name` in a domain object.\n- Duplicate domain names in the request list.\n- Unexpected properties in the payload.\n',
      content: {
        'application/json': {
          schema: RegistrarApiApiResponseCommonFailureSchema,
          examples: {
            domains_missing: {
              summary: 'Missing domains field',
              description: 'The root payload must include a `domains` array.',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'object at root is missing required properties: domains',
                    source: { pointer: '/domains' },
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
            duplicate_domain_name: {
              summary: 'Duplicate domain name',
              description: 'Duplicate domain names are rejected to keep response keys unique.',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'Duplicate domain name',
                    source: { pointer: '/domains/1' },
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
            too_many_domains: {
              summary: 'Too many domains',
              description:
                'The request exceeds the maximum limit of 10 domains per request. Split into multiple requests.',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'array at `/domains` is too long (maximum: 10)',
                    source: { pointer: '/domains' },
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
    503: {
      description:
        'Transfer checks failed for all requested domains due to internal\nupstream errors.\n',
      content: {
        'application/json': {
          schema: RegistrarApiApiResponseCommonFailureSchema,
          examples: {
            all_domains_failed: {
              summary: 'All domain checks failed upstream',
              value: {
                errors: [
                  {
                    code: 10000,
                    message: 'Internal API failure for domain example.com',
                    source: { pointer: '/domains/0' },
                  },
                  {
                    code: 10000,
                    message: 'Internal API failure for domain mybrand.net',
                    source: { pointer: '/domains/1' },
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

