export const getAccountsAccountIdReportingIndustryRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/reporting/industry',
  tags: ['reports_other'],
  summary: 'Get an account industry',
  description: 'Gets the industry classification for an account.',
  operationId: 'reporting-industry-get',
  request: {
    params: z.object({
      account_id: z
        .string()
        .regex(/^[a-f0-9]{32}$/)
        .length(32)
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            required: true,
            schema: {
              description: 'Cloudflare public account ID (32-character hexadecimal string)',
              type: 'string',
              example: 'f1234567890abcdef1234567890abcdef',
              maxLength: 32,
              minLength: 32,
              pattern: '^[a-f0-9]{32}$',
            },
          },
          description: 'Cloudflare public account ID (32-character hexadecimal string)',
          example: 'f1234567890abcdef1234567890abcdef',
        }),
    }),
  },
  responses: {
    200: {
      description: "Account industry retrieved successfully (returns 'unknown' if not set)",
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(ReportsErrorSchema).default([]).exactOptional(),
              messages: z.array(ReportsMessageSchema).default([]).exactOptional(),
              result: ReportsAccountIndustrySingleResponseSchema,
              success: z.literal(true),
            })
            .openapi({ required: ['success', 'result'] }),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

