export const postAccountsAccountIdRequestTracerTraceRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/request-tracer/trace',
  tags: ['Account Request Tracer'],
  summary: 'Request Trace',
  description:
    "Traces a simulated HTTP request through Cloudflare's edge to analyze how rules, settings, and configurations would process the request. Useful for debugging firewall rules, page rules, and other request transformations without sending actual traffic. Supports custom headers, cookies, body content, and geolocation context.",
  operationId: 'account-request-tracer-request-trace',
  request: {
    params: z.object({
      account_id: RequestTracerAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/request-tracer_account_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              body: z
                .object({
                  base64: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'Base64 encoded request body',
                      example: 'c29tZV9yZXF1ZXN0X2JvZHk=',
                      'x-auditable': true,
                    }),
                  json: z
                    .object({})
                    .exactOptional()
                    .openapi({ description: 'Arbitrary json as request body' }),
                  plain_text: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'Request body as plain text', 'x-auditable': true }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              context: z
                .object({
                  bot_score: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description: 'Bot score used for evaluating tracing request processing',
                      'x-auditable': true,
                    }),
                  geoloc: z
                    .object({
                      city: z
                        .string()
                        .exactOptional()
                        .openapi({ example: 'London', 'x-auditable': true }),
                      continent: z.string().exactOptional().openapi({ 'x-auditable': true }),
                      is_eu_country: z.boolean().exactOptional().openapi({ 'x-auditable': true }),
                      iso_code: z.string().exactOptional().openapi({ 'x-auditable': true }),
                      latitude: z.number().exactOptional().openapi({ 'x-auditable': true }),
                      longitude: z.number().exactOptional().openapi({ 'x-auditable': true }),
                      postal_code: z.string().exactOptional().openapi({ 'x-auditable': true }),
                      region_code: z.string().exactOptional().openapi({ 'x-auditable': true }),
                      subdivision_2_iso_code: z
                        .string()
                        .exactOptional()
                        .openapi({ 'x-auditable': true }),
                      timezone: z.string().exactOptional().openapi({ 'x-auditable': true }),
                    })
                    .exactOptional()
                    .openapi({ description: 'Geodata for tracing request', required: [] }),
                  skip_challenge: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether to skip any challenges for tracing request (e.g.: captcha)',
                      example: true,
                      'x-auditable': true,
                    }),
                  threat_score: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description: 'Threat score used for evaluating tracing request processing',
                      'x-auditable': true,
                    }),
                })
                .exactOptional()
                .openapi({ description: 'Additional request parameters', required: [] }),
              cookies: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description: 'Cookies added to tracing request',
                  example: { cookie_name_1: 'cookie_value_1', cookie_name_2: 'cookie_value_2' },
                }),
              headers: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description: 'Headers added to tracing request',
                  example: { header_name_1: 'header_value_1', header_name_2: 'header_value_2' },
                }),
              method: z
                .string()
                .openapi({
                  description: 'HTTP Method of tracing request',
                  example: 'PUT',
                  'x-auditable': true,
                }),
              protocol: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'HTTP Protocol of tracing request',
                  example: 'HTTP/1.1',
                  'x-auditable': true,
                }),
              skip_response: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Skip sending the request to the Origin server after all rules evaluation',
                  'x-auditable': true,
                }),
              url: z
                .string()
                .openapi({
                  description: 'URL to which perform tracing request',
                  example: 'https://some.zone/some_path',
                  'x-auditable': true,
                }),
            })
            .openapi({ required: ['url', 'method'] }),
          example: {
            body: { base64: 'c29tZV9yZXF1ZXN0X2JvZHk=' },
            context: { geoloc: { city: 'London' }, skip_challenge: true },
            cookies: { cookie_name_1: 'cookie_value_1', cookie_name_2: 'cookie_value_2' },
            headers: { header_name_1: 'header_value_1', header_name_2: 'header_value_2' },
            method: 'PUT',
            protocol: 'HTTP/1.1',
            url: 'https://some.zone/some_path',
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Request Trace response',
      content: {
        'application/json': {
          schema: RequestTracerApiResponseCommonSchema.and(
            z
              .object({
                result: z
                  .object({
                    status_code: z
                      .int()
                      .exactOptional()
                      .openapi({
                        description: 'HTTP Status code of zone response',
                        'x-auditable': true,
                      }),
                    trace: RequestTracerTraceSchema.exactOptional(),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'Trace result with an origin status code',
                    required: [],
                  }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Request Trace response failure',
      content: { 'application/json': { schema: RequestTracerApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const getAccountsAccountIdResourceLibraryApplicationsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/resource-library/applications',
  tags: ['Applications'],
  summary: 'List applications',
  description:
    'List the applications available to an account, both the applications Cloudflare\ncurates and the custom applications the account has defined.\n\nResults are paginated. Page with `cursor` so that applications added or removed\nbetween requests do not make other results repeat or go missing; `offset` paging can\nrepeat or miss results when the list changes between requests. Use `filter` and\n`search` to narrow the list, `order_by` to sort it, and `fields` to reduce each result\nto only the properties you need.\nUse `lookup` to find complete application names mentioned in a rule sentence,\nignoring case. Lookup does not correct misspellings. It ranks matches by\nrelevance and uses the same filters, fields, and pagination as listing.\n`lookup` cannot be combined with `search`.\n\nInvalid UTF-8 or a NUL character (U+0000) in any query parameter name or value\nreturns `400`.\n\nThe authenticated principal must have access to the account identified by\n`account_id`.\n',
  operationId: 'getResourceLibraryApplications',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            description: 'Account ID.',
            required: true,
            schema: { type: 'string' },
            example: '023e105f4ecef8ad9ca31a8372d0c353',
          },
        }),
    }),
    query: z.object({
      filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter',
            in: 'query',
            description:
              'Filter applications using `key:value` format. Supported filter keys:\n- `name`: application name (for example, `name:HR`).\n- `id`: application ID (for example, `id:498`).\n- `human_id`: human-readable ID (for example, `human_id:HR`).\n- `hostname`: hostname or support domain (for example, `hostname:portal.example.com`).\n- `source`: application source name (for example, `source:cloudflare`).\n- `ip_subnet`: CIDR containment; returns applications where a stored subnet contains the search value (for example, `ip_subnet:10.0.1.5/32` matches `10.0.0.0/16`).\n- `category_id`: category ID (for example, `category_id:12`).\n- `category_name`: category name (for example, `category_name:HR`).\n- `supported`: supported Cloudflare product. Values: `GATEWAY`, `ACCESS`, `CASB`.\n- `review_status`: account-specific Gateway review status. Values: `approved`, `unapproved`, `in_review`, `unreviewed`.\n',
            schema: { type: 'string' },
            example: 'name:HR',
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description:
              'Number of results to return. Defaults to 25; values are clamped to 1–250.',
            schema: { type: 'integer', default: 25 },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description:
              'Number of results to skip. Defaults to 0; negative values are clamped to 0. Ignored when `cursor` is provided.',
            schema: { type: 'integer', default: 0 },
            required: false,
          },
        }),
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            description:
              'Opaque value from `result_info.cursor` of the previous response. Returns the\nresults that follow it. Send the same `filter`, `search`, `lookup`, and\n`order_by` values as the request that returned it; `limit` and `fields` may\nchange. An empty value is the same as no cursor. A modified cursor, or one used\nwith different values, returns `400`.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      order_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description:
              'Order results using field:direction format. Supported fields are name, id, human_id,\ncategory_id, application_type, application_confidence_score, and gen_ai_score.\nSupported directions are asc and desc. Ignored when search is provided; results are\nranked by relevance instead. Also ignored when lookup is provided.\n',
            schema: { type: 'string' },
            example: 'name:asc',
            required: false,
          },
        }),
      search: z
        .string()
        .min(2)
        .max(200)
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description:
              'Fuzzy search across application name and hostnames. Results are ranked by relevance. Must be between 2 and 200 characters. Can be combined with filter parameters.',
            schema: { type: 'string', maxLength: 200, minLength: 2 },
            example: 'MyNewApp',
            required: false,
          },
        }),
      lookup: z
        .string()
        .min(2)
        .max(1000)
        .exactOptional()
        .openapi({
          param: {
            name: 'lookup',
            in: 'query',
            description:
              'Find complete, case-insensitive application name mentions in a phrase or\nrule sentence. Misspelled names do not match. Returns matching applications\nranked by relevance. Must be between 2 and 1000 characters, with no control\ncharacters other than tab and line breaks. Uses the same\nfilters, fields, and pagination as listing. `search` cannot be combined\nwith lookup. Results are ranked by relevance, so `order_by` is ignored.\nTo keep the text out of URLs, send it to `POST .../applications/lookup` instead.\n',
            schema: { type: 'string', maxLength: 1000, minLength: 2 },
            example: 'block access to Google Chat',
            required: false,
          },
        }),
      fields: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'Return only the listed properties on each application, as a comma-separated list.\nUse this to keep responses small when you only need part of each application, for\nexample populating a picker with `fields=id,name` instead of downloading every\nhostname and IP subnet.\n\nOmit this parameter to receive the full application object, including\nwhen lookup is used.\n\n`id` is always returned.\n\nSelectable properties: `id`, `name`, `human_id`, `version`, `hostnames`,\n`support_domains`, `ip_subnets`, `port_protocols`, `supported`, `gen_ai_score`,\n`application_confidence_score`, `created_at`, `updated_at`, `review_status`.\n\nUnknown or empty property names return `400`.\n',
            schema: { type: 'string' },
            example: 'id,name',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get the application response.',
      content: { 'application/json': { schema: AlexandriaGetApplicationsResponseSchema } },
    },
    403: {
      description: 'The authenticated principal does not have access to the requested account.',
      content: { 'application/json': { schema: AlexandriaApiResponseCommonFailureSchema } },
    },
    502: {
      description: 'Application review statuses could not be retrieved.',
      content: { 'application/json': { schema: AlexandriaApiResponseCommonFailureSchema } },
    },
    503: {
      description:
        'Application review statuses were requested but are not available, or a cursor was sent while cursor pagination is not available.',
      content: { 'application/json': { schema: AlexandriaApiResponseCommonFailureSchema } },
    },
    '4XX': {
      description: 'Get application response failure.',
      content: { 'application/json': { schema: AlexandriaApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

