export const getAccountsAccountIdRulesetsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/rulesets',
  tags: ['Account Rulesets'],
  summary: 'List account rulesets',
  description: 'Fetches all rulesets at the account level.',
  operationId: 'listAccountRulesets',
  request: {
    params: z.object({
      account_id: RulesetsAccountIdSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/rulesets_AccountId' },
        },
      }),
    }),
    query: z.object({
      cursor: RulesetsCursorSchema.openapi({
        param: {
          name: 'cursor',
          in: 'query',
          schema: { $ref: '#/components/schemas/rulesets_Cursor' },
          required: false,
        },
      }).exactOptional(),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          RulesetsPerPageSchema.openapi({
            param: {
              name: 'per_page',
              in: 'query',
              schema: { $ref: '#/components/schemas/rulesets_PerPage' },
              required: false,
            },
          }),
        )
        .exactOptional(),
    }),
  },
  responses: { 200: RulesetsRulesetsResponse, '4XX': RulesetsFailureResponse },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { api_email: [], api_key: [] }],
})

