export const getAccountsAccountIdRumSiteInfoValidateHostnameRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/rum/site_info/validate/{hostname}',
  tags: ['Web Analytics'],
  summary: 'Validate a Web Analytics site hostname',
  description:
    'Validates that the provided hostname is well-formed, does not contain wildcards, and has a valid TLD. Returns an empty result on success.\n',
  operationId: 'web-analytics-validate-site-hostname',
  request: {
    params: z.object({
      account_id: RumIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/rum_identifier' },
        },
      }),
      hostname: z
        .string()
        .regex(
          /^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\-]*[a-zA-Z0-9]?)\.){1,}([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\-]*[A-Za-z0-9]?){2,}$/,
        )
        .max(253)
        .openapi({
          param: {
            name: 'hostname',
            in: 'path',
            description:
              "The hostname to validate (e.g. example.com). The `pattern` below validates the hostname's structure (label syntax) only. In addition, the hostname must end in a valid public suffix (TLD). For the list of valid suffixes and how it is used, see the Public Suffix List: https://wiki.mozilla.org/Public_Suffix_List/Use_Cases\n",
            required: true,
            schema: {
              type: 'string',
              example: 'example.com',
              maxLength: 253,
              pattern:
                '^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9]?)\\.){1,}([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9]?){2,}$',
            },
          },
          example: 'example.com',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Hostname is valid.',
      content: { 'application/json': { schema: RumEmptyResponseSchema } },
    },
    '4XX': {
      description: 'Failure response.',
      content: { 'application/json': { schema: RumApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

