export const getAccountsAccountIdScimV2UsersRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/scim/v2/Users',
  tags: ['SCIM Users'],
  summary: 'List SCIM Users',
  description:
    'Lists account members as SCIM User resources. Supports optional filtering by `userName` (email) using the SCIM filter syntax (e.g. `userName eq "user@example.com"`). Pagination is controlled via `startIndex` and `count` query parameters per RFC 7644 Section 3.4.2.4.\n',
  operationId: 'scim-users-list',
  request: {
    params: z.object({
      account_id: IamAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/iam_account_identifier' },
        },
      }),
    }),
    query: z.object({
      startIndex: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'startIndex',
            in: 'query',
            schema: {
              description:
                'The 1-based index of the first result in the current set of list results. Values less than 1 are treated as 1.\n',
              type: 'integer',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description:
            'The 1-based index of the first result in the current set of list results. Values less than 1 are treated as 1.\n',
        }),
      count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'count',
            in: 'query',
            schema: {
              description: 'Specifies the desired maximum number of query results per page.\n',
              type: 'integer',
              minimum: 0,
            },
            required: false,
          },
          description: 'Specifies the desired maximum number of query results per page.\n',
        }),
      filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter',
            in: 'query',
            schema: {
              description:
                'SCIM filter expression (RFC 7644 Section 3.4.2.2). Only `userName eq "value"` is supported.\n',
              type: 'string',
              example: 'userName eq "user@example.com"',
            },
            required: false,
          },
          description:
            'SCIM filter expression (RFC 7644 Section 3.4.2.2). Only `userName eq "value"` is supported.\n',
          example: 'userName eq "user@example.com"',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List SCIM Users response',
      content: { 'application/scim+json': { schema: IamScimUserListResponseSchema } },
    },
    '4XX': {
      description: 'List SCIM Users response failure',
      content: { 'application/scim+json': { schema: IamScimErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

