export const patchAccountsAccountIdScimV2UsersUserIdRoute = createRoute({
  method: 'patch',
  path: '/accounts/{account_id}/scim/v2/Users/{user_id}',
  tags: ['SCIM Users'],
  summary: 'Patch SCIM User',
  description:
    'Partially updates a SCIM User via PATCH operations (RFC 7644 Section 3.5.2). Supports updating `userName`, `name.givenName`, `name.familyName`, and `active`. Setting `active: false` deprovisions the user (removes them from the account). For IdP compatibility, `emails[type eq "work"].value` is also accepted as an alias for `userName`.\n',
  operationId: 'scim-users-patch',
  request: {
    params: z.object({
      account_id: IamAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/iam_account_identifier' },
        },
      }),
      user_id: IamScimUserIdentifierSchema.openapi({
        param: {
          name: 'user_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/iam_scim_user_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/scim+json': {
          schema: IamScimPatchOpRequestSchema,
          examples: {
            'path-based': {
              summary: 'Path-based style',
              value: {
                Operations: [{ op: 'replace', path: 'active', value: false }],
                schemas: ['urn:ietf:params:scim:api:messages:2.0:PatchOp'],
              },
            },
            'value-object': {
              summary: 'Value-object style (no path)',
              value: {
                Operations: [{ op: 'replace', value: { active: false } }],
                schemas: ['urn:ietf:params:scim:api:messages:2.0:PatchOp'],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Patch SCIM User response',
      content: { 'application/scim+json': { schema: IamScimUserSchema } },
    },
    '4XX': {
      description: 'Patch SCIM User response failure',
      content: { 'application/scim+json': { schema: IamScimErrorResponseSchema } },
    },
  },
  security: [{ api_token: [] }],
})

