export const getAccountsAccountIdSecurityCenterInsightsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/security-center/insights',
  tags: ['Security Center Insights'],
  summary: 'Retrieves Security Center Insights',
  description:
    'Lists all Security Center insights for the account, showing security findings and recommendations.',
  operationId: 'get-security-center-insights',
  request: {
    params: z.object({
      account_id: SecurityCenterIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/security-center_identifier' },
        },
      }),
    }),
    query: z.object({
      dismissed: z
        .preprocess(
          ((read) => (val: unknown) => {
            const result = read.safeParse(val)
            return result.success ? result.data : val
          })(z.stringbool()),
          SecurityCenterDismissedSchema.openapi({
            param: {
              name: 'dismissed',
              in: 'query',
              schema: { $ref: '#/components/schemas/security-center_dismissed' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      issue_class: SecurityCenterIssueClassesSchema.openapi({
        param: {
          name: 'issue_class',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_issueClasses' },
          required: false,
        },
      }).exactOptional(),
      issue_type: SecurityCenterIssueTypesSchema.openapi({
        param: {
          name: 'issue_type',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_issueTypes' },
          required: false,
        },
      }).exactOptional(),
      product: SecurityCenterProductsSchema.openapi({
        param: {
          name: 'product',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_products' },
          required: false,
        },
      }).exactOptional(),
      source: SecurityCenterSourcesSchema.openapi({
        param: {
          name: 'source',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_sources' },
          required: false,
        },
      }).exactOptional(),
      severity: SecurityCenterSeverityQueryParamSchema.openapi({
        param: {
          name: 'severity',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_severityQueryParam' },
          required: false,
        },
      }).exactOptional(),
      subject: SecurityCenterSubjectsSchema.openapi({
        param: {
          name: 'subject',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_subjects' },
          required: false,
        },
      }).exactOptional(),
      'issue_class~neq': SecurityCenterIssueClassesSchema.openapi({
        param: {
          name: 'issue_class~neq',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_issueClasses' },
          required: false,
        },
      }).exactOptional(),
      'issue_type~neq': SecurityCenterIssueTypesSchema.openapi({
        param: {
          name: 'issue_type~neq',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_issueTypes' },
          required: false,
        },
      }).exactOptional(),
      'product~neq': SecurityCenterProductsSchema.openapi({
        param: {
          name: 'product~neq',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_products' },
          required: false,
        },
      }).exactOptional(),
      'severity~neq': SecurityCenterSeverityQueryParamSchema.openapi({
        param: {
          name: 'severity~neq',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_severityQueryParam' },
          required: false,
        },
      }).exactOptional(),
      'subject~neq': SecurityCenterSubjectsSchema.openapi({
        param: {
          name: 'subject~neq',
          in: 'query',
          schema: { $ref: '#/components/schemas/security-center_subjects' },
          required: false,
        },
      }).exactOptional(),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          SecurityCenterPageSchema,
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: { default: 1, allOf: [{ $ref: '#/components/schemas/security-center_page' }] },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          SecurityCenterPerPageSchema,
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              default: 25,
              allOf: [{ $ref: '#/components/schemas/security-center_perPage' }],
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The request was successful.',
      content: {
        'application/json': {
          schema: SecurityCenterApiResponseCommonSchema.and(
            z
              .object({
                result: z
                  .object({
                    count: SecurityCenterCountSchema.exactOptional(),
                    issues: z.array(SecurityCenterIssueSchema).exactOptional(),
                    page: SecurityCenterPageSchema.exactOptional(),
                    per_page: SecurityCenterPerPageSchema.exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'A client error occurred.',
      content: { 'application/json': { schema: SecurityCenterApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }, { api_token: [] }],
})

