export const getAccountsAccountIdSlurperJobsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/slurper/jobs',
  tags: ['R2 Super Slurper'],
  summary: 'List jobs',
  description: 'Lists all R2 Super Slurper migration jobs for the account with their status.',
  operationId: 'slurper-list-jobs',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(50),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: { type: 'integer', maximum: 50 },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { name: 'offset', in: 'query', schema: { type: 'integer' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A list of jobs',
      content: {
        'application/json': {
          schema: R2SlurperApiV4SuccessSchema.and(
            z
              .object({ result: z.array(R2SlurperJobResponseSchema).exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'Failure response',
      content: { 'application/json': { schema: R2SlurperApiV4FailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

