export const getAccountsAccountIdStorageKvNamespacesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/storage/kv/namespaces',
  tags: ['Workers KV Namespace'],
  summary: 'List namespaces',
  description:
    'Lists Workers KV namespaces owned by the specified account. Use `page` and `per_page` to select a page of results, and `order` and `direction` to control sorting.',
  operationId: 'workers-kv-namespace-list-namespaces',
  request: {
    params: z.object({
      account_id: WorkersKvIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/workers-kv_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(1000),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Maximum number of results per page.',
              type: 'number',
              default: 20,
              maximum: 1000,
              minimum: 1,
            },
            required: false,
          },
          description: 'Maximum number of results per page.',
        }),
      order: z
        .enum(['id', 'title'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              description: 'Namespace field to sort by (`id` or `title`).',
              type: 'string',
              example: 'id',
              enum: ['id', 'title'],
            },
            required: false,
          },
          description: 'Namespace field to sort by (`id` or `title`).',
          example: 'id',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Sort namespaces in ascending (`asc`) or descending (`desc`) order.',
              type: 'string',
              example: 'asc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Sort namespaces in ascending (`asc`) or descending (`desc`) order.',
          example: 'asc',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Namespaces response.',
      content: {
        'application/json': {
          schema: WorkersKvApiResponseCollectionSchema.and(
            z
              .object({ result: z.array(WorkersKvNamespaceSchema).exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'List Namespaces response failure.',
      content: { 'application/json': { schema: WorkersKvApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

