export const postAccountsAccountIdStreamWatermarksRoute = createRoute({
  method: 'post',
  path: '/accounts/{account_id}/stream/watermarks',
  tags: ['Stream Watermark Profile'],
  summary: 'Create watermark profiles via basic upload',
  description: 'Creates watermark profiles using a single `HTTP POST multipart/form-data` request.',
  operationId: 'stream-watermark-profile-create-watermark-profiles-via-basic-upload',
  request: {
    params: z.object({
      account_id: StreamAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/stream_account_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: StreamNameSchema.exactOptional(),
              opacity: StreamOpacitySchema.exactOptional(),
              padding: StreamPaddingSchema.exactOptional(),
              position: StreamPositionSchema.exactOptional(),
              scale: StreamScaleSchema.exactOptional(),
              url: z
                .url()
                .exactOptional()
                .openapi({ description: 'URL of the watermark image to copy.' }),
            })
            .openapi({ required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              file: z
                .string()
                .openapi({
                  description: 'The image file to upload.',
                  example: '@/Users/rchen/Downloads/watermark.png',
                  'x-auditable': true,
                }),
              name: StreamNameSchema.exactOptional(),
              opacity: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  StreamOpacitySchema,
                )
                .exactOptional(),
              padding: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  StreamPaddingSchema,
                )
                .exactOptional(),
              position: StreamPositionSchema.exactOptional(),
              scale: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  StreamScaleSchema,
                )
                .exactOptional(),
            })
            .openapi({ required: ['file'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Create watermark profiles via basic upload response.',
      content: { 'application/json': { schema: StreamWatermarkResponseSingleSchema } },
    },
    '4XX': {
      description: 'Create watermark profiles via basic upload response failure.',
      content: { 'application/json': { schema: StreamApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

