export const getAccountsAccountIdTagsResourcesRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/tags/resources',
  tags: ['Resource Tagging'],
  summary: 'List tagged resources',
  description: 'Lists all tagged resources for an account.',
  operationId: 'tags-list',
  request: {
    query: z.object({
      include_navigation: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_navigation',
            in: 'query',
            description:
              'Resolve current namespace Worker navigation by immutable child tag. Optional read-only navigation is omitted for deleted or unresolved children. Lookups are limited to this page, at most five concurrently, with a shared two-second budget. Tag identity, ETag, filters and pagination are unchanged; name filtering still uses the stored resource name. Defaults to false.',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      type: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(ResourceTaggingResourceTypeSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            description:
              'Filter by resource type. Can be repeated to filter by multiple types (OR logic). Example: ?type=zone&type=worker',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/resource-tagging_resource_type' },
            },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      name: z
        .string()
        .max(256)
        .exactOptional()
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            description:
              'Filter by resource name. Performs a case-insensitive substring match. Example: ?name=my-zone',
            schema: { type: 'string', maxLength: 256 },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(ResourceTaggingResourceIdSchema).max(50),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'id',
            in: 'query',
            description:
              'Filter by resource ID. Can be repeated up to 50 times to filter by multiple IDs. Example: ?id=abc&id=def',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/resource-tagging_resource_id' },
              maxItems: 50,
            },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
      case_insensitive: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'case_insensitive',
            in: 'query',
            description:
              'Match `tag` keys and values case-insensitively. Stored casing is unchanged. Example: ?tag=environment=production&case_insensitive=true',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      tag: ResourceTaggingTagParamsSchema,
      cursor: ResourceTaggingCursorParamsSchema,
    }),
    params: z.object({
      account_id: ResourceTaggingAccountIdSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/resource-tagging_account_id' },
        },
      }),
    }),
  },
  responses: {
    200: {
      description: 'List tagged resources response.',
      content: {
        'application/json': { schema: ResourceTaggingTaggedResourceResponseCollectionSchema },
      },
    },
    '4XX': {
      description: 'List tagged resources response failure.',
      content: { 'application/json': { schema: ResourceTaggingApiResponseCommonFailureSchema } },
    },
    '5XX': {
      description: 'List tagged resources response failure.',
      content: { 'application/json': { schema: ResourceTaggingApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

