export const getAccountsAccountIdTokensRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/tokens',
  tags: ['Account Owned API Tokens'],
  summary: 'List Tokens',
  description:
    'List Account Owned API tokens created for this account. Callers with\n`com.cloudflare.api.account.token.list_self` permission only receive\ntokens they created. Results include active, disabled, and\nrecently-expired tokens when `include_expired` is set to true.',
  operationId: 'account-api-tokens-list-tokens',
  request: {
    params: z.object({
      account_id: IamAccountIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/iam_account_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Maximum number of results per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Maximum number of results per page.',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Direction to order results.',
              type: 'string',
              example: 'desc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Direction to order results.',
          example: 'desc',
        }),
      include_expired: IamIncludeExpiredParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'List Tokens response',
      content: { 'application/json': { schema: IamCollectionTokensResponseSchema } },
    },
    '4XX': {
      description: 'List Tokens response failure',
      content: { 'application/json': { schema: IamApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }],
})

