export const getAccountsAccountIdTriggersScriptNameRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/triggers/{script_name}',
  tags: ['Workflows'],
  summary: 'Get script triggers',
  description: 'Returns the event trigger declarations owned by a Worker script.',
  operationId: 'wor-get-script-triggers',
  request: {
    params: z.object({
      script_name: z
        .string()
        .min(1)
        .max(255)
        .openapi({
          param: {
            name: 'script_name',
            in: 'path',
            required: true,
            schema: { type: 'string', maxLength: 255, minLength: 1 },
          },
        }),
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Script trigger declarations.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({ code: z.number(), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                )
                .max(0),
              messages: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              result: z
                .object({
                  script_name: z.string(),
                  triggers: z
                    .array(
                      z
                        .object({
                          filter: z
                            .record(
                              z.string(),
                              z.union([z.string().max(1024), z.number(), z.boolean()]),
                            )
                            .default({})
                            .exactOptional(),
                          targets: z
                            .array(
                              z
                                .object({
                                  script_name: z.string().min(1).max(255),
                                  type: z.literal('workflow'),
                                  workflow_name: z.string().min(1).max(255),
                                })
                                .openapi({ required: ['type', 'script_name', 'workflow_name'] }),
                            )
                            .min(1)
                            .max(100),
                          type: z.string().min(1),
                        })
                        .openapi({ required: ['type', 'targets'] }),
                    )
                    .max(100),
                })
                .openapi({ required: ['script_name', 'triggers'] }),
              result_info: z
                .object({
                  count: z.number(),
                  cursor: z.string().exactOptional(),
                  page: z.number().exactOptional(),
                  per_page: z.number(),
                  total_count: z.number(),
                  total_pages: z.number().exactOptional(),
                })
                .exactOptional()
                .openapi({ required: ['per_page', 'count', 'total_count'] }),
              success: z.literal(true),
            })
            .openapi({ required: ['success', 'errors', 'result', 'messages'] }),
        },
      },
    },
    400: {
      description: 'Invalid trigger configuration.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
    404: {
      description: 'Target workflow not found.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

