export const getAccountsAccountIdUrlscannerV2SearchRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/urlscanner/v2/search',
  tags: ['URL Scanner'],
  summary: 'Search URL scans',
  description:
    "Use a subset of ElasticSearch Query syntax to filter scans. Some example queries:<br/> <br/>- 'path:\"/bundles/jquery.js\"': Searches for scans who requested resources with the given path.<br/>- 'page.asn:AS24940 AND hash:xxx': Websites hosted in AS24940 where a resource with the given hash was downloaded.<br/>- 'page.domain:microsoft* AND verdicts.malicious:true AND NOT page.domain:microsoft.com': malicious scans whose hostname starts with \"microsoft\".<br/>- 'apikey:me AND date:[2025-01 TO 2025-02]': my scans from 2025 January to 2025 February.",
  operationId: 'urlscanner-search-scans-v2',
  request: {
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: {
            name: 'account_id',
            in: 'path',
            description: 'Account ID.',
            required: true,
            schema: { description: 'Account ID.', type: 'string' },
          },
          description: 'Account ID.',
        }),
    }),
    query: z.object({
      size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'size',
            in: 'query',
            description: 'Limit the number of objects in the response.',
            schema: {
              description: 'Limit the number of objects in the response.',
              type: 'integer',
              example: 100,
            },
            required: false,
          },
          description: 'Limit the number of objects in the response.',
          example: 100,
        }),
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'q',
            in: 'query',
            description: 'Filter scans',
            schema: { description: 'Filter scans', type: 'string' },
            'x-fern-parameter-name': 'query',
            required: false,
          },
          description: 'Filter scans',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Search results',
      content: {
        'application/json': {
          schema: z
            .object({
              results: z.array(
                z
                  .object({
                    _id: z.string().openapi({ example: '9626f773-9ffb-4cfb-89d3-30b120fc8011' }),
                    page: z
                      .object({
                        asn: z.string().openapi({ example: 'AS15133' }),
                        country: z.string().openapi({ example: 'US' }),
                        ip: z.string().openapi({ example: '93.184.215.14' }),
                        url: z.string().openapi({ example: 'https://example.com' }),
                      })
                      .openapi({ required: ['country', 'ip', 'url', 'asn'] }),
                    result: z
                      .string()
                      .openapi({
                        example:
                          'https://radar.clouflare.com/scan/9626f773-9ffb-4cfb-89d3-30b120fc8011',
                      }),
                    stats: z
                      .object({
                        dataLength: z.number().openapi({ example: 2512 }),
                        requests: z.number().openapi({ example: 2 }),
                        uniqCountries: z.number().openapi({ example: 1 }),
                        uniqIPs: z.number().openapi({ example: 1 }),
                      })
                      .openapi({
                        required: ['uniqIPs', 'uniqCountries', 'dataLength', 'requests'],
                      }),
                    task: z
                      .object({
                        time: z.string().openapi({ example: '2024-09-30T23:54:02.881Z' }),
                        url: z.string().openapi({ example: 'https://example.com' }),
                        uuid: z
                          .string()
                          .openapi({ example: '9626f773-9ffb-4cfb-89d3-30b120fc8011' }),
                        visibility: z.string().openapi({ example: 'public' }),
                      })
                      .openapi({ required: ['visibility', 'time', 'uuid', 'url'] }),
                    verdicts: z
                      .object({ malicious: z.boolean() })
                      .openapi({ required: ['malicious'] }),
                  })
                  .openapi({ required: ['task', 'stats', 'page', 'verdicts', '_id', 'result'] }),
              ),
            })
            .openapi({ required: ['results'] }),
        },
      },
    },
    400: {
      description: 'Invalid input.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({
                    detail: z.string(),
                    status: z.int().openapi({ description: 'Status code.', example: 400 }),
                    title: z.string().openapi({ example: 'Invalid url' }),
                  })
                  .openapi({ required: ['title', 'detail', 'status'] }),
              ),
              message: z.string(),
              status: z.int().openapi({ description: 'Status code.', example: 400 }),
            })
            .openapi({ required: ['message', 'status', 'errors'] }),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

