export const getAccountsAccountIdWarpConnectorRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/warp_connector',
  tags: ['Cloudflare Tunnel'],
  summary: 'List Mesh nodes',
  description: 'Lists and filters Mesh nodes in an account.',
  operationId: 'cloudflare-tunnel-list-warp-connector-tunnels',
  request: {
    params: z.object({
      account_id: TunnelAccountIdSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/tunnel_account_id' },
        },
      }),
    }),
    query: z.object({
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            schema: {
              description: 'A user-friendly name for the tunnel.',
              type: 'string',
              example: 'blog',
            },
            required: false,
          },
          description: 'A user-friendly name for the tunnel.',
          example: 'blog',
        }),
      is_deleted: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'is_deleted',
            in: 'query',
            schema: {
              description:
                'If `true`, only include deleted tunnels. If `false`, exclude deleted tunnels. If empty, all tunnels will be included.',
              type: 'boolean',
              example: true,
            },
            required: false,
          },
          description:
            'If `true`, only include deleted tunnels. If `false`, exclude deleted tunnels. If empty, all tunnels will be included.',
          example: true,
        }),
      existed_at: TunnelExistedAtSchema.openapi({
        param: {
          name: 'existed_at',
          in: 'query',
          schema: { $ref: '#/components/schemas/tunnel_existed_at' },
          required: false,
        },
      }).exactOptional(),
      uuid: TunnelTunnelIdSchema.openapi({
        param: {
          name: 'uuid',
          in: 'query',
          schema: { $ref: '#/components/schemas/tunnel_tunnel_id' },
          required: false,
        },
      }).exactOptional(),
      was_active_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'was_active_at',
            in: 'query',
            schema: { type: 'string', format: 'date-time', example: '2009-11-10T23:00:00Z' },
            required: false,
          },
          example: '2009-11-10T23:00:00Z',
        }),
      was_inactive_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'was_inactive_at',
            in: 'query',
            schema: { type: 'string', format: 'date-time', example: '2009-11-10T23:00:00Z' },
            required: false,
          },
          example: '2009-11-10T23:00:00Z',
        }),
      include_prefix: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_prefix',
            in: 'query',
            schema: { type: 'string', example: 'vpc1-' },
            required: false,
          },
          example: 'vpc1-',
        }),
      exclude_prefix: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'exclude_prefix',
            in: 'query',
            schema: { type: 'string', example: 'vpc1-' },
            required: false,
          },
          example: 'vpc1-',
        }),
      status: TunnelStatusSchema.openapi({
        param: {
          name: 'status',
          in: 'query',
          schema: { $ref: '#/components/schemas/tunnel_status' },
          required: false,
        },
      }).exactOptional(),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          TunnelPerPageSchema.openapi({
            param: {
              name: 'per_page',
              in: 'query',
              schema: { $ref: '#/components/schemas/tunnel_per_page' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          TunnelPageNumberSchema.openapi({
            param: {
              name: 'page',
              in: 'query',
              schema: { $ref: '#/components/schemas/tunnel_page_number' },
              required: false,
            },
          }),
        )
        .exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'List Mesh nodes response',
      content: { 'application/json': { schema: TunnelWarpConnectorResponseCollectionSchema } },
    },
    '4XX': {
      description: 'List Mesh nodes response failure',
      content: {
        'application/json': {
          schema: TunnelWarpConnectorResponseCollectionSchema.and(
            TunnelApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [] }, { api_token: [] }, { user_service_key: [] }],
})

