export const getAccountsAccountIdWorkersWorkersRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/workers/workers',
  tags: ['Workers'],
  summary: 'List Workers',
  description: 'List all Workers for an account.',
  operationId: 'listWorkers',
  request: {
    params: z.object({
      account_id: WorkersIdentifierSchema.openapi({
        param: {
          name: 'account_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/workers_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Current page.',
            schema: { type: 'integer', default: 1, minimum: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Items per-page.',
            schema: { type: 'integer', default: 10, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
      order_by: z
        .enum(['deployed_on', 'updated_on', 'created_on', 'name'])
        .default('deployed_on')
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description: 'Property to sort results by.',
            schema: {
              type: 'string',
              default: 'deployed_on',
              enum: ['deployed_on', 'updated_on', 'created_on', 'name'],
            },
            required: false,
          },
        }),
      order: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            description: 'Sort direction.',
            schema: { type: 'string', default: 'desc', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Workers success.',
      content: {
        'application/json': {
          schema: WorkersApiResponseCollectionSchema.and(
            z.object({ result: z.array(WorkersWorkerSchema) }).openapi({ required: ['result'] }),
          ),
        },
      },
    },
    401: WorkersErrorAuthResponse,
    500: WorkersErrorInternalServerResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

