export const getAccountsAccountIdWorkflowsRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/workflows',
  tags: ['Workflows'],
  summary: 'List all Workflows',
  description: 'Lists all workflows configured for the account.',
  operationId: 'wor-list-workflows',
  request: {
    query: z.object({
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: { type: 'number', default: 10, maximum: 100, minimum: 1 },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: { type: 'number', default: 1, minimum: 1 },
            required: false,
          },
        }),
      search: z
        .string()
        .regex(/^[a-zA-Z0-9_][a-zA-Z0-9-_]*$/)
        .min(1)
        .max(64)
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description: 'Allows filtering workflows` name.',
            schema: {
              type: 'string',
              maxLength: 64,
              minLength: 1,
              pattern: '^[a-zA-Z0-9_][a-zA-Z0-9-_]*$',
            },
            required: false,
          },
        }),
    }),
    params: z.object({
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of all Workflows belonging to a account.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({ code: z.number(), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                )
                .max(0),
              messages: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              result: z.array(
                z
                  .object({
                    class_name: z.string(),
                    created_on: z.iso.datetime({ offset: true }),
                    id: z.uuid(),
                    instances: z.record(z.string(), z.number()),
                    modified_on: z.iso.datetime({ offset: true }),
                    name: z
                      .string()
                      .regex(/^[a-zA-Z0-9_][a-zA-Z0-9-_]*$/)
                      .min(1)
                      .max(64),
                    schedules: z
                      .array(
                        z
                          .object({ cron: z.string(), next_instance: z.string() })
                          .openapi({ required: ['cron', 'next_instance'] }),
                      )
                      .exactOptional(),
                    script_deleted: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description:
                          'Whether the bound Worker was deleted, leaving this Workflow inactive.',
                      }),
                    script_name: z.string(),
                    triggered_on: z.iso.datetime({ offset: true }).nullable(),
                  })
                  .openapi({
                    required: [
                      'name',
                      'id',
                      'created_on',
                      'modified_on',
                      'script_name',
                      'class_name',
                      'triggered_on',
                      'instances',
                    ],
                  }),
              ),
              result_info: z
                .object({
                  count: z.number(),
                  cursor: z.string().exactOptional(),
                  page: z.number().exactOptional(),
                  per_page: z.number(),
                  total_count: z.number(),
                  total_pages: z.number().exactOptional(),
                })
                .exactOptional()
                .openapi({ required: ['per_page', 'count', 'total_count'] }),
              success: z.literal(true),
            })
            .openapi({ required: ['success', 'errors', 'result', 'messages'] }),
        },
      },
    },
    400: {
      description: 'Input Validation Error.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

