export const getAccountsAccountIdWorkflowsWorkflowNameInstancesInstanceIdStepRoute = createRoute({
  method: 'get',
  path: '/accounts/{account_id}/workflows/{workflow_name}/instances/{instance_id}/step',
  tags: ['Workflows'],
  summary: 'Get full step output from instance',
  description:
    "Retrieves the full, untruncated output for a specific step on a workflow instance. Returns a flat status-shaped JSON body with step `status` ('running' | 'waiting' | 'complete' | 'errored'), `error` (nullable), and `output` (the step value, or null while running/waiting/errored). When the step returned a ReadableStream from step.do, the response is served as 'application/octet-stream' with the raw bytes as the body instead of JSON. A `status='running'` response with non-null `error` indicates the step is currently retrying after a prior attempt failed.",
  operationId: 'wor-get-workflow-instance-step',
  request: {
    params: z.object({
      workflow_name: z
        .string()
        .regex(/^[a-zA-Z0-9_][a-zA-Z0-9-_]*$/)
        .min(1)
        .max(64)
        .openapi({
          param: {
            name: 'workflow_name',
            in: 'path',
            required: true,
            schema: {
              type: 'string',
              maxLength: 64,
              minLength: 1,
              pattern: '^[a-zA-Z0-9_][a-zA-Z0-9-_]*$',
            },
          },
        }),
      instance_id: z
        .string()
        .min(1)
        .max(271)
        .openapi({
          param: {
            name: 'instance_id',
            in: 'path',
            description:
              'Instance identifier. User-created instances match `^[a-zA-Z0-9_][a-zA-Z0-9-_]*$` (max 100 characters); cron-triggered instances can use a longer, system-generated id derived from the cron expression.',
            required: true,
            schema: { type: 'string', maxLength: 271, minLength: 1 },
          },
        }),
      account_id: z
        .string()
        .openapi({
          param: { name: 'account_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      name: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            description:
              'Exact step name from the instance logs response, including the generated counter suffix.',
            required: true,
            schema: { type: 'string', minLength: 1 },
          },
        }),
      type: z
        .enum(['step', 'waitForEvent'])
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            description:
              'Step type to disambiguate step.do and waitForEvent entries that share the same name.',
            required: true,
            schema: { type: 'string', enum: ['step', 'waitForEvent'] },
          },
        }),
      attempt: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().positive().max(9007199254740991),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'attempt',
            in: 'query',
            description: 'Specific attempt number to retrieve output or error for.',
            schema: {
              type: 'integer',
              exclusiveMinimum: true,
              maximum: 9007199254740991,
              minimum: 0,
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get the full output from a specific instance step.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({ code: z.number(), message: z.string() })
                    .openapi({ required: ['code', 'message'] }),
                )
                .max(0),
              messages: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              result: z
                .object({
                  error: z
                    .object({ message: z.string(), name: z.string() })
                    .nullable()
                    .openapi({
                      description: "Error details when status='errored'; null otherwise.",
                      required: ['name', 'message'],
                    }),
                  event_type: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        "The event type the step is waiting on, as supplied to step.waitForEvent. Only present when type='waitForEvent'.",
                    }),
                  output: z
                    .object({})
                    .exactOptional()
                    .openapi({
                      description:
                        "Contains the full step output or waitForEvent payload without truncation. Uses '[REDACTED]' for sensitive outputs. Contains a value when status='complete'. May contain a ReadableStream when step.do returns one; the response serves stream outputs as application/octet-stream rather than JSON.",
                    }),
                  status: z.enum([
                    'queued',
                    'running',
                    'paused',
                    'errored',
                    'terminated',
                    'complete',
                    'waitingForPause',
                    'waiting',
                    'rollingBack',
                  ]),
                })
                .openapi({ required: ['status', 'error'] }),
              result_info: z
                .object({
                  count: z.number(),
                  cursor: z.string().exactOptional(),
                  page: z.number().exactOptional(),
                  per_page: z.number(),
                  total_count: z.number(),
                  total_pages: z.number().exactOptional(),
                })
                .exactOptional()
                .openapi({ required: ['per_page', 'count', 'total_count'] }),
              success: z.literal(true),
            })
            .openapi({ required: ['success', 'errors', 'result', 'messages'] }),
        },
        'application/octet-stream': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description: 'Raw bytes of the ReadableStream returned from step.do.',
            }),
        },
      },
    },
    400: {
      description: "Bad Request (e.g. 'attempt' parameter supplied with type='waitForEvent').",
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
    404: {
      description: 'Step not found on this instance, or requested attempt is out of range.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
    429: {
      description: 'Step output requests are rate limited.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
    500: {
      description:
        'Step completed but its stored output is corrupt or missing (server-side data-integrity failure).',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(
                z
                  .object({ code: z.number(), message: z.string() })
                  .openapi({ required: ['code', 'message'] }),
              ),
              messages: z.array(z.string()),
              result: z.literal(null).nullable(),
              success: z.literal(false),
            })
            .openapi({ required: ['success', 'messages', 'errors', 'result'] }),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

