export const getMembershipsRoute = createRoute({
  method: 'get',
  path: '/memberships',
  tags: ["User's Account Memberships"],
  summary: 'List Memberships',
  description: 'List memberships of accounts the user can access.',
  operationId: "user'-s-account-memberships-list-memberships",
  request: {
    query: z.object({
      'account.name': IamPropertiesNameSchema.openapi({
        param: {
          name: 'account.name',
          in: 'query',
          schema: { $ref: '#/components/schemas/iam_properties-name' },
          required: false,
        },
      }).exactOptional(),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of memberships per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Number of memberships per page.',
        }),
      order: z
        .enum(['id', 'account.name', 'status'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              description: 'Field to order memberships by.',
              type: 'string',
              example: 'status',
              enum: ['id', 'account.name', 'status'],
            },
            required: false,
          },
          description: 'Field to order memberships by.',
          example: 'status',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Direction to order memberships.',
              type: 'string',
              example: 'desc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Direction to order memberships.',
          example: 'desc',
        }),
      name: IamPropertiesNameSchema.openapi({
        param: {
          name: 'name',
          in: 'query',
          schema: { $ref: '#/components/schemas/iam_properties-name' },
          required: false,
        },
      }).exactOptional(),
      status: z
        .enum(['accepted', 'pending', 'rejected'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            schema: {
              description: 'Status of this membership.',
              type: 'string',
              example: 'accepted',
              enum: ['accepted', 'pending', 'rejected'],
            },
            required: false,
          },
          description: 'Status of this membership.',
          example: 'accepted',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Memberships response',
      content: {
        'application/json': {
          schema: z.xor([
            IamCollectionMembershipResponseSchema,
            IamCollectionMembershipResponseWithPoliciesSchema,
          ]),
        },
      },
    },
    '4XX': {
      description: 'List Memberships response failure',
      content: { 'application/json': { schema: IamApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [] }],
})

