export const getOrganizationsOrganizationIdBillableUsageRoute = createRoute({
  method: 'get',
  path: '/organizations/{organization_id}/billable/usage',
  tags: ['Billable Usage V2'],
  summary: 'Get Organization Usage (Version 2, Alpha, Restricted)',
  description:
    'Returns cost and usage data for all accounts within an organization,\naligned with the [FinOps FOCUS v1.3](https://focus.finops.org/focus-specification/v1-3/)\nCost and Usage dataset specification.\n\nEach record represents one billable metric for one account on one day.\nThis includes all metered usage, including usage that falls within\nfree-tier allowances and may result in zero cost. The response\nincludes usage for every account belonging to the specified\norganization.\n\n**Note:** This endpoint serves `usage` records only; cost and pricing\nfields are absent from responses. Rated costs are available per\naccount via `POST /accounts/{account_id}/billable/usage` with\n`Metric: cost`.\n\nWhen `from` and `to` are omitted, defaults to the start of the current\nmonth through today. The maximum date range is 31 days.\n\nAn organization with no accounts, or an organization ID that does not\nexist, returns a successful response with an empty result set rather\nthan an error.\n',
  operationId: 'billable-usage-v2-get-organization-usage',
  request: {
    params: z.object({ organization_id: BillableUsageApiOrganizationIdParamsSchema }),
    query: z.object({
      from: BillableUsageApiV2FromParamsSchema,
      to: BillableUsageApiV2ToParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Organization usage data was successfully retrieved.',
      content: { 'application/json': { schema: BillableUsageApiV2UsageResponseSchema } },
    },
    '4XX': {
      description: 'Indicates the request failed.',
      content: { 'application/json': { schema: BillableUsageApiApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

