export const postProduceRoute = createRoute({
  method: 'post',
  path: '/produce',
  tags: ['workers_k2_other'],
  summary: 'Produce records',
  description:
    "Send to the stream's `endpoint`, `https://<stream_id>.k2.cloudflarestorage.com`. Appends a batch of records to the stream. The batch is written atomically, so either every record is stored or none are. Requests are limited to 5 MB, compressed and decompressed, and each record to 1 MB. Gzip bodies are accepted when `Content-Encoding` is `gzip`. Requires an API token with K2 produce permission unless the stream's HTTP input sets `authentication` to false. Errors use a `success` and `error` body instead of the `errors` array.",
  operationId: 'postK2Produce',
  request: {
    body: {
      content: { 'application/json': { schema: CloudflareK2K2ProduceRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Indicates that every record in the batch was stored.',
      content: { 'application/json': { schema: CloudflareK2K2ProduceResponseSchema } },
    },
    '4XX': {
      description:
        'Indicates an invalid request, a missing stream or HTTP input, or failed authorization. No records were stored.',
      content: { 'application/json': { schema: CloudflareK2K2ProduceErrorSchema } },
    },
    '5XX': {
      description: 'Indicates a server error. Retry with backoff when the error is retryable.',
      content: { 'application/json': { schema: CloudflareK2K2ProduceErrorSchema } },
    },
  },
  security: [{ api_token: [] }],
})

