export const getRadarCtLogsRoute = createRoute({
  method: 'get',
  path: '/radar/ct/logs',
  tags: ['Radar Certificate Transparency'],
  summary: 'List certificate logs',
  description: 'Retrieves a list of certificate logs.',
  operationId: 'radar-get-certificate-logs',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().positive(),
        )
        .default(5)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Limits the number of objects returned in the response.',
            schema: {
              description: 'Limits the number of objects returned in the response.',
              type: 'integer',
              example: 5,
              default: 5,
              exclusiveMinimum: true,
              minimum: 0,
            },
            required: false,
          },
          description: 'Limits the number of objects returned in the response.',
          example: 5,
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Skips the specified number of objects before fetching the results.',
            schema: {
              description: 'Skips the specified number of objects before fetching the results.',
              type: 'integer',
              example: 0,
              minimum: 0,
            },
            required: false,
          },
          description: 'Skips the specified number of objects before fetching the results.',
          example: 0,
        }),
      format: z
        .enum(['JSON', 'CSV'])
        .exactOptional()
        .openapi({
          param: {
            name: 'format',
            in: 'query',
            description: 'Format in which results will be returned.',
            schema: {
              description: 'Format in which results will be returned.',
              type: 'string',
              example: 'json',
              enum: ['JSON', 'CSV'],
            },
            required: false,
          },
          description: 'Format in which results will be returned.',
          example: 'json',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              result: z
                .object({
                  certificateLogs: z.array(
                    z
                      .object({
                        api: z
                          .enum(['RFC6962', 'STATIC'])
                          .openapi({
                            description: 'The API standard that the certificate log follows.',
                          }),
                        description: z
                          .string()
                          .openapi({
                            description: 'A brief description of the certificate log.',
                            example: "Google 'Argon2024' log",
                          }),
                        endExclusive: z.iso
                          .datetime({ offset: true })
                          .openapi({
                            description:
                              'The end date and time for when the log will stop accepting certificates.',
                            example: '2025-01-01T00:00:00Z',
                          }),
                        operator: z
                          .string()
                          .openapi({
                            description:
                              'The organization responsible for operating the certificate log.',
                            example: 'Google',
                          }),
                        slug: z
                          .string()
                          .openapi({
                            description:
                              'A URL-friendly, kebab-case identifier for the certificate log.',
                            example: 'argon2024',
                          }),
                        startInclusive: z.iso
                          .datetime({ offset: true })
                          .openapi({
                            description:
                              'The start date and time for when the log starts accepting certificates.',
                            example: '2024-01-01T00:00:00Z',
                          }),
                        state: z
                          .enum([
                            'USABLE',
                            'PENDING',
                            'QUALIFIED',
                            'READ_ONLY',
                            'RETIRED',
                            'REJECTED',
                          ])
                          .openapi({
                            description:
                              'The current state of the certificate log. More details about log states can be found here: https://googlechrome.github.io/CertificateTransparency/log_states.html',
                          }),
                        stateTimestamp: z.iso
                          .datetime({ offset: true })
                          .openapi({
                            description: 'Timestamp of when the log state was last updated.',
                            example: '2025-02-01T08:53:20Z',
                          }),
                        url: z
                          .string()
                          .openapi({
                            description: 'The URL for the certificate log.',
                            example: 'https://ct.googleapis.com/logs/us1/argon2024/',
                          }),
                      })
                      .openapi({
                        required: [
                          'slug',
                          'description',
                          'operator',
                          'api',
                          'state',
                          'stateTimestamp',
                          'startInclusive',
                          'endExclusive',
                          'url',
                        ],
                      }),
                  ),
                })
                .openapi({ required: ['certificateLogs'] }),
              success: z.boolean().openapi({ example: true }),
            })
            .openapi({ required: ['result', 'success'] }),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(z.object({ message: z.string() }).openapi({ required: ['message'] })),
              result: z.object({}),
              success: z.boolean().openapi({ example: false }),
            })
            .openapi({ required: ['result', 'success', 'errors'] }),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

