export const getRadarPostQuantumTlsSupportRoute = createRoute({
  method: 'get',
  path: '/radar/post_quantum/tls/support',
  tags: ['Radar Post-Quantum'],
  summary: 'Check Post-Quantum TLS support',
  description:
    'Tests whether a hostname or IP address supports Post-Quantum (PQ) TLS key exchange. Returns information about the negotiated key exchange algorithm, whether it uses PQ cryptography, and any detected TLS implementation bugs (Split ClientHello, HRR failure, etc.).',
  operationId: 'radar-get-post-quantum-tls-support',
  request: {
    query: z.object({
      host: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'host',
            in: 'query',
            description:
              'Hostname or IP address to test for Post-Quantum TLS support, optionally with port (defaults to 443).',
            required: true,
            schema: {
              description:
                'Hostname or IP address to test for Post-Quantum TLS support, optionally with port (defaults to 443).',
              type: 'string',
              example: 'cloudflare.com',
              minLength: 1,
            },
          },
          description:
            'Hostname or IP address to test for Post-Quantum TLS support, optionally with port (defaults to 443).',
          example: 'cloudflare.com',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              result: z
                .object({
                  bugs: z
                    .object({
                      hrrFailure: z
                        .boolean()
                        .openapi({
                          description:
                            'Server sends a HelloRetryRequest but fails to complete the handshake after the client sends the second ClientHello. Often caused by non-compliant TLS 1.3 implementations on shared hosting providers.',
                        }),
                      splitClientHello: z
                        .boolean()
                        .openapi({
                          description:
                            'Server rejects fragmented ClientHello caused by large PQ keyshare, but accepts classical (non-PQ) handshakes. Typically caused by middleboxes or firewalls that cannot reassemble split TLS ClientHello messages.',
                        }),
                      unknownKeyshare: z
                        .boolean()
                        .openapi({
                          description:
                            'Server cannot handle an unknown key exchange algorithm in the ClientHello keyshare extension. Compliant servers should respond with HelloRetryRequest for a supported algorithm.',
                        }),
                    })
                    .openapi({ required: ['splitClientHello', 'hrrFailure', 'unknownKeyshare'] }),
                  host: z.string().openapi({ description: 'The host that was tested' }),
                  kex: z
                    .number()
                    .openapi({ description: 'TLS CurveID of the negotiated key exchange' }),
                  kexName: z
                    .string()
                    .openapi({ description: 'Human-readable name of the key exchange algorithm' }),
                  pq: z
                    .boolean()
                    .openapi({
                      description:
                        'Whether the negotiated key exchange uses Post-Quantum cryptography (specifically X25519MLKEM768)',
                    }),
                })
                .openapi({ required: ['kex', 'kexName', 'pq', 'host', 'bugs'] }),
              success: z.boolean().openapi({ example: true }),
            })
            .openapi({ required: ['result', 'success'] }),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(z.object({ message: z.string() }).openapi({ required: ['message'] })),
              result: z.object({}),
              success: z.boolean().openapi({ example: false }),
            })
            .openapi({ required: ['result', 'success', 'errors'] }),
        },
      },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

