export const getZonesRoute = createRoute({
  method: 'get',
  path: '/zones',
  tags: ['Zone'],
  summary: 'List Zones',
  description:
    'Lists, searches, sorts, and filters your zones. Listing zones across more than 500 accounts\nis currently not allowed.\n',
  operationId: 'zones-get',
  request: {
    query: z.object({
      name: z
        .string()
        .max(253)
        .exactOptional()
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            schema: {
              description:
                'A domain name. Optional filter operators can be provided to extend refine the search:\n  * `equal` (default)\n  * `not_equal`\n  * `starts_with`\n  * `ends_with`\n  * `contains`\n  * `starts_with_case_sensitive`\n  * `ends_with_case_sensitive`\n  * `contains_case_sensitive`\n',
              type: 'string',
              maxLength: 253,
            },
            examples: {
              'Basic Query': { summary: 'Simple Query', value: 'example.com' },
              'Contains Query': { summary: 'Contains Query', value: 'contains:.org' },
              'Ends With Query': { summary: 'Ends With Query', value: 'ends_with:arpa' },
              'Starts With Query': { summary: 'Starts With Query', value: 'starts_with:dev' },
            },
            required: false,
          },
          description:
            'A domain name. Optional filter operators can be provided to extend refine the search:\n  * `equal` (default)\n  * `not_equal`\n  * `starts_with`\n  * `ends_with`\n  * `contains`\n  * `starts_with_case_sensitive`\n  * `ends_with_case_sensitive`\n  * `contains_case_sensitive`\n',
        }),
      status: z
        .enum(['initializing', 'pending', 'active', 'moved'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            schema: {
              description: 'Specify a zone status to filter by.',
              type: 'string',
              enum: ['initializing', 'pending', 'active', 'moved'],
            },
            required: false,
          },
          description: 'Specify a zone status to filter by.',
        }),
      type: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.enum(['full', 'partial', 'secondary', 'internal'])),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            schema: {
              description:
                'Zone types to filter by. Multiple types can be specified as a comma-separated list (e.g., ?type=full,partial,secondary). When this parameter is not provided, zones with type "internal" are excluded from the results.',
              type: 'array',
              items: { enum: ['full', 'partial', 'secondary', 'internal'], type: 'string' },
            },
            explode: false,
            style: 'form',
            required: false,
          },
          description:
            'Zone types to filter by. Multiple types can be specified as a comma-separated list (e.g., ?type=full,partial,secondary). When this parameter is not provided, zones with type "internal" are excluded from the results.',
        }),
      'account.id': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'account.id',
            in: 'query',
            schema: { description: 'Filter by an account ID.', type: 'string' },
            required: false,
          },
          description: 'Filter by an account ID.',
        }),
      'account.name': z
        .string()
        .max(253)
        .exactOptional()
        .openapi({
          param: {
            name: 'account.name',
            in: 'query',
            schema: {
              description:
                'An account Name. Optional filter operators can be provided to extend refine the search:\n  * `equal` (default)\n  * `not_equal`\n  * `starts_with`\n  * `ends_with`\n  * `contains`\n  * `starts_with_case_sensitive`\n  * `ends_with_case_sensitive`\n  * `contains_case_sensitive`\n',
              type: 'string',
              maxLength: 253,
            },
            examples: {
              'Basic Query': { summary: 'Simple Query', value: 'Dev Account' },
              'Contains Query': { summary: 'Contains Query', value: 'contains:Test' },
            },
            required: false,
          },
          description:
            'An account Name. Optional filter operators can be provided to extend refine the search:\n  * `equal` (default)\n  * `not_equal`\n  * `starts_with`\n  * `ends_with`\n  * `contains`\n  * `starts_with_case_sensitive`\n  * `ends_with_case_sensitive`\n  * `contains_case_sensitive`\n',
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of zones per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Number of zones per page.',
        }),
      order: z
        .enum(['name', 'status', 'account.id', 'account.name', 'plan.id'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              description: 'Field to order zones by.',
              type: 'string',
              example: 'status',
              enum: ['name', 'status', 'account.id', 'account.name', 'plan.id'],
            },
            required: false,
          },
          description: 'Field to order zones by.',
          example: 'status',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Direction to order zones.',
              type: 'string',
              example: 'desc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Direction to order zones.',
          example: 'desc',
        }),
      match: z
        .enum(['any', 'all'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'match',
            in: 'query',
            schema: {
              description: 'Whether to match all search requirements or at least one (any).',
              type: 'string',
              default: 'all',
              enum: ['any', 'all'],
            },
            required: false,
          },
          description: 'Whether to match all search requirements or at least one (any).',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Zones response.',
      content: {
        'application/json': {
          schema: ZonesApiResponseCommonSchema.and(
            z
              .object({ result_info: ZonesResultInfoSchema.exactOptional() })
              .openapi({ required: [] }),
          ).and(
            z
              .object({ result: z.array(ZonesZoneSchema).exactOptional() })
              .openapi({ required: [] }),
          ),
        },
      },
    },
    '4XX': {
      description: 'List Zones response failure.',
      content: { 'application/json': { schema: ZonesApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

