export const getZonesZoneIdAcmCustomTrustStoreRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/acm/custom_trust_store',
  tags: ['Custom Origin Trust Store'],
  summary: 'List Custom Origin Trust Store Details',
  description: 'Get Custom Origin Trust Store for a Zone.',
  operationId: 'custom-origin-trust-store-list-details',
  request: {
    params: z.object({
      zone_id: TlsCertificatesAndHostnamesIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/tls-certificates-and-hostnames_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of records per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Number of records per page.',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: {
              description: 'Limit to the number of records returned.',
              type: 'integer',
              example: 10,
            },
            required: false,
          },
          description: 'Limit to the number of records returned.',
          example: 10,
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            schema: { description: 'Offset the results.', type: 'integer', example: 10 },
            required: false,
          },
          description: 'Offset the results.',
          example: 10,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Custom Origin Trust Store Details response.',
      content: {
        'application/json': {
          schema: TlsCertificatesAndHostnamesCustomTrustStoreResponseCollectionSchema,
        },
      },
    },
    '4XX': {
      description: 'Custom Origin Trust Store response failure.',
      content: {
        'application/json': {
          schema: TlsCertificatesAndHostnamesCustomTrustStoreResponseCollectionSchema.and(
            TlsCertificatesAndHostnamesApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

