export const deleteZonesZoneIdApiGatewayOperationsRoute = createRoute({
  method: 'delete',
  path: '/zones/{zone_id}/api_gateway/operations',
  tags: ['API Shield Endpoint Management'],
  summary: 'Delete web or API operations',
  description: 'Deletes multiple web or API operations from endpoint management in one request.',
  operationId: 'api-shield-endpoint-management-delete-multiple-operations',
  request: {
    params: z.object({ zone_id: ApiShieldZoneIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .array(ApiShieldObjectWithOperationIdSchema)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              example: [
                { operation_id: 'b17c8043-99a0-4202-b7d9-8f7cdbee02cd' },
                { operation_id: '3818d821-5901-4147-a474-f5f5aec1d54e' },
              ],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Delete multiple operations response',
      content: { 'application/json': { schema: ApiShieldApiResponseCommonSchema } },
    },
    '4XX': {
      description: 'Delete multiple operations response failure',
      content: { 'application/json': { schema: ApiShieldApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

