export const getZonesZoneIdApiGatewaySchemasRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/api_gateway/schemas',
  tags: ['API Shield Endpoint Management'],
  summary: 'Export web and API operations as OpenAPI schemas',
  description:
    'Returns tracked web and API operations and their feature configuration rendered as OpenAPI schemas.',
  operationId:
    'api-shield-endpoint-management-retrieve-operations-and-features-as-open-api-schemas',
  request: {
    params: z.object({ zone_id: ApiShieldZoneIdParamsSchema }),
    query: z.object({
      host: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().openapi({ example: 'www.example.com' })).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'host',
            in: 'query',
            schema: {
              description: 'Receive schema only for the given host(s).',
              type: 'array',
              items: { example: 'www.example.com', type: 'string' },
              uniqueItems: true,
            },
            required: false,
          },
          description: 'Receive schema only for the given host(s).',
        }),
      feature: ApiShieldOperationFeatureParameterParamsSchema,
      include_schema_kind: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.literal('learned')).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'include_schema_kind',
            in: 'query',
            description: 'Schema kinds to include in exported OpenAPI schemas.',
            schema: {
              type: 'array',
              items: { enum: ['learned'], type: 'string' },
              uniqueItems: true,
            },
            explode: true,
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Retrieve operations and features as OpenAPI schemas response',
      content: { 'application/json': { schema: ApiShieldSchemaResponseWithThresholdsSchema } },
    },
    '4XX': {
      description: 'Retrieve operations and features as OpenAPI schemas response failure',
      content: { 'application/json': { schema: ApiShieldApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

