export const getZonesZoneIdClientCertificatesRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/client_certificates',
  tags: ['API Shield Client Certificates for a Zone'],
  summary: 'List Client Certificates',
  description:
    "List all of your Zone's API Shield mTLS Client Certificates by Status and/or using Pagination.",
  operationId: 'client-certificate-for-a-zone-list-client-certificates',
  request: {
    params: z.object({
      zone_id: TlsCertificatesAndHostnamesIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/tls-certificates-and-hostnames_identifier' },
        },
      }),
    }),
    query: z.object({
      status: z
        .enum(['all', 'active', 'pending_reactivation', 'pending_revocation', 'revoked'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            schema: {
              description: 'Client Certitifcate Status to filter results by.',
              type: 'string',
              example: 'all',
              enum: ['all', 'active', 'pending_reactivation', 'pending_revocation', 'revoked'],
            },
            required: false,
          },
          description: 'Client Certitifcate Status to filter results by.',
          example: 'all',
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of records per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Number of records per page.',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: {
              description: 'Limit to the number of records returned.',
              type: 'integer',
              example: 10,
            },
            required: false,
          },
          description: 'Limit to the number of records returned.',
          example: 10,
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            schema: { description: 'Offset the results.', type: 'integer', example: 10 },
            required: false,
          },
          description: 'Offset the results.',
          example: 10,
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Client Certificates Response.',
      content: {
        'application/json': {
          schema: TlsCertificatesAndHostnamesClientCertificateResponseCollectionSchema,
        },
      },
    },
    '4XX': {
      description: 'List Client Certificates Response Failure.',
      content: {
        'application/json': { schema: TlsCertificatesAndHostnamesApiResponseCommonFailureSchema },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

