export const getZonesZoneIdCustomCertificatesRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/custom_certificates',
  tags: ['Custom SSL for a Zone'],
  summary: 'List SSL Configurations',
  description:
    "List, search, and filter all of your custom SSL certificates. The higher priority will break ties across overlapping 'legacy_custom' certificates, but 'legacy_custom' certificates will always supercede 'sni_custom' certificates.",
  operationId: 'custom-ssl-for-a-zone-list-ssl-configurations',
  request: {
    params: z.object({
      zone_id: TlsCertificatesAndHostnamesIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/tls-certificates-and-hostnames_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Number of zones per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Number of zones per page.',
        }),
      match: z
        .enum(['any', 'all'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'match',
            in: 'query',
            schema: {
              description: 'Whether to match all search requirements or at least one (any).',
              type: 'string',
              default: 'all',
              enum: ['any', 'all'],
            },
            required: false,
          },
          description: 'Whether to match all search requirements or at least one (any).',
        }),
      status: z
        .enum(['active', 'expired', 'deleted', 'pending', 'initializing'])
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            schema: {
              description: "Status of the zone's custom SSL.",
              type: 'string',
              example: 'active',
              enum: ['active', 'expired', 'deleted', 'pending', 'initializing'],
              readOnly: true,
            },
            required: false,
          },
          description: "Status of the zone's custom SSL.",
          example: 'active',
          readOnly: true,
        }),
    }),
  },
  responses: {
    200: {
      description: 'List SSL Configurations response.',
      content: {
        'application/json': {
          schema: TlsCertificatesAndHostnamesCertificateResponseCollectionSchema,
        },
      },
    },
    '4XX': {
      description: 'List SSL Configurations response failure.',
      content: {
        'application/json': {
          schema: TlsCertificatesAndHostnamesCertificateResponseCollectionSchema.and(
            TlsCertificatesAndHostnamesApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

