export const postZonesZoneIdDnsRecordsRoute = createRoute({
  method: 'post',
  path: '/zones/{zone_id}/dns_records',
  tags: ['DNS Records for a Zone'],
  summary: 'Create DNS Record',
  description:
    'Create a new DNS record for a zone.\n\nNotes:\n- A/AAAA records cannot exist on the same name as CNAME records.\n- NS records cannot exist on the same name as any other record type.\n- Domain names are always represented in Punycode, even if Unicode\n  characters were used when creating the record.\n',
  operationId: 'dns-records-for-a-zone-create-dns-record',
  request: {
    params: z.object({
      zone_id: DnsRecordsIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/dns-records_identifier' },
        },
      }),
    }),
    query: z.object({ include_shadow_metadata: DnsRecordsIncludeShadowMetadataParamsSchema }),
    body: {
      content: { 'application/json': { schema: DnsRecordsDnsRecordPostSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Create DNS Record response',
      content: { 'application/json': { schema: DnsRecordsDnsResponseSingleSchema } },
    },
    '4XX': {
      description: 'Create DNS Record response failure',
      content: { 'application/json': { schema: DnsRecordsApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const postZonesZoneIdDnsRecordsBatchRoute = createRoute({
  method: 'post',
  path: '/zones/{zone_id}/dns_records/batch',
  tags: ['DNS Records for a Zone'],
  summary: 'Batch DNS Records',
  description:
    'Send a Batch of DNS Record API calls to be executed together.\n\nNotes:\n- Although Cloudflare will execute the batched operations in a single database transaction, Cloudflare\'s distributed KV store must treat each record change as a single key-value pair. This means that the propagation of changes is not atomic. See [the documentation](https://developers.cloudflare.com/dns/manage-dns-records/how-to/batch-record-changes/ "Batch DNS records") for more information.\n- The operations you specify within the /batch request body are always executed in the following order:\n\n    - Deletes\n    - Patches\n    - Puts\n    - Posts\n',
  operationId: 'dns-records-for-a-zone-batch-dns-records',
  request: {
    params: z.object({
      zone_id: DnsRecordsIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/dns-records_identifier' },
        },
      }),
    }),
    query: z.object({ include_shadow_metadata: DnsRecordsIncludeShadowMetadataParamsSchema }),
    body: {
      content: { 'application/json': { schema: DnsRecordsDnsRequestBatchObjectSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Batch DNS Records response',
      content: { 'application/json': { schema: DnsRecordsDnsResponseBatchSchema } },
    },
    '4XX': {
      description: 'Batch DNS Records response failure',
      content: { 'application/json': { schema: DnsRecordsApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

