export const getZonesZoneIdEmailRoutingRulesRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/email/routing/rules',
  tags: ['Email Routing routing rules'],
  summary: 'List routing rules',
  description: 'Lists the routing rules that match incoming messages for a zone.',
  operationId: 'email-routing-routing-rules-list-routing-rules',
  request: {
    params: z.object({
      zone_id: EmailIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/email_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description: 'Page number of paginated results.',
              type: 'number',
              default: 1,
              minimum: 1,
            },
            required: false,
          },
          description: 'Page number of paginated results.',
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(5).max(50),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Maximum number of results per page.',
              type: 'number',
              default: 20,
              maximum: 50,
              minimum: 5,
            },
            required: false,
          },
          description: 'Maximum number of results per page.',
        }),
      enabled: z
        .stringbool()
        .pipe(z.union([z.literal(true), z.literal(false)]))
        .exactOptional()
        .openapi({
          param: {
            name: 'enabled',
            in: 'query',
            schema: {
              description: 'Filter by enabled routing rules.',
              type: 'boolean',
              example: true,
              enum: [true, false],
            },
            required: false,
          },
          description: 'Filter by enabled routing rules.',
          example: true,
        }),
    }),
  },
  responses: {
    200: {
      description: 'List routing rules response',
      content: { 'application/json': { schema: EmailRulesResponseCollectionSchema } },
    },
    403: { description: 'Authentication error or missing zone routing rule list permission.' },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

