export const getZonesZoneIdEmailSendingSuppressionRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/email/sending/suppression',
  tags: ['Email Sending suppressions'],
  summary: 'List zone email suppressions',
  description: 'Lists email suppressions for the specified zone.',
  operationId: 'get_publicListSuppressionZoneSending',
  request: {
    params: z.object({
      zone_id: z
        .string()
        .openapi({
          param: {
            name: 'zone_id',
            in: 'path',
            required: true,
            schema: { type: 'string', example: '88228822' },
          },
          example: '88228822',
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: { type: 'integer', default: 1, minimum: 0 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0).max(1000),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: { type: 'integer', default: 100, maximum: 1000, minimum: 0 },
            required: false,
          },
        }),
      order: z
        .enum(['email', 'expires_at', 'created_at'])
        .default('created_at')
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              type: 'string',
              default: 'created_at',
              enum: ['email', 'expires_at', 'created_at'],
            },
            required: false,
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: { type: 'string', default: 'desc', enum: ['asc', 'desc'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns suppressed emails.',
      content: {
        'application/json': {
          schema: z
            .object({
              page: z.int().openapi({ example: 0 }),
              per_page: z.int().openapi({ example: 100 }),
              result: z.array(
                z
                  .object({
                    created_at: z.iso.datetime({ offset: true }),
                    email: z.email().openapi({ example: 'user@example.com' }),
                    expires_at: z.iso.datetime({ offset: true }).nullable(),
                    id: z.uuid(),
                    reason: z.string().openapi({ example: 'hard_bounce' }),
                    zones: z.array(z.string()).default([]).exactOptional(),
                  })
                  .openapi({ required: ['id', 'email', 'reason', 'created_at', 'expires_at'] }),
              ),
              total: z.int().openapi({ example: 1 }),
            })
            .openapi({ required: ['page', 'per_page', 'total', 'result'] }),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(z.string()),
              success: z.boolean().openapi({ example: false }),
            })
            .openapi({ required: ['success', 'errors'] }),
        },
      },
    },
  },
  deprecated: true,
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

