export const postZonesZoneIdEnvironmentsEnvironmentIdInvalidateCacheRoute = createRoute({
  method: 'post',
  path: '/zones/{zone_id}/environments/{environment_id}/invalidate_cache',
  tags: ['Zone'],
  summary: 'Invalidate Cached Content by Environment',
  description:
    "Marks cached content as stale for one environment of the zone. Content cached for the zone's other environments, including production, is not affected. Otherwise this works like `POST /zones/{zone_id}/invalidate_cache`: the next request for invalidated content makes Cloudflare revalidate it with your origin, and the request body takes the same fields.\n\nEnvironments are part of [Version Management](https://developers.cloudflare.com/version-management/). To delete the content instead, use `POST /zones/{zone_id}/environments/{environment_id}/purge_cache`.\n\nInvalidating by URL (`files`) does not work for environments that select requests by IP address, country, ASN, or threat score, and fails with error `1136`. Use `tags`, `hosts`, `prefixes`, or `purge_everything` for those environments.\n\n### Availability and limits\n\nRate limits and the number of items you can send in one request depend on your plan. See [Purge cache: availability and limits](https://developers.cloudflare.com/cache/how-to/purge-cache/#availability-and-limits).\n",
  operationId: 'zone-environment-invalidate',
  request: {
    params: z.object({
      zone_id: CachePurgeIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          description: 'The zone ID.',
          required: true,
          schema: { $ref: '#/components/schemas/cache-purge_identifier' },
        },
      }),
      environment_id: CachePurgeIdentifierSchema.openapi({
        param: {
          name: 'environment_id',
          in: 'path',
          description: 'The environment ID, from Version Management.',
          required: true,
          schema: { $ref: '#/components/schemas/cache-purge_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z.union([
            CachePurgeFlexPurgeByTagsSchema,
            CachePurgeFlexPurgeByHostnamesSchema,
            CachePurgeFlexPurgeByPrefixesSchema,
            CachePurgeEverythingSchema,
            CachePurgeSingleFileSchema,
            CachePurgeSingleFileWithUrlAndHeadersSchema,
          ]),
          examples: {
            'Cache tags': {
              summary: 'Content with these Cache-Tag values',
              value: { tags: ['product-1234', 'homepage'] },
            },
            Everything: { summary: 'All cached content', value: { purge_everything: true } },
            Hostnames: {
              summary: 'Content cached for these hostnames',
              value: { hosts: ['www.example.com', 'images.example.com'] },
            },
            Prefixes: {
              summary: 'Content under these URL prefixes',
              value: { prefixes: ['www.example.com/blog/', 'images.example.com/avatars/'] },
            },
            URLs: {
              summary: 'Specific URLs',
              value: {
                files: [
                  'https://www.example.com/css/styles.css',
                  'https://www.example.com/js/index.js',
                ],
              },
            },
            'URLs with cache key headers': {
              summary: 'URLs cached with request headers in the cache key',
              value: {
                files: [
                  {
                    headers: {
                      'Accept-Language': 'zh-CN',
                      'CF-Device-Type': 'desktop',
                      'CF-IPCountry': 'US',
                    },
                    url: 'https://www.example.com/cat_picture.jpg',
                  },
                  {
                    headers: {
                      'Accept-Language': 'en-US',
                      'CF-Device-Type': 'mobile',
                      'CF-IPCountry': 'DE',
                    },
                    url: 'https://www.example.com/dog_picture.jpg',
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Cloudflare accepted the request. If Cloudflare could not accept some of the items, `success` is `false` and `errors` lists them, followed by error `1016`.\n',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema,
          example: {
            errors: [],
            messages: [],
            result: { id: '023e105f4ecef8ad9ca31a8372d0c353' },
            success: true,
          },
        },
      },
    },
    '4XX': {
      description: 'Cloudflare rejected the request. `errors` explains why.',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema.and(CachePurgeApiResponseCommonFailureSchema),
          examples: {
            'Invalid request body': {
              summary: 'purge_everything sent with other fields (HTTP 400)',
              value: {
                errors: [
                  {
                    code: 1092,
                    message:
                      'Request cannot contain "purge_everything" and any of "files", "tags", "hosts" or "prefixes"',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
            'Rate limited': {
              summary: 'Rate limit reached (HTTP 429)',
              value: {
                errors: [
                  {
                    code: 1134,
                    message:
                      'Unable to purge, rate limit reached. Please wait and consider throttling your request speed',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

