export const getZonesZoneIdHoldZoneNameRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/hold/{zone_name}',
  tags: ['Zone Holds'],
  summary: 'Get Zone Hold by Zone Name',
  description:
    'Retrieve whether a given hostname is subject to a zone hold, and metadata about the hold.\nThis endpoint checks whether the given hostname (or any of its ancestor domains) is blocked\nby an active zone hold. If a hold with `include_subdomains` is active on an ancestor domain,\nthat hold is returned. This endpoint is used internally by SSL/COMS to check hold status\nduring zone activation.',
  operationId: 'zones-0-hold-zone-name-get',
  request: {
    params: z.object({
      zone_id: ZonesIdentifier_2Schema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          description:
            'Zone identifier. Consumed by the API gateway for routing; the backend\nhandler does not use this value directly.',
          required: true,
          schema: { $ref: '#/components/schemas/zones_identifier-2' },
        },
      }),
      zone_name: z
        .string()
        .regex(/^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/)
        .max(253)
        .openapi({
          param: {
            name: 'zone_name',
            in: 'path',
            description:
              'The hostname to check for a zone hold. May be a subdomain (e.g. `subdomain.example.com`)\nor an apex domain (e.g. `example.com`). The service checks the hostname and its ancestor\ndomains for active holds with `include_subdomains` enabled.',
            required: true,
            schema: {
              type: 'string',
              example: 'subdomain.example.com',
              maxLength: 253,
              pattern: '^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,}$',
            },
          },
          example: 'subdomain.example.com',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: z
            .object({
              hold: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether the hostname is currently subject to a zone hold.',
                  example: true,
                }),
              hold_after: z.iso
                .datetime({ offset: true })
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The RFC3339-formatted timestamp at which the hold will be automatically\nre-enabled, if the hold was temporarily disabled. Null if the hold is\npermanently enabled or not set.',
                  example: '2023-01-31T15:56:36Z',
                }),
              include_subdomains: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether the hold extends to block subdomains of the held zone.',
                  example: false,
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    '4XX': {
      description: 'Client Error',
      content: { 'application/json': { schema: ZonesApiResponseCommonFailure_2Schema } },
    },
  },
  security: [],
})

