export const postZonesZoneIdInvalidateCacheRoute = createRoute({
  method: 'post',
  path: '/zones/{zone_id}/invalidate_cache',
  tags: ['Zone'],
  summary: 'Invalidate Cached Content',
  description:
    'Marks cached content as stale in every Cloudflare data center and cache tier, including Cache Reserve. The content stays in cache. The next request for it makes Cloudflare revalidate it with your origin, using the `ETag` and `Last-Modified` values it was cached with:\n\n- If your origin answers `304 Not Modified`, Cloudflare serves the cached copy without downloading it again, and `CF-Cache-Status` is `REVALIDATED`.\n- If your origin sends a full response, Cloudflare serves and caches the new content, and `CF-Cache-Status` is `EXPIRED`.\n\nWith Tiered Cache, each tier revalidates with the tier above it, so a visitor can see `EXPIRED` even when your origin answered `304`.\n\nUntil content is revalidated, your `stale-while-revalidate` and `stale-if-error` directives still apply, counted from the time you invalidated it. For example, if your origin fails during revalidation, Cloudflare can keep serving the stale copy for the `stale-if-error` window.\n\n### Invalidate or purge?\n\n- **Invalidate** when content may not have changed, for example after a deploy. Unchanged content costs your origin a `304` instead of a full response. That saving needs an origin that sends `ETag` or `Last-Modified` and answers conditional requests. Otherwise, every revalidation downloads the full response.\n- **Purge**, with `POST /zones/{zone_id}/purge_cache`, when content must not be served again, for example content you removed for legal or security reasons.\n\nInvalidating takes the same request bodies as purging, needs the same permission, and counts against the same rate limits. After a broad invalidation, such as `purge_everything`, expect more conditional requests to your origin while visitors request the invalidated content again.\n\n### Choose what to invalidate\n\nSend one of these fields in the request body:\n\n- `files`: specific URLs. If your cache key includes request headers, send each URL with the header values it was cached with.\n- `tags`: all content whose `Cache-Tag` response header contains one of the tags.\n- `hosts`: all content cached for the hostnames.\n- `prefixes`: all content whose URL starts with one of the prefixes.\n- `purge_everything`: all cached content in the zone.\n\n### Check the result\n\nA `200` response with `success: true` means Cloudflare accepted the request. To check, request an invalidated URL and confirm that the `CF-Cache-Status` response header is `REVALIDATED` or `EXPIRED`.\n\n### Availability and limits\n\nRate limits and the number of items you can send in one request depend on your plan. See [Purge cache: availability and limits](https://developers.cloudflare.com/cache/how-to/purge-cache/#availability-and-limits).\n',
  operationId: 'zone-invalidate',
  request: {
    params: z.object({
      zone_id: CachePurgeIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          description: 'The zone ID.',
          required: true,
          schema: { $ref: '#/components/schemas/cache-purge_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z.union([
            CachePurgeFlexPurgeByTagsSchema,
            CachePurgeFlexPurgeByHostnamesSchema,
            CachePurgeFlexPurgeByPrefixesSchema,
            CachePurgeEverythingSchema,
            CachePurgeSingleFileSchema,
            CachePurgeSingleFileWithUrlAndHeadersSchema,
          ]),
          examples: {
            'Cache tags': {
              summary: 'Content with these Cache-Tag values',
              value: { tags: ['product-1234', 'homepage'] },
            },
            Everything: { summary: 'All cached content', value: { purge_everything: true } },
            Hostnames: {
              summary: 'Content cached for these hostnames',
              value: { hosts: ['www.example.com', 'images.example.com'] },
            },
            Prefixes: {
              summary: 'Content under these URL prefixes',
              value: { prefixes: ['www.example.com/blog/', 'images.example.com/avatars/'] },
            },
            URLs: {
              summary: 'Specific URLs',
              value: {
                files: [
                  'https://www.example.com/css/styles.css',
                  'https://www.example.com/js/index.js',
                ],
              },
            },
            'URLs with cache key headers': {
              summary: 'URLs cached with request headers in the cache key',
              value: {
                files: [
                  {
                    headers: {
                      'Accept-Language': 'zh-CN',
                      'CF-Device-Type': 'desktop',
                      'CF-IPCountry': 'US',
                    },
                    url: 'https://www.example.com/cat_picture.jpg',
                  },
                  {
                    headers: {
                      'Accept-Language': 'en-US',
                      'CF-Device-Type': 'mobile',
                      'CF-IPCountry': 'DE',
                    },
                    url: 'https://www.example.com/dog_picture.jpg',
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Cloudflare accepted the request. If Cloudflare could not accept some of the items, `success` is `false` and `errors` lists them, followed by error `1016`.\n',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema,
          example: {
            errors: [],
            messages: [],
            result: { id: '023e105f4ecef8ad9ca31a8372d0c353' },
            success: true,
          },
        },
      },
    },
    '4XX': {
      description: 'Cloudflare rejected the request. `errors` explains why.',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema.and(CachePurgeApiResponseCommonFailureSchema),
          examples: {
            'Invalid request body': {
              summary: 'purge_everything sent with other fields (HTTP 400)',
              value: {
                errors: [
                  {
                    code: 1092,
                    message:
                      'Request cannot contain "purge_everything" and any of "files", "tags", "hosts" or "prefixes"',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
            'Rate limited': {
              summary: 'Rate limit reached (HTTP 429)',
              value: {
                errors: [
                  {
                    code: 1134,
                    message:
                      'Unable to purge, rate limit reached. Please wait and consider throttling your request speed',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

