export const getZonesZoneIdLogsReceivedRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/logs/received',
  tags: ['Logs Received'],
  summary: 'Get logs received',
  description:
    'The `/received` api route allows customers to retrieve their edge HTTP logs. The basic access pattern is "give me all the logs for zone Z for minute M", where the minute M refers to the time records were received at Cloudflare\'s central data center. `start` is inclusive, and `end` is exclusive. Because of that, to get all data, at minutely cadence, starting at 10AM, the proper values are: `start=2018-05-20T10:00:00Z&end=2018-05-20T10:01:00Z`, then `start=2018-05-20T10:01:00Z&end=2018-05-20T10:02:00Z` and so on; the overlap will be handled properly.',
  operationId: 'get-zones-zone_id-logs-received',
  request: {
    params: z.object({
      zone_id: LogshareIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/logshare_identifier' },
        },
      }),
    }),
    query: z.object({
      start: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(LogshareStartSchema)
        .exactOptional()
        .openapi({
          param: {
            name: 'start',
            in: 'query',
            schema: { $ref: '#/components/schemas/logshare_start' },
            required: false,
          },
        }),
      end: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(LogshareEndSchema).openapi({
        param: {
          name: 'end',
          in: 'query',
          required: true,
          schema: { $ref: '#/components/schemas/logshare_end' },
        },
      }),
      fields: LogshareFieldsSchema.openapi({
        param: {
          name: 'fields',
          in: 'query',
          schema: { $ref: '#/components/schemas/logshare_fields' },
          required: false,
        },
      }).exactOptional(),
      sample: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          LogshareSampleSchema.openapi({
            param: {
              name: 'sample',
              in: 'query',
              schema: { $ref: '#/components/schemas/logshare_sample' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          LogshareCountSchema.openapi({
            param: {
              name: 'count',
              in: 'query',
              schema: { $ref: '#/components/schemas/logshare_count' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      timestamps: LogshareTimestampsSchema.openapi({
        param: {
          name: 'timestamps',
          in: 'query',
          schema: { $ref: '#/components/schemas/logshare_timestamps' },
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'Get logs received response',
      content: { 'application/json': { schema: LogshareLogsResponseJsonLinesSchema } },
    },
    '4XX': {
      description: 'Get logs received response failure',
      content: { 'application/json': { schema: LogshareApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_email: [], api_key: [], api_token: [] }],
})

