export const putZonesZoneIdPrecursorRoute = createRoute({
  method: 'put',
  path: '/zones/{zone_id}/precursor',
  tags: ['Precursor'],
  summary: 'Update Zone Precursor Config',
  description:
    'Updates the Precursor configuration for a zone.\n\n`mode` controls whether Precursor detection is off, monitoring, or\narmed. `show_interstitial` controls the zone-level response when armed.\n`rules` is the ordered list of overrides for matching requests.\n\nThis is a partial update: only the fields present in the request body\nare changed.\n\n- Sending an empty array (`[]`) clears all rules.\n- At least one of `mode`, `show_interstitial`, or `rules` must be\n  present; an empty body (`{}`) is rejected with `400`.\n- Rule `id` is read-only (assigned by Cloudflare) and ignored on input.\n- Rule `show_interstitial` is required and controls the response for\n  requests that match that rule.\n- Rule `expression` is limited to 4000 characters. The limit applies to\n  each rule individually, not to the combined size of all rules.\n',
  operationId: 'precursor-for-a-zone-update-config',
  request: {
    headers: z.object({
      'Cloudflare-Version': z
        .literal('1.0')
        .default('1.0')
        .openapi({
          param: {
            name: 'Cloudflare-Version',
            in: 'header',
            description: 'Selects the split Precursor API schema.',
            required: true,
            schema: {
              type: 'string',
              default: '1.0',
              enum: ['1.0'],
              'x-stainless-const': true,
              'x-stainless-useDefault': true,
            },
          },
          'x-stainless-const': true,
          'x-stainless-useDefault': true,
        }),
    }),
    params: z.object({
      zone_id: PrecursorIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/precursor_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: PrecursorPrecursorConfigSchema,
          examples: {
            monitor: {
              summary: 'Monitor detections without affecting bot scores',
              value: { mode: 'monitor' },
            },
            off: { summary: 'Disable precursor for the zone', value: { mode: 'off' } },
            'rules-only': {
              summary: 'Replace rules while leaving zone-level settings unchanged',
              value: {
                rules: [
                  {
                    description: 'Show an interstitial on the login path',
                    enabled: true,
                    expression: 'http.request.uri.path eq "/login"',
                    show_interstitial: true,
                  },
                ],
              },
            },
            'with-rules': {
              summary: 'Arm detection and configure an interstitial override',
              value: {
                mode: 'arm',
                rules: [
                  {
                    description: 'Show an interstitial on the login path',
                    enabled: true,
                    expression: 'http.request.uri.path eq "/login"',
                    show_interstitial: true,
                  },
                ],
                show_interstitial: false,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Update Precursor response.',
      content: { 'application/json': { schema: PrecursorPrecursorConfigResponseBodySchema } },
    },
    '4XX': {
      description: 'Update Precursor response failure.',
      content: {
        'application/json': {
          schema: PrecursorPrecursorConfigResponseBodySchema.and(
            PrecursorApiResponseCommonFailureSchema,
          ),
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const postZonesZoneIdPurgeCacheRoute = createRoute({
  method: 'post',
  path: '/zones/{zone_id}/purge_cache',
  tags: ['Zone'],
  summary: 'Purge Cached Content',
  description:
    'Deletes cached content in every Cloudflare data center and cache tier, including Cache Reserve. The next request for purged content is a cache `MISS`: Cloudflare fetches the full response from your origin and caches it again. Cloudflare does not serve purged content from cache again, even if your origin is unavailable.\n\nTo keep content cached and have Cloudflare revalidate it with your origin instead, use `POST /zones/{zone_id}/invalidate_cache`.\n\n### Choose what to purge\n\nSend one of these fields in the request body:\n\n- `files`: specific URLs. If your cache key includes request headers, send each URL with the header values it was cached with.\n- `tags`: all content whose `Cache-Tag` response header contains one of the tags.\n- `hosts`: all content cached for the hostnames.\n- `prefixes`: all content whose URL starts with one of the prefixes.\n- `purge_everything`: all cached content in the zone.\n\n### Check the result\n\nA `200` response with `success: true` means Cloudflare accepted the request. It does not confirm that any content was cached or removed. To check, request a purged URL and confirm that the `CF-Cache-Status` response header is `MISS`.\n\n### Availability and limits\n\nRate limits and the number of items you can send in one request depend on your plan. See [Purge cache: availability and limits](https://developers.cloudflare.com/cache/how-to/purge-cache/#availability-and-limits).\n',
  operationId: 'zone-purge',
  request: {
    params: z.object({
      zone_id: CachePurgeIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          description: 'The zone ID.',
          required: true,
          schema: { $ref: '#/components/schemas/cache-purge_identifier' },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z.union([
            CachePurgeFlexPurgeByTagsSchema,
            CachePurgeFlexPurgeByHostnamesSchema,
            CachePurgeFlexPurgeByPrefixesSchema,
            CachePurgeEverythingSchema,
            CachePurgeSingleFileSchema,
            CachePurgeSingleFileWithUrlAndHeadersSchema,
          ]),
          examples: {
            'Cache tags': {
              summary: 'Content with these Cache-Tag values',
              value: { tags: ['product-1234', 'homepage'] },
            },
            Everything: { summary: 'All cached content', value: { purge_everything: true } },
            Hostnames: {
              summary: 'Content cached for these hostnames',
              value: { hosts: ['www.example.com', 'images.example.com'] },
            },
            Prefixes: {
              summary: 'Content under these URL prefixes',
              value: { prefixes: ['www.example.com/blog/', 'images.example.com/avatars/'] },
            },
            URLs: {
              summary: 'Specific URLs',
              value: {
                files: [
                  'https://www.example.com/css/styles.css',
                  'https://www.example.com/js/index.js',
                ],
              },
            },
            'URLs with cache key headers': {
              summary: 'URLs cached with request headers in the cache key',
              value: {
                files: [
                  {
                    headers: {
                      'Accept-Language': 'zh-CN',
                      'CF-Device-Type': 'desktop',
                      'CF-IPCountry': 'US',
                    },
                    url: 'https://www.example.com/cat_picture.jpg',
                  },
                  {
                    headers: {
                      'Accept-Language': 'en-US',
                      'CF-Device-Type': 'mobile',
                      'CF-IPCountry': 'DE',
                    },
                    url: 'https://www.example.com/dog_picture.jpg',
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Cloudflare accepted the request. If Cloudflare could not accept some of the items, `success` is `false` and `errors` lists them, followed by error `1016`.\n',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema,
          example: {
            errors: [],
            messages: [],
            result: { id: '023e105f4ecef8ad9ca31a8372d0c353' },
            success: true,
          },
        },
      },
    },
    '4XX': {
      description: 'Cloudflare rejected the request. `errors` explains why.',
      content: {
        'application/json': {
          schema: CachePurgeApiResponseSingleIdSchema.and(CachePurgeApiResponseCommonFailureSchema),
          examples: {
            'Invalid request body': {
              summary: 'purge_everything sent with other fields (HTTP 400)',
              value: {
                errors: [
                  {
                    code: 1092,
                    message:
                      'Request cannot contain "purge_everything" and any of "files", "tags", "hosts" or "prefixes"',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
            'Rate limited': {
              summary: 'Rate limit reached (HTTP 429)',
              value: {
                errors: [
                  {
                    code: 1134,
                    message:
                      'Unable to purge, rate limit reached. Please wait and consider throttling your request speed',
                  },
                ],
                messages: [],
                result: null,
                success: false,
              },
            },
          },
        },
      },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

export const getZonesZoneIdRateLimitAnalyticsRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/rate_limit_analytics',
  tags: ['Rate Limiting Analytics'],
  summary: 'Get Rate Limiting Analytics',
  description:
    'Returns rate limiting analytics for a zone over the specified time period.\nThe time period divides into time segments of a given length. Each segment\ncontains total action counts and action counts broken down by colo.',
  operationId: 'rate-limit-analytics-get-zone-analytics',
  request: {
    params: z.object({
      zone_id: z
        .string()
        .regex(/^[0-9a-f]{32}$/)
        .max(32)
        .openapi({
          param: {
            name: 'zone_id',
            in: 'path',
            description: 'Identifier of the zone.',
            required: true,
            schema: {
              type: 'string',
              example: '023e105f4ecef8ad9ca31a8372d0c353',
              maxLength: 32,
              pattern: '^[0-9a-f]{32}$',
            },
          },
          example: '023e105f4ecef8ad9ca31a8372d0c353',
        }),
    }),
    query: z.object({
      since: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'since',
            in: 'query',
            description:
              'The start of the queried time period. Time must be rounded to the time\nsegment boundary and formatted as RFC 3339.',
            required: true,
            schema: { type: 'string', format: 'date-time', example: '2024-01-01T00:00:00Z' },
          },
          example: '2024-01-01T00:00:00Z',
        }),
      until: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'until',
            in: 'query',
            description:
              'The exclusive end of the queried time period. Time must be rounded to the\ntime segment boundary and formatted as RFC 3339.',
            required: true,
            schema: { type: 'string', format: 'date-time', example: '2024-01-02T00:00:00Z' },
          },
          example: '2024-01-02T00:00:00Z',
        }),
      time_delta: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.union([z.literal(60), z.literal(3600), z.literal(86400), z.literal(2592000)]),
        )
        .openapi({
          param: {
            name: 'time_delta',
            in: 'query',
            description:
              'Length (in seconds) of each time segment dividing the entire time period.\nAccepted values are 60 (minute), 3600 (hour), 86400 (day), and 2592000 (month).',
            required: true,
            schema: { type: 'integer', example: 3600, enum: [60, 3600, 86400, 2592000] },
          },
          example: 3600,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: RlanalyticsRateLimitAnalyticsSchema } },
    },
    400: {
      description: 'Bad request. Invalid or missing parameters.',
      content: { 'application/json': { schema: RlanalyticsApiResponseCommonFailureSchema } },
    },
    401: {
      description: 'Unauthorized. Missing or invalid authentication credentials.',
      content: { 'application/json': { schema: RlanalyticsApiResponseCommonFailureSchema } },
    },
    403: {
      description: 'Forbidden. Insufficient permissions for the requested resource.',
      content: { 'application/json': { schema: RlanalyticsApiResponseCommonFailureSchema } },
    },
    500: {
      description: 'Internal server error.',
      content: { 'application/json': { schema: RlanalyticsApiResponseCommonFailureSchema } },
    },
  },
  deprecated: true,
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

