export const getZonesZoneIdRulesetsRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/rulesets',
  tags: ['Zone Rulesets'],
  summary: 'List zone rulesets',
  description: 'Fetches all rulesets at the zone level.',
  operationId: 'listZoneRulesets',
  request: {
    params: z.object({
      zone_id: RulesetsZoneIdSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/rulesets_ZoneId' },
        },
      }),
    }),
    query: z.object({
      cursor: RulesetsCursorSchema.openapi({
        param: {
          name: 'cursor',
          in: 'query',
          schema: { $ref: '#/components/schemas/rulesets_Cursor' },
          required: false,
        },
      }).exactOptional(),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          RulesetsPerPageSchema.openapi({
            param: {
              name: 'per_page',
              in: 'query',
              schema: { $ref: '#/components/schemas/rulesets_PerPage' },
              required: false,
            },
          }),
        )
        .exactOptional(),
    }),
  },
  responses: { 200: RulesetsRulesetsResponse, '4XX': RulesetsFailureResponse },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { api_email: [], api_key: [] }],
})

