export const getZonesZoneIdSettingsZarazHistoryRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/settings/zaraz/history',
  tags: ['Zaraz'],
  summary: 'List Zaraz historical configuration records',
  description: 'Lists a history of published Zaraz configuration records for a zone.',
  operationId: 'get-zones-zone_identifier-zaraz-history',
  request: {
    params: z.object({
      zone_id: ZarazIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/zaraz_identifier' },
        },
      }),
    }),
    query: z.object({
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Ordinal number to start listing the results with. Default value is 0.',
            schema: { type: 'integer', minimum: 0 },
            example: 0,
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Maximum amount of results to list. Default value is 10.',
            schema: { type: 'integer', minimum: 1 },
            example: 10,
            required: false,
          },
        }),
      sortField: z
        .enum(['id', 'user_id', 'description', 'created_at', 'updated_at'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sortField',
            in: 'query',
            description: 'The field to sort by. Default is updated_at.',
            schema: {
              type: 'string',
              enum: ['id', 'user_id', 'description', 'created_at', 'updated_at'],
            },
            example: 'updated_at',
            required: false,
          },
        }),
      sortOrder: z
        .enum(['DESC', 'ASC'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sortOrder',
            in: 'query',
            description: 'Sorting order. Default is DESC.',
            schema: { type: 'string', enum: ['DESC', 'ASC'] },
            example: 'DESC',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Zaraz historical configuration records response.',
      content: { 'application/json': { schema: ZarazZarazHistoryResponseSchema } },
    },
    '4XX': {
      description: 'List Zaraz historical configuration records failure.',
      content: { 'application/json': { schema: ZarazApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

