export const getZonesZoneIdSettingsZarazHistoryConfigsRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/settings/zaraz/history/configs',
  tags: ['Zaraz'],
  summary: 'Get Zaraz historical configurations by ID(s)',
  description: 'Gets a history of published Zaraz configurations by ID(s) for a zone.',
  operationId: 'get-zones-zone_identifier-zaraz-config-history',
  request: {
    params: z.object({
      zone_id: ZarazIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/zaraz_identifier' },
        },
      }),
    }),
    query: z.object({
      ids: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: 'Comma separated list of Zaraz configuration IDs.',
            required: true,
            schema: { type: 'array', items: { type: 'integer' } },
            example: [12345, 23456],
            explode: false,
            style: 'form',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Get Zaraz historical configurations by ID(s) response.',
      content: { 'application/json': { schema: ZarazZarazConfigHistoryResponseSchema } },
    },
    '4XX': {
      description: 'Get Zaraz historical configurations by ID(s) failure.',
      content: { 'application/json': { schema: ZarazApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

