export const getZonesZoneIdSnippetsRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/snippets',
  tags: ['Zone Snippets'],
  summary: 'List zone snippets',
  description: 'Fetches all snippets belonging to the zone.',
  operationId: 'listZoneSnippets',
  request: {
    params: z.object({
      zone_id: SnippetsZoneIdSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/snippets_ZoneId' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          SnippetsPageSchema.openapi({
            param: {
              name: 'page',
              in: 'query',
              schema: { $ref: '#/components/schemas/snippets_Page' },
              required: false,
            },
          }),
        )
        .exactOptional(),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          SnippetsPerPageSchema.openapi({
            param: {
              name: 'per_page',
              in: 'query',
              schema: { $ref: '#/components/schemas/snippets_PerPage' },
              required: false,
            },
          }),
        )
        .exactOptional(),
    }),
  },
  responses: {
    200: SnippetsSnippetsResponse,
    '4XX': SnippetsFailureResponse,
    '5XX': SnippetsFailureResponse,
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }, { api_email: [], api_key: [] }],
})

