export const getZonesZoneIdSpectrumAppsRoute = createRoute({
  method: 'get',
  path: '/zones/{zone_id}/spectrum/apps',
  tags: ['Spectrum Applications'],
  summary: 'List Spectrum applications',
  description: 'Retrieves a list of currently existing Spectrum applications inside a zone.',
  operationId: 'spectrum-applications-list-spectrum-applications',
  request: {
    params: z.object({
      zone_id: SpectrumConfigZoneIdentifierSchema.openapi({
        param: {
          name: 'zone_id',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/spectrum-config_zone_identifier' },
        },
      }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            schema: {
              description:
                'Page number of paginated results. This parameter is required in order to use other pagination parameters. If included in the query, `result_info` will be present in the response.',
              type: 'number',
              example: 1,
              minimum: 1,
            },
            required: false,
          },
          description:
            'Page number of paginated results. This parameter is required in order to use other pagination parameters. If included in the query, `result_info` will be present in the response.',
          example: 1,
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            schema: {
              description: 'Sets the maximum number of results per page.',
              type: 'number',
              default: 20,
              maximum: 100,
              minimum: 1,
            },
            required: false,
          },
          description: 'Sets the maximum number of results per page.',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .default('asc')
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              description: 'Sets the direction by which results are ordered.',
              type: 'string',
              example: 'desc',
              default: 'asc',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Sets the direction by which results are ordered.',
          example: 'desc',
        }),
      order: z
        .enum(['protocol', 'app_id', 'created_on', 'modified_on', 'dns'])
        .default('dns')
        .exactOptional()
        .openapi({
          param: {
            name: 'order',
            in: 'query',
            schema: {
              description: 'Application field by which results are ordered.',
              type: 'string',
              example: 'protocol',
              default: 'dns',
              enum: ['protocol', 'app_id', 'created_on', 'modified_on', 'dns'],
            },
            required: false,
          },
          description: 'Application field by which results are ordered.',
          example: 'protocol',
        }),
    }),
  },
  responses: {
    200: {
      description: 'List Spectrum applications response.',
      content: { 'application/json': { schema: SpectrumConfigAppConfigCollectionSchema } },
    },
    '4XX': {
      description: 'List Spectrum applications response failure.',
      content: { 'application/json': { schema: SpectrumConfigApiResponseCommonFailureSchema } },
    },
  },
  security: [{ api_token: [] }, { api_email: [], api_key: [] }],
})

